fun rotated(center: PyreonChartPt, x: Double, y: Double, cosA: Double, sinA: Double): PyreonChartPt = PyreonChartPt(x = center.x + x * cosA - y * sinA, y = center.y + x * sinA + y * cosA)

fun patternMarks(p: PyreonChartPattern, bounds: PyreonChartRect): List<PyreonDrawCmd> {
    val out: MutableList<PyreonDrawCmd> = mutableListOf()
    val spacing = if (p.spacing > 2.0) p.spacing else 2.0
    val width = if (p.width > 0.5) p.width else 0.5
    val center = PyreonChartPt(x = bounds.x + (bounds.w).toDouble() / (2.0).toDouble(), y = bounds.y + (bounds.h).toDouble() / (2.0).toDouble())
    val reach = (Math.sqrt((bounds.w * bounds.w + bounds.h * bounds.h).toDouble())).toDouble() / (2.0).toDouble() + spacing
    if (p.kind == "image") {
      return out
    }
    if (p.kind == "dots") {
      var y = bounds.y
      while (y <= bounds.y + bounds.h) {
        var x = bounds.x
        while (x <= bounds.x + bounds.w) {
          out.add(PyreonDrawCmd(kind = "circle", fill = p.color, center = PyreonChartPt(x = x, y = y), radius = (width).toDouble() / (2.0).toDouble()))
          x = x + spacing
        }
        y = y + spacing
      }
      return out
    }
    if (p.kind == "symbols") {
      val angle = ((p.angle ?: 0.0)) * DEG
      val cosA = Math.cos((angle).toDouble())
      val sinA = Math.sin((angle).toDouble())
      val stepY = if (((p.spacingY ?: spacing)) > 2.0) (p.spacingY ?: spacing) else 2.0
      val half = (width).toDouble() / (2.0).toDouble()
      val symbol = (p.symbol ?: "rect")
      val shape = (p.shape ?: listOf())
      val rings = (p.shapeRings ?: listOf())
      var gy = -reach
      while (gy <= reach) {
        var gx = -reach
        while (gx <= reach) {
          val c = rotated(center, gx, gy, cosA, sinA)
          if (symbol == "circle") {
            out.add(PyreonDrawCmd(kind = "circle", fill = p.color, center = c, radius = half))
          } else {
            if (symbol == "triangle") {
              out.add(PyreonDrawCmd(kind = "polygon", fill = p.color, points = listOf(rotated(center, gx, gy - half, cosA, sinA), rotated(center, gx + half, gy + half, cosA, sinA), rotated(center, gx - half, gy + half, cosA, sinA))))
            } else {
              if (symbol == "path") {
                var at = 0
                for (count in rings) {
                  val pts: MutableList<PyreonChartPt> = mutableListOf()
                  var k = 0.0
                  while (k < count && at < shape.length) {
                    val q = shape[at]
                    pts.add(rotated(center, gx + q.x * width, gy + q.y * width, cosA, sinA))
                    at = at + 1
                    k = k + 1.0
                  }
                  if (pts.length >= 3) {
                    out.add(PyreonDrawCmd(kind = "polygon", fill = p.color, points = pts))
                  }
                }
              } else {
                if (symbol == "pin") {
                  val pts: MutableList<PyreonChartPt> = mutableListOf()
                  val headR = half * 0.62
                  val headY = gy - half + headR
                  var t = 0.0
                  while (t <= 1.0) {
                    val a = kotlin.math.PI * (0.8 + 1.4 * t)
                    pts.add(rotated(center, gx + headR * Math.cos((a).toDouble()), headY + headR * Math.sin((a).toDouble()), cosA, sinA))
                    t = t + 0.125
                  }
                  pts.add(rotated(center, gx, gy + half, cosA, sinA))
                  out.add(PyreonDrawCmd(kind = "polygon", fill = p.color, points = pts))
                } else {
                  if (symbol == "arrow") {
                    out.add(PyreonDrawCmd(kind = "polygon", fill = p.color, points = listOf(rotated(center, gx, gy - half, cosA, sinA), rotated(center, gx + half * 0.8, gy + half, cosA, sinA), rotated(center, gx, gy + half * 0.45, cosA, sinA), rotated(center, gx - half * 0.8, gy + half, cosA, sinA))))
                  } else {
                    if (symbol == "diamond") {
                      out.add(PyreonDrawCmd(kind = "polygon", fill = p.color, points = listOf(rotated(center, gx, gy - half, cosA, sinA), rotated(center, gx + half, gy, cosA, sinA), rotated(center, gx, gy + half, cosA, sinA), rotated(center, gx - half, gy, cosA, sinA))))
                    } else {
                      out.add(PyreonDrawCmd(kind = "polygon", fill = p.color, points = listOf(rotated(center, gx - half, gy - half, cosA, sinA), rotated(center, gx + half, gy - half, cosA, sinA), rotated(center, gx + half, gy + half, cosA, sinA), rotated(center, gx - half, gy + half, cosA, sinA))))
                    }
                  }
                }
              }
            }
          }
          gx = gx + spacing
        }
        gy = gy + stepY
      }
      return out
    }
    val base = (p.angle ?: 45.0)
    val sets = if (p.kind == "cross") 2 else 1
    for (set in 0 until sets) {
      val a = (if (set == 0) base else base + 90.0) * DEG
      val cosA = Math.cos((a).toDouble())
      val sinA = Math.sin((a).toDouble())
      var k = -reach
      while (k <= reach) {
        out.add(PyreonDrawCmd(kind = "line", from = rotated(center, -reach, k, cosA, -sinA), to = rotated(center, reach, k, cosA, -sinA), stroke = p.color, width = width))
        k = k + spacing
      }
    }
    return out
  }

fun patternImageCells(p: PyreonChartPattern, bounds: PyreonChartRect, imageW: Double, imageH: Double): List<PyreonChartRect> {
    val out: MutableList<PyreonChartRect> = mutableListOf()
    val repeat = (p.repeat ?: "repeat")
    if (repeat == "grid") {
      val sx = if (p.spacing > 2.0) p.spacing else 2.0
      val sy = if (((p.spacingY ?: sx)) > 2.0) (p.spacingY ?: sx) else 2.0
      val size = if (p.width > 0.5) p.width else 0.5
      val aspect = if (imageW > 0.0 && imageH > 0.0) (imageH).toDouble() / (imageW).toDouble() else 1.0
      val w = if (aspect <= 1.0) size else (size).toDouble() / (aspect).toDouble()
      val h = if (aspect <= 1.0) size * aspect else size
      var y = Math.floor((bounds.y).toDouble() / (sy).toDouble()) * sy
      while (y < bounds.y + bounds.h) {
        var x = Math.floor((bounds.x).toDouble() / (sx).toDouble()) * sx
        while (x < bounds.x + bounds.w) {
          out.add(PyreonChartRect(x = x + ((sx - w)).toDouble() / (2.0).toDouble(), y = y + ((sy - h)).toDouble() / (2.0).toDouble(), w = w, h = h))
          x = x + sx
        }
        y = y + sy
      }
      return out
    }
    if (!(imageW > 0.0) || !(imageH > 0.0)) {
      return out
    }
    val tileX = repeat == "repeat" || repeat == "repeat-x"
    val tileY = repeat == "repeat" || repeat == "repeat-y"
    var y = if (tileY) Math.floor((bounds.y).toDouble() / (imageH).toDouble()) * imageH else 0.0
    val yEnd = if (tileY) bounds.y + bounds.h else 0.5
    while (y < yEnd) {
      var x = if (tileX) Math.floor((bounds.x).toDouble() / (imageW).toDouble()) * imageW else 0.0
      val xEnd = if (tileX) bounds.x + bounds.w else 0.5
      while (x < xEnd) {
        out.add(PyreonChartRect(x = x, y = y, w = imageW, h = imageH))
        x = x + imageW
      }
      y = y + imageH
    }
    return out
  }

fun paletteAt(palette: List<String>, index: Int): String {
    val n = palette.length
    if (n == 0) {
      return DEFAULT_PALETTE[index % DEFAULT_PALETTE.length]
    }
    return palette[index % n]
  }

fun hexDigit(c: Double): Double {
    if (c >= 48.0 && c <= 57.0) {
      return c - 48.0
    }
    if (c >= 97.0 && c <= 102.0) {
      return c - 87.0
    }
    if (c >= 65.0 && c <= 70.0) {
      return c - 55.0
    }
    return 0.0
  }

fun cornerRadii(rect: PyreonChartRect, corners: List<Double>?): List<Double> {
    val c = (corners ?: listOf())
    if (c.length < 4) {
      return listOf(0.0, 0.0, 0.0, 0.0)
    }
    val w = if (rect.w < 0.0) -rect.w else rect.w
    val h = if (rect.h < 0.0) -rect.h else rect.h
    val max = ((if (w < h) w else h)).toDouble() / (2.0).toDouble()
    val out: MutableList<Double> = mutableListOf()
    for (raw in c) {
      val v = if (raw < 0.0) 0.0 else raw
      out.add(if (v > max) max else v)
    }
    return listOf(out[0], out[1], out[2], out[3])
  }

fun hasCorners(radii: List<Double>): Boolean {
    for (r in radii) {
      if (r > 0.0) {
        return true
      }
    }
    return false
  }

fun rectCmd(rect: PyreonChartRect, fill: String, corners: List<Double>?, grad: PyreonChartGradient?, pattern: PyreonChartPattern? = null): PyreonDrawCmd {
    if (pattern == null) {
      if (corners == null && grad == null) {
        return PyreonDrawCmd(kind = "rect", rect = rect, fill = fill)
      }
      if (grad == null) {
        return PyreonDrawCmd(kind = "rect", rect = rect, fill = fill, corners = corners)
      }
      if (corners == null) {
        return PyreonDrawCmd(kind = "rect", rect = rect, fill = fill, grad = grad)
      }
      return PyreonDrawCmd(kind = "rect", rect = rect, fill = fill, corners = corners, grad = grad)
    }
    if (corners == null && grad == null) {
      return PyreonDrawCmd(kind = "rect", rect = rect, fill = fill, pattern = pattern)
    }
    if (grad == null) {
      return PyreonDrawCmd(kind = "rect", rect = rect, fill = fill, corners = corners, pattern = pattern)
    }
    if (corners == null) {
      return PyreonDrawCmd(kind = "rect", rect = rect, fill = fill, grad = grad, pattern = pattern)
    }
    return PyreonDrawCmd(kind = "rect", rect = rect, fill = fill, corners = corners, grad = grad, pattern = pattern)
  }

fun polygonCmd(points: List<PyreonChartPt>, fill: String, grad: PyreonChartGradient?, pattern: PyreonChartPattern? = null): PyreonDrawCmd {
    if (grad == null && pattern == null) {
      return PyreonDrawCmd(kind = "polygon", fill = fill, points = points)
    }
    if (grad == null) {
      return PyreonDrawCmd(kind = "polygon", fill = fill, pattern = pattern, points = points)
    }
    if (pattern == null) {
      return PyreonDrawCmd(kind = "polygon", fill = fill, grad = grad, points = points)
    }
    return PyreonDrawCmd(kind = "polygon", fill = fill, grad = grad, pattern = pattern, points = points)
  }

fun gradientFor(g: SeriesGradient, plot: PyreonChartRect): PyreonChartGradient {
    if (g.shape == "radial") {
      val center = PyreonChartPt(x = plot.x + (plot.w).toDouble() / (2).toDouble(), y = plot.y + (plot.h).toDouble() / (2).toDouble())
      val radius = (Math.max(plot.w, plot.h)).toDouble() / (2).toDouble()
      return PyreonChartGradient(from = center, to = PyreonChartPt(x = center.x + radius, y = center.y), stops = g.stops, radial = true)
    }
    val horizontal = g.direction == "horizontal"
    val from = PyreonChartPt(x = plot.x, y = plot.y)
    val to = if (horizontal) PyreonChartPt(x = plot.x + plot.w, y = plot.y) else PyreonChartPt(x = plot.x, y = plot.y + plot.h)
    return PyreonChartGradient(from = from, to = to, stops = g.stops, radial = false)
  }

fun seriesGradient(g: SeriesGradient?, plot: PyreonChartRect): PyreonChartGradient {
    val src = (g ?: NO_GRADIENT)
    return gradientFor(src, plot)
  }

fun gradientSolid(g: PyreonChartGradient, fallback: String): String {
    if (g.stops.length == 0) {
      return fallback
    }
    return g.stops[0].color
  }

fun plain(v: Double): String {
    val r = Math.round(v)
    if (Math.abs(v - r) < 0.000001) {
      return "${r}"
    }
    return "${(Math.round(v * 1000.0)).toDouble() / (1000.0).toDouble()}"
  }

fun compact(v: Double): String {
    val abs = Math.abs(v)
    val sign = if (v < 0.0) "-" else ""
    if (abs >= 1000000000.0) {
      return "${sign}${trim((abs).toDouble() / (1000000000.0).toDouble())}B"
    }
    if (abs >= 1000000.0) {
      return "${sign}${trim((abs).toDouble() / (1000000.0).toDouble())}M"
    }
    if (abs >= 1000.0) {
      return "${sign}${trim((abs).toDouble() / (1000.0).toDouble())}K"
    }
    return plain(v)
  }

fun trim(v: Double): String {
    val r = (Math.round(v * 10.0)).toDouble() / (10.0).toDouble()
    return if (((r) % 1.0 == 0.0)) "${Math.round(r)}" else "${r}"
  }

fun fixed(places: Int): (Double) -> String {
    val p = Math.max(0, Math.min(10, places))
    val mul = Math.pow((10.0).toDouble(), (p).toDouble())
    return fun(v: Double): String {
      val r = (Math.round(v * mul)).toDouble() / (mul).toDouble()
      if (p == 0) {
        return "${Math.round(r)}"
      }
      val s = "${r}"
      val dot = s.indexOf(".")
      if (dot < 0) {
        return "${s}.${"0".repeat(p)}"
      }
      val decimals = s.length - dot - 1
      return if (decimals >= p) s else "${s}${"0".repeat(p - decimals)}"
    }
  }

fun currency(symbol: String, places: Int = 0): (Double) -> String {
    val f = fixed(places)
    return { v -> (if (v < 0.0) "-${symbol}${f(-v)}" else "${symbol}${f(v)}") }
  }

fun percent(places: Int = 0): (Double) -> String {
    val f = fixed(places)
    return { v -> "${f(v * 100.0)}%" }
  }

fun scaleLinear(d: Domain, r0: Double, r1: Double, v: Double): Double {
    val span = d.max - d.min
    if (span == 0.0) {
      return ((r0 + r1)).toDouble() / (2.0).toDouble()
    }
    if (d.inverse == true) {
      return r1 + (((v - d.min)).toDouble() / (span).toDouble()) * (r0 - r1)
    }
    return r0 + (((v - d.min)).toDouble() / (span).toDouble()) * (r1 - r0)
  }

fun niceStep(raw: Double): Double {
    if (raw <= 0.0) {
      return 1.0
    }
    val mag = Math.pow((10.0).toDouble(), (Math.floor(Math.log10((raw).toDouble()))).toDouble())
    val norm = (raw).toDouble() / (mag).toDouble()
    var m = 10.0
    if (norm <= 1.0) {
      m = 1.0
    } else {
      if (norm <= 2.0) {
        m = 2.0
      } else {
        if (norm <= 5.0) {
          m = 5.0
        }
      }
    }
    return m * mag
  }

fun niceDomain(d: Domain, targetCount: Double): Domain {
    if (d.max == d.min) {
      return Domain(min = d.min - 0.5, max = d.max + 0.5)
    }
    val step = niceStep(((d.max - d.min)).toDouble() / (targetCount).toDouble())
    return Domain(min = Math.floor((d.min).toDouble() / (step).toDouble()) * step, max = Math.ceil((d.max).toDouble() / (step).toDouble()) * step)
  }

fun isFiniteNumber(v: Double): Boolean = v == v && v - v == 0.0

fun makeTicks(d: Domain, r0: Double, r1: Double, count: Double, format: ((Double) -> String)? = null): List<Tick> {
    val fmt = (format ?: ::formatTick)
    val out: MutableList<Tick> = mutableListOf()
    if (count <= 0.0) {
      return out
    }
    if (!isFiniteNumber(d.min) || !isFiniteNumber(d.max)) {
      return out
    }
    val span = d.max - d.min
    if (span <= 0.0) {
      out.add(Tick(value = d.min, pos = scaleLinear(d, r0, r1, d.min), label = fmt(d.min)))
      return out
    }
    val step = niceStep((span).toDouble() / (count).toDouble())
    val first = Math.ceil((d.min).toDouble() / (step).toDouble()) * step
    val maxTicks = 1000
    var i = 0
    while (i < maxTicks) {
      val v = first + step * i
      if (v > d.max + step * 0.000001) {
        break
      }
      out.add(Tick(value = v, pos = scaleLinear(d, r0, r1, v), label = fmt(v)))
      i = i + 1
    }
    return out
  }

fun formatTick(v: Double): String {
    val r = Math.round(v)
    if (Math.abs(v - r) < 0.000001) {
      return "${r}"
    }
    return "${(Math.round(v * 1000.0)).toDouble() / (1000.0).toDouble()}"
  }

fun extent(values: List<Double>): Domain {
    var seen = false
    var lo = 0.0
    var hi = 1.0
    for (v in values) {
      if (!isFiniteNumber(v)) {
        continue
      }
      if (!seen) {
        lo = v
        hi = v
        seen = true
      } else {
        if (v < lo) {
          lo = v
        }
        if (v > hi) {
          hi = v
        }
      }
    }
    if (!seen) {
      return Domain(min = 0.0, max = 1.0)
    }
    return Domain(min = lo, max = hi)
  }

fun scaleLog(d: Domain, r0: Double, r1: Double, v: Double): Double {
    val min = if (d.min <= 0.0) 0.000001 else d.min
    val max = if (d.max <= min) min * 10.0 else d.max
    val `val` = if (v <= 0.0) min else v
    val lo = Math.log10((min).toDouble())
    val hi = Math.log10((max).toDouble())
    return r0 + (((Math.log10((`val`).toDouble()) - lo)).toDouble() / ((hi - lo)).toDouble()) * (r1 - r0)
  }

fun logTicks(d: Domain, r0: Double, r1: Double): List<Tick> {
    val min = if (d.min <= 0.0) 0.000001 else d.min
    val max = if (d.max <= min) min * 10.0 else d.max
    val out: MutableList<Tick> = mutableListOf()
    val from = Math.floor(Math.log10((min).toDouble()))
    val to = Math.ceil(Math.log10((max).toDouble()))
    val limit = 24
    var count = 0
    var e = from
    while (e <= to && count < limit) {
      val v = Math.pow((10.0).toDouble(), (e).toDouble())
      if (v >= min && v <= max) {
        out.add(Tick(value = v, pos = scaleLog(d, r0, r1, v), label = plain(v)))
        count = count + 1
      }
      e = e + 1.0
    }
    return out
  }

fun timeTicks(d: Domain, r0: Double, r1: Double, target: Double, format: ((Double) -> String)? = null): List<Tick> {
    val span = d.max - d.min
    val out: MutableList<Tick> = mutableListOf()
    if (span <= 0.0 || target <= 0) {
      return out
    }
    val steps = listOf(1000.0, 5000.0, 15000.0, 30000.0, MINUTE, MINUTE * 5.0, MINUTE * 15.0, MINUTE * 30.0, HOUR, HOUR * 3.0, HOUR * 6.0, HOUR * 12.0, DAY, DAY * 7.0, DAY * 30.0, DAY * 90.0, DAY * 365.0)
    val ideal = (span).toDouble() / (target).toDouble()
    var step = steps[steps.length - 1]
    for (s in steps) {
      if (s >= ideal) {
        step = s
        break
      }
    }
    val fmt = (format ?: ({ x -> formatTime(x, step) }))
    val first = Math.ceil((d.min).toDouble() / (step).toDouble()) * step
    val limit = 200
    var i = 0
    while (i < limit) {
      val v = first + step * i
      if (v > d.max) {
        break
      }
      out.add(Tick(value = v, pos = scaleLinear(d, r0, r1, v), label = fmt(v)))
      i = i + 1
    }
    return out
  }

fun formatTime(ms: Double, step: Double): String {
    val p2 = { n: Double -> (if (n < 10) "0${kotlin.math.truncate((n).toDouble())}" else "${kotlin.math.truncate((n).toDouble())}") }
    val dayMs = 86400000.0
    val days = Math.floor((ms).toDouble() / (dayMs).toDouble())
    val msOfDay = ms - days * dayMs
    val z = days + 719468.0
    val era = Math.floor((z).toDouble() / (146097.0).toDouble())
    val doe = z - era * 146097.0
    val yoe = Math.floor(((doe - Math.floor((doe).toDouble() / (1460.0).toDouble()) + Math.floor((doe).toDouble() / (36524.0).toDouble()) - Math.floor((doe).toDouble() / (146096.0).toDouble()))).toDouble() / (365.0).toDouble())
    val y0 = yoe + era * 400.0
    val doy = doe - (365.0 * yoe + Math.floor((yoe).toDouble() / (4.0).toDouble()) - Math.floor((yoe).toDouble() / (100.0).toDouble()))
    val mp = Math.floor(((5.0 * doy + 2.0)).toDouble() / (153.0).toDouble())
    val day = doy - Math.floor(((153.0 * mp + 2.0)).toDouble() / (5.0).toDouble()) + 1.0
    val month = if (mp < 10.0) mp + 3.0 else mp - 9.0
    val year = if (month <= 2.0) y0 + 1.0 else y0
    val hours = Math.floor((msOfDay).toDouble() / (3600000.0).toDouble())
    val minutes = Math.floor(((msOfDay - hours * 3600000.0)).toDouble() / (60000.0).toDouble())
    val seconds = Math.floor(((msOfDay - hours * 3600000.0 - minutes * 60000.0)).toDouble() / (1000.0).toDouble())
    if (step >= DAY * 300.0) {
      return "${kotlin.math.truncate((year).toDouble())}"
    }
    if (step >= DAY * 25.0) {
      return "${kotlin.math.truncate((year).toDouble())}-${p2(month)}"
    }
    if (step >= DAY) {
      return "${p2(month)}-${p2(day)}"
    }
    if (step >= MINUTE) {
      return "${p2(hours)}:${p2(minutes)}"
    }
    return "${p2(hours)}:${p2(minutes)}:${p2(seconds)}"
  }

fun logViewTicks(lo: Double, hi: Double, r0: Double, r1: Double, format: ((Double) -> String)? = null): List<Tick> {
    val fmt = (format ?: ::plain)
    val out: MutableList<Tick> = mutableListOf()
    if (!(lo > 0.0) || !(hi > lo)) {
      return out
    }
    val view = Domain(min = 0.0, max = Math.log10(((hi).toDouble() / (lo).toDouble()).toDouble()))
    val from = Math.floor(Math.log10((lo).toDouble()))
    val to = Math.ceil(Math.log10((hi).toDouble()))
    val minors = to - from < 2.0
    val limit = 48
    var count = 0
    var e = from
    while (e <= to && count < limit) {
      val base = Math.pow((10.0).toDouble(), (e).toDouble())
      val mults = if (minors) listOf(1.0, 2.0, 5.0) else listOf(1.0)
      for (m in mults) {
        val v = base * m
        if (v >= lo * 0.999999 && v <= hi * 1.000001 && count < limit) {
          out.add(Tick(value = v, pos = scaleLinear(view, r0, r1, Math.log10(((v).toDouble() / (lo).toDouble()).toDouble())), label = fmt(v)))
          count = count + 1
        }
      }
      e = e + 1.0
    }
    return out
  }

fun smooth(points: List<PyreonChartPt>): List<PyreonChartPt> {
    val n = points.length
    if (n < 3) {
      return points
    }
    val dx: MutableList<Double> = mutableListOf()
    val slope: MutableList<Double> = mutableListOf()
    for (i in 0 until n - 1) {
      val dxi = points[i + 1].x - points[i].x
      dx.add(dxi)
      slope.add(if (dxi == 0.0) 0.0 else ((points[i + 1].y - points[i].y)).toDouble() / (dxi).toDouble())
    }
    val m = mutableListOf(slope[0])
    for (i in 1 until n - 1) {
      val s0 = slope[i - 1]
      val s1 = slope[i]
      if (s0 * s1 <= 0.0) {
        m.add(0.0)
      } else {
        val w0 = 2.0 * dx[i] + dx[i - 1]
        val w1 = dx[i] + 2.0 * dx[i - 1]
        m.add(((w0 + w1)).toDouble() / (((w0).toDouble() / (s0).toDouble() + (w1).toDouble() / (s1).toDouble())).toDouble())
      }
    }
    m.add(slope[n - 2])
    val steps = 16
    val out = mutableListOf(points[0])
    for (i in 0 until n - 1) {
      val p0 = points[i]
      val p1 = points[i + 1]
      val h = dx[i]
      for (k in 1..steps) {
        val t = (k).toDouble() / (steps).toDouble()
        val t2 = t * t
        val t3 = t2 * t
        val h00 = 2.0 * t3 - 3.0 * t2 + 1.0
        val h10 = t3 - 2.0 * t2 + t
        val h01 = -2.0 * t3 + 3.0 * t2
        val h11 = t3 - t2
        out.add(PyreonChartPt(x = p0.x + t * h, y = h00 * p0.y + h10 * h * m[i] + h01 * p1.y + h11 * h * m[i + 1]))
      }
    }
    return out
  }

fun step(points: List<PyreonChartPt>): List<PyreonChartPt> {
    val n = points.length
    if (n < 2) {
      return points
    }
    val out = mutableListOf(points[0])
    for (i in 1 until n) {
      out.add(PyreonChartPt(x = points[i].x, y = points[i - 1].y))
      out.add(points[i])
    }
    return out
  }

fun layoutArcs(slices: List<Slice>): List<ArcGeometry> {
    var total = 0.0
    for (s in slices) {
      if (s.value > 0.0) {
        total = total + s.value
      }
    }
    val out: MutableList<ArcGeometry> = mutableListOf()
    if (total <= 0.0) {
      return out
    }
    var angle = START
    for (s in slices) {
      if (s.value <= 0.0) {
        continue
      }
      val fraction = (s.value).toDouble() / (total).toDouble()
      val sweep = fraction * TAU
      out.add(ArcGeometry(start = angle, end = angle + sweep, mid = angle + (sweep).toDouble() / (2.0).toDouble(), slice = s, fraction = fraction))
      angle = angle + sweep
    }
    return out
  }

fun fitCircle(box: PyreonChartRect): Circle {
    val r = (Math.min(box.w, box.h)).toDouble() / (2.0).toDouble()
    return Circle(center = PyreonChartPt(x = box.x + (box.w).toDouble() / (2.0).toDouble(), y = box.y + (box.h).toDouble() / (2.0).toDouble()), radius = Math.max(0.0, r))
  }

fun pointOnCircle(center: PyreonChartPt, radius: Double, angle: Double): PyreonChartPt = PyreonChartPt(x = center.x + Math.cos((angle).toDouble()) * radius, y = center.y + Math.sin((angle).toDouble()) * radius)

fun arcPolygon(center: PyreonChartPt, outerR: Double, innerR: Double, start: Double, end: Double): List<PyreonChartPt> {
    val sweep = Math.abs(end - start)
    val steps = Math.max((2).toDouble(), Math.ceil(((sweep).toDouble() / (TAU).toDouble()) * 64.0))
    val pts: MutableList<PyreonChartPt> = mutableListOf()
    for (i in 0..Math.floor(steps).toInt()) {
      pts.add(pointOnCircle(center, outerR, start + ((sweep * i)).toDouble() / (steps).toDouble()))
    }
    if (innerR > 0.0) {
      for (i in Math.floor(steps).toInt() downTo 0) {
        pts.add(pointOnCircle(center, innerR, start + ((sweep * i)).toDouble() / (steps).toDouble()))
      }
    } else {
      pts.add(center)
    }
    return pts
  }

fun renderPie(slices: List<Slice>, box: PyreonChartRect, opts: PieOptions): List<PyreonDrawCmd> {
    val __pyDestr1 = fitCircle(box)
    val center = __pyDestr1.center
    val radius = __pyDestr1.radius
    val inner = radius * Math.max(0.0, Math.min(0.95, opts.innerRadius))
    val out: MutableList<PyreonDrawCmd> = mutableListOf()
    val arcs = layoutArcs(slices)
    for (a in arcs) {
      out.add(PyreonDrawCmd(kind = "polygon", fill = a.slice.color, points = arcPolygon(center, radius, inner, a.start, a.end)))
    }
    if (opts.showLabels) {
      for (a in arcs) {
        if (a.fraction < 0.05) {
          continue
        }
        val at = pointOnCircle(center, ((radius + inner)).toDouble() / (2.0).toDouble(), a.mid)
        out.add(PyreonDrawCmd(kind = "text", fill = opts.labelColor, text = "${Math.round(a.fraction * 100.0)}%", at = at, size = opts.fontSize, align = "middle", baseline = "middle"))
      }
    }
    return out
  }

fun hitArc(arcs: List<ArcGeometry>, center: PyreonChartPt, outerR: Double, innerR: Double, p: PyreonChartPt): Int {
    val dx = p.x - center.x
    val dy = p.y - center.y
    val dist = Math.sqrt((dx * dx + dy * dy).toDouble())
    if (dist > outerR || dist < innerR) {
      return -1
    }
    val ang = Math.atan2((dy).toDouble(), (dx).toDouble())
    for (i in 0 until arcs.length) {
      val a = arcs[i]
      var s = a.start
      var e = a.end
      while (e > kotlin.math.PI) {
        s = s - TAU
        e = e - TAU
      }
      val cand = if (ang > e) ang - TAU else ang
      if (cand >= s && cand <= e) {
        return i
      }
    }
    return -1
  }

fun renderGauge(value: Double, box: PyreonChartRect, opts: GaugeOptions): List<PyreonDrawCmd> {
    val __pyDestr1 = fitCircle(box)
    val center = __pyDestr1.center
    val radius = __pyDestr1.radius
    val inner = Math.max(0.0, radius - opts.thickness)
    val span = opts.max - opts.min
    val t = if (span <= 0.0) 0.0 else Math.max(0.0, Math.min(1.0, ((value - opts.min)).toDouble() / (span).toDouble()))
    val start = kotlin.math.PI - ((opts.sweep - kotlin.math.PI)).toDouble() / (2.0).toDouble()
    return listOf(PyreonDrawCmd(kind = "polygon", fill = opts.trackColor, points = arcPolygon(center, radius, inner, start, start + opts.sweep)), PyreonDrawCmd(kind = "polygon", fill = opts.valueColor, points = arcPolygon(center, radius, inner, start, start + opts.sweep * t)))
  }

fun radarAngles(count: Int): List<Double> {
    val out: MutableList<Double> = mutableListOf()
    if (count <= 0) {
      return out
    }
    for (i in 0 until count) {
      out.add(RADAR_START + ((kotlin.math.PI * 2.0 * i)).toDouble() / (count).toDouble())
    }
    return out
  }

fun radarPolygon(values: List<Double>, axes: List<RadarAxis>, center: PyreonChartPt, radius: Double): List<PyreonChartPt> {
    val n = Math.min(values.length, axes.length)
    val angles = radarAngles(n)
    val out: MutableList<PyreonChartPt> = mutableListOf()
    for (i in 0 until n) {
      val axisMax = axes[i].max
      val t = if (axisMax <= 0.0) 0.0 else Math.max(0.0, Math.min(1.0, (values[i]).toDouble() / (axisMax).toDouble()))
      out.add(pointOnCircle(center, radius * t, angles[i]))
    }
    return out
  }

fun renderRadar(axes: List<RadarAxis>, series: List<RadarSeries>, box: PyreonChartRect, opts: RadarOptions): List<PyreonDrawCmd> {
    val out: MutableList<PyreonDrawCmd> = mutableListOf()
    val n = axes.length
    if (n < 3) {
      return out
    }
    val pad = if (opts.showLabels) opts.fontSize * 3.0 else 0.0
    val radius = Math.max(0.0, (Math.min(box.w, box.h)).toDouble() / (2.0).toDouble() - pad)
    val center = PyreonChartPt(x = box.x + (box.w).toDouble() / (2.0).toDouble(), y = box.y + (box.h).toDouble() / (2.0).toDouble())
    val angles = radarAngles(n)
    for (r in 1..opts.rings) {
      val rr = ((radius * r)).toDouble() / (opts.rings).toDouble()
      val ring: MutableList<PyreonChartPt> = mutableListOf()
      for (a in angles) {
        ring.add(pointOnCircle(center, rr, a))
      }
      ring.add(ring[0])
      out.add(PyreonDrawCmd(kind = "polyline", stroke = opts.gridColor, width = 1.0, points = ring))
    }
    for (a in angles) {
      out.add(PyreonDrawCmd(kind = "line", from = center, to = pointOnCircle(center, radius, a), stroke = opts.gridColor, width = 1.0))
    }
    for (s in series) {
      val poly = radarPolygon(s.values, axes, center, radius)
      if (poly.length < 3) {
        continue
      }
      out.add(PyreonDrawCmd(kind = "polygon", fill = withAlpha(s.color, s.fillAlpha), points = poly))
      val closed: MutableList<PyreonChartPt> = mutableListOf()
      for (p in poly) {
        closed.add(p)
      }
      closed.add(poly[0])
      out.add(PyreonDrawCmd(kind = "polyline", stroke = s.color, width = 2.0, points = closed))
    }
    if (opts.showLabels) {
      for (i in 0 until n) {
        val at = pointOnCircle(center, radius + opts.fontSize * 1.2, angles[i])
        val dx = at.x - center.x
        val align = if (Math.abs(dx) < 1.0) "middle" else if (dx > 0.0) "start" else "end"
        out.add(PyreonDrawCmd(kind = "text", fill = opts.labelColor, text = axes[i].label, at = at, size = opts.fontSize, align = align, baseline = "middle"))
      }
    }
    return out
  }

fun withAlpha(color: String, alpha: Double): String {
    val a = Math.max(0.0, Math.min(1.0, alpha))
    if (color.startsWith("rgb(") && color.endsWith(")")) {
      return "rgba(${color.drop(4).take(maxOf(0, (color.length - 1) - (4)))}, ${a})"
    }
    if (!color.startsWith("#")) {
      return color
    }
    val hex = color.drop(1)
    val code = fun(c: Double): Double {
      if (c >= 48.0 && c <= 57.0) {
        return c - 48.0
      }
      if (c >= 97.0 && c <= 102.0) {
        return c - 87.0
      }
      if (c >= 65.0 && c <= 70.0) {
        return c - 55.0
      }
      return 0.0
    }
    val pair = { at: Double -> code(hex[(at).toInt()].code.toDouble()) * 16.0 + code(hex[(at + 1).toInt()].code.toDouble()) }
    val single = { at: Double -> code(hex[(at).toInt()].code.toDouble()) * 17.0 }
    if (hex.length == 3) {
      return "rgba(${single(0.0)}, ${single(1.0)}, ${single(2.0)}, ${a})"
    }
    if (hex.length == 6) {
      return "rgba(${pair(0.0)}, ${pair(2.0)}, ${pair(4.0)}, ${a})"
    }
    return color
  }

fun hitRadarIndex(axes: List<RadarAxis>, series: List<RadarSeries>, box: PyreonChartRect, opts: RadarOptions, px: Double, py: Double, tolerance: Double = 8.0): RadarHitIndex {
    val miss = RadarHitIndex(series = -1, axis = -1)
    val n = axes.length
    if (n < 3) {
      return miss
    }
    val pad = if (opts.showLabels) opts.fontSize * 3.0 else 0.0
    val radius = Math.max(0.0, (Math.min(box.w, box.h)).toDouble() / (2.0).toDouble() - pad)
    val center = PyreonChartPt(x = box.x + (box.w).toDouble() / (2.0).toDouble(), y = box.y + (box.h).toDouble() / (2.0).toDouble())
    var best = tolerance * tolerance
    var hit = miss
    for (si in 0 until series.length) {
      val pts = radarPolygon(series[si].values, axes, center, radius)
      for (ai in 0 until pts.length) {
        val dx = pts[ai].x - px
        val dy = pts[ai].y - py
        val d = dx * dx + dy * dy
        if (d <= best) {
          best = d
          hit = RadarHitIndex(series = si, axis = ai)
        }
      }
    }
    return hit
  }

fun computeLayout(cfg: LayoutConfig, measure: (String, Double) -> Double): PlotLayout {
    val padTop = 8.0
    val padRight = 12.0
    val labelGap = 6.0
    val tickLen = 4.0
    val titleH = cfg.fontSize + labelGap
    val isLog = cfg.yLog == true
    val logMin = (cfg.yLogMin ?: 1.0)
    val logMax = (cfg.yLogMax ?: 10.0)
    val valueTicksY = { r0: Double, r1: Double -> if (isLog) logViewTicks(logMin, logMax, if (cfg.yDomain.inverse == true) r1 else r0, if (cfg.yDomain.inverse == true) r0 else r1, cfg.yFormat) else if (cfg.yTime == true) timeTicks(cfg.yDomain, r0, r1, cfg.yTickCount, cfg.yFormat) else makeTicks(cfg.yDomain, r0, r1, cfg.yTickCount, cfg.yFormat) }
    val provisionalLabels = if (cfg.horizontal == true) if (cfg.showYAxis) cfg.categories else listOf() else if (cfg.showYAxis) valueTicksY(cfg.height, 0.0).map({ t -> t.label }) else listOf()
    var widest = 0.0
    for (label in provisionalLabels) {
      var w = measure(label, cfg.fontSize)
      if (w > widest) {
        widest = w
      }
    }
    val yTitleH = if (cfg.yTitle != null && cfg.yTitle != "" && cfg.showYAxis) titleH else 0.0
    val yBand = (if (cfg.showYAxis) widest + labelGap + tickLen + ((cfg.yOffset ?: 0.0)) else 0.0) + yTitleH
    val xTitleH = if (cfg.xTitle != null && cfg.xTitle != "" && cfg.showXAxis) titleH else 0.0
    val y2dom = (cfg.y2Domain ?: Domain(min = 0.0, max = 1.0))
    val hasY2 = cfg.y2Domain != null && cfg.horizontal != true && cfg.showYAxis
    var widest2 = 0.0
    if (hasY2) {
      for (label in makeTicks(y2dom, cfg.height, 0.0, cfg.yTickCount, cfg.y2Format).map({ t -> t.label })) {
        var w = measure(label, cfg.fontSize)
        if (w > widest2) {
          widest2 = w
        }
      }
    }
    val y2TitleH = if (hasY2 && cfg.y2Title != null && cfg.y2Title != "") titleH else 0.0
    val yRight = cfg.yRight == true && !hasY2 && cfg.horizontal != true
    val leftBase = if (yRight) padRight else yBand
    val rightBase = if (yRight) yBand else (if (hasY2) widest2 + labelGap + tickLen + ((cfg.y2Offset ?: 0.0)) else padRight) + y2TitleH
    var leftExtra = 0.0
    var rightExtra = 0.0
    if (cfg.horizontal != true && cfg.showYAxis) {
      for (a in (cfg.extraYAxes ?: listOf())) {
        var w = 0.0
        for (tk in makeTicks((a.domain ?: Domain(min = 0.0, max = 1.0)), cfg.height, 0.0, cfg.yTickCount, null)) {
          val lw = measure(tk.label, cfg.fontSize)
          if (lw > w) {
            w = lw
          }
        }
        val band = ((a.offset ?: 0.0)) + w + labelGap + tickLen + (if (a.title != null && a.title != "") titleH else 0.0)
        if (a.side == "left") {
          if (band > leftExtra) {
            leftExtra = band
          }
        } else {
          if (band > rightExtra) {
            rightExtra = band
          }
        }
      }
    }
    val left = if (leftBase > leftExtra) leftBase else leftExtra
    val right = if (rightBase > rightExtra) rightBase else rightExtra
    val provisionalW = Math.max(0.0, cfg.width - left - right)
    val mode = (cfg.xLabels ?: "auto")
    var rotate = 0.0
    var every = 1
    var slantH = 0.0
    if (cfg.showXAxis && cfg.horizontal != true) {
      val xLabels = if (cfg.categories.length > 0) cfg.categories else (if (cfg.xTime == true) timeTicks(cfg.xDomain, 0.0, provisionalW, cfg.xTickCount, cfg.xFormat) else makeTicks(cfg.xDomain, 0.0, provisionalW, cfg.xTickCount, cfg.xFormat)).map({ t -> t.label })
      var need = 0.0
      var widestX = 0.0
      for (label in xLabels) {
        var w = measure(label, cfg.fontSize)
        need = need + w + labelGap
        if (w > widestX) {
          widestX = w
        }
      }
      val overflow = need > provisionalW && xLabels.length > 1
      val wantRotate = mode == "rotate" || (mode == "auto" && overflow && cfg.categories.length > 0)
      if (wantRotate && xLabels.length > 0) {
        rotate = -45.0
        slantH = (widestX + cfg.fontSize) * 0.7071 - cfg.fontSize
        if (slantH < 0.0) {
          slantH = 0.0
        }
        val bandW = (provisionalW).toDouble() / (xLabels.length).toDouble()
        val perLabel = cfg.fontSize * 1.3
        if (bandW < perLabel && bandW > 0.0) {
          every = ceilRatio(perLabel, bandW)
        }
      } else {
        if (mode != "all" && overflow && (mode == "thin" || mode == "auto")) {
          every = ceilRatio(need, provisionalW)
        }
      }
    }
    val xBand = (if (cfg.showXAxis) cfg.fontSize + labelGap + tickLen + slantH + ((cfg.xOffset ?: 0.0)) else 0.0) + xTitleH
    val xTop = cfg.xTop == true && cfg.horizontal != true
    val hasX2 = (((cfg.x2Labels ?: listOf())).length > 0 || cfg.x2Domain != null) && cfg.showXAxis && cfg.horizontal != true
    val x2Band = if (hasX2) cfg.fontSize + labelGap + tickLen + (if (cfg.x2Title != null && cfg.x2Title != "") titleH else 0.0) else padTop
    val top = if (xTop) xBand else x2Band
    val bottom = if (xTop) x2Band else xBand
    val gutters = Gutters(left = left, right = right, top = top, bottom = bottom)
    val plot = PyreonChartRect(x = left, y = top, w = Math.max(0.0, cfg.width - left - right), h = Math.max(0.0, cfg.height - top - bottom))
    if (cfg.horizontal == true) {
      val yTicks = if (cfg.showYAxis) bandTicksY(cfg.categories, plot) else listOf()
      val xTicks = if (cfg.showXAxis) makeTicks(cfg.yDomain, plot.x, plot.x + plot.w, cfg.yTickCount, cfg.yFormat) else listOf()
      var yEvery = 1
      val nCat = cfg.categories.length
      if (nCat > 0 && plot.h > 0.0) {
        val bandH = (plot.h).toDouble() / (nCat).toDouble()
        val perLabel = cfg.fontSize + 2.0
        if (bandH < perLabel) {
          yEvery = ceilRatio(perLabel, bandH)
        }
      }
      return PlotLayout(plot = plot, xTicks = xTicks, yTicks = yTicks, y2Ticks = listOf(), xDomainUsed = cfg.xDomain, xLabelRotate = 0.0, xLabelEvery = 1, yLabelEvery = yEvery, gutters = gutters, extraTicks = listOf(), x2Ticks = listOf())
    }
    val yTicks = if (cfg.showYAxis) valueTicksY(plot.y + plot.h, plot.y) else listOf()
    val xTicks = if (cfg.showXAxis) if (cfg.categories.length > 0) bandTicks(cfg.categories, plot) else if (cfg.xTime == true) timeTicks(cfg.xDomain, plot.x, plot.x + plot.w, cfg.xTickCount, cfg.xFormat) else makeTicks(cfg.xDomain, plot.x, plot.x + plot.w, cfg.xTickCount, cfg.xFormat) else listOf()
    val y2Ticks = if (hasY2) makeTicks(y2dom, plot.y + plot.h, plot.y, cfg.yTickCount, cfg.y2Format) else listOf()
    val extraTicks: MutableList<ExtraTick> = mutableListOf()
    if (cfg.showYAxis) {
      var ai = 0.0
      for (a in (cfg.extraYAxes ?: listOf())) {
        for (tk in makeTicks((a.domain ?: Domain(min = 0.0, max = 1.0)), plot.y + plot.h, plot.y, cfg.yTickCount, null)) {
          extraTicks.add(ExtraTick(axis = ai, pos = tk.pos, label = tk.label))
        }
        ai = ai + 1.0
      }
    }
    val x2Ticks = if (hasX2 && cfg.x2Domain != null) makeTicks((cfg.x2Domain ?: Domain(min = 0.0, max = 1.0)), plot.x, plot.x + plot.w, cfg.xTickCount, null) else listOf()
    return PlotLayout(plot = plot, xTicks = xTicks, yTicks = yTicks, y2Ticks = y2Ticks, xDomainUsed = cfg.xDomain, xLabelRotate = rotate, xLabelEvery = every, yLabelEvery = 1, gutters = gutters, extraTicks = extraTicks, x2Ticks = x2Ticks)
  }

fun ceilRatio(need: Double, room: Double): Int {
    if (!(room > 0.0)) {
      return 1
    }
    var every = 1
    var acc = room
    while (acc < need && every < 200) {
      every = every + 1
      acc = acc + room
    }
    return every
  }

fun bandTicksY(categories: List<String>, plot: PyreonChartRect): List<Tick> {
