        out.add(StackSegment(rect = PyreonChartRect(x = if (xStart < xEnd) xStart else xEnd, y = plot.y + band * i + ((band - bh)).toDouble() / (2.0).toDouble(), w = (Math.abs(xEnd - xStart)).toDouble(), h = bh), seriesIndex = s, datumIndex = i, value = v))
        acc = acc + v
      }
    }
    return out
  }

fun layoutGroupedBarsH(seriesValues: List<List<Double>>, plot: PyreonChartRect, vDomain: Domain, gapRatio: Double): List<StackSegment> {
    val out: MutableList<StackSegment> = mutableListOf()
    val k = seriesValues.length
    if (k == 0) {
      return out
    }
    var n = 0
    for (s in seriesValues) {
      if (s.length > n) {
        n = s.length
      }
    }
    if (n == 0) {
      return out
    }
    val ratio = if (gapRatio < 0.0) 0.0 else if (gapRatio > 0.9) 0.9 else gapRatio
    val band = (plot.h).toDouble() / (n).toDouble()
    val groupH = band * (1.0 - ratio)
    val barH = (groupH).toDouble() / (k).toDouble()
    val zero = if (vDomain.min < 0.0 && vDomain.max > 0.0) 0.0 else vDomain.min
    val zeroX = scaleLinear(vDomain, plot.x, plot.x + plot.w, zero)
    for (i in 0 until n) {
      val gy = plot.y + band * i + ((band - groupH)).toDouble() / (2.0).toDouble()
      for (s in 0 until k) {
        val raw = (seriesValues[s][i] ?: 0.0)
        val v = if (raw == raw) raw else zero
        val vx = scaleLinear(vDomain, plot.x, plot.x + plot.w, v)
        out.add(StackSegment(rect = PyreonChartRect(x = if (vx < zeroX) vx else zeroX, y = gy + barH * s, w = Math.abs(vx - zeroX), h = barH), seriesIndex = s, datumIndex = i, value = v))
      }
    }
    return out
  }

fun stackCumulative(seriesValues: List<List<Double>>): List<List<Double>> {
    val out: MutableList<List<Double>> = mutableListOf()
    var n = 0
    for (s in seriesValues) {
      if (s.length > n) {
        n = s.length
      }
    }
    val acc: MutableList<Double> = mutableListOf()
    for (i in 0 until n) {
      acc.add(0.0)
    }
    for (s in seriesValues) {
      val row: MutableList<Double> = mutableListOf()
      for (i in 0 until n) {
        val v = if (i < s.length) s[i] else 0.0
        if (v > 0.0) {
          acc[i] = acc[i] + v
        }
        row.add(acc[i])
      }
      out.add(row)
    }
    return out
  }

fun stackHasNegatives(seriesValues: List<List<Double>>): Boolean {
    for (s in seriesValues) {
      for (v in s) {
        if (v < 0.0) {
          return true
        }
      }
    }
    return false
  }

fun stackedExtent(seriesValues: List<List<Double>>): Domain {
    var n = 0
    for (s in seriesValues) {
      if (s.length > n) {
        n = s.length
      }
    }
    var max = 0.0
    for (i in 0 until n) {
      var sum = 0.0
      for (s in seriesValues) {
        val v = (s[i] ?: 0.0)
        if (v > 0.0) {
          sum = sum + v
        }
      }
      if (sum > max) {
        max = sum
      }
    }
    return Domain(min = 0.0, max = if (max == 0.0) 1.0 else max)
  }

fun layoutGroupedBars(seriesValues: List<List<Double>>, plot: PyreonChartRect, yDomain: Domain, gapRatio: Double): List<StackSegment> {
    val out: MutableList<StackSegment> = mutableListOf()
    val k = seriesValues.length
    if (k == 0) {
      return out
    }
    var n = 0
    for (s in seriesValues) {
      if (s.length > n) {
        n = s.length
      }
    }
    if (n == 0) {
      return out
    }
    val ratio = if (gapRatio < 0.0) 0.0 else if (gapRatio > 0.9) 0.9 else gapRatio
    val band = (plot.w).toDouble() / (n).toDouble()
    val groupW = band * (1.0 - ratio)
    val barW = (groupW).toDouble() / (k).toDouble()
    val zero = if (yDomain.min < 0.0 && yDomain.max > 0.0) 0.0 else yDomain.min
    val zeroY = scaleLinear(yDomain, plot.y + plot.h, plot.y, zero)
    for (i in 0 until n) {
      val gx = plot.x + band * i + ((band - groupW)).toDouble() / (2.0).toDouble()
      for (s in 0 until k) {
        val raw = (seriesValues[s][i] ?: 0.0)
        val v = if (isFiniteNumber(raw)) raw else zero
        val vy = scaleLinear(yDomain, plot.y + plot.h, plot.y, v)
        out.add(StackSegment(rect = PyreonChartRect(x = gx + barW * s, y = if (vy < zeroY) vy else zeroY, w = barW, h = Math.abs(zeroY - vy)), seriesIndex = s, datumIndex = i, value = v))
      }
    }
    return out
  }

fun layoutScatter(xs: List<Double>, ys: List<Double>, plot: PyreonChartRect, xDomain: Domain, yDomain: Domain): List<PyreonChartPt> {
    val n = Math.min(xs.length, ys.length)
    val out: MutableList<PyreonChartPt> = mutableListOf()
    for (i in 0 until n) {
      out.add(PyreonChartPt(x = scaleLinear(xDomain, plot.x, plot.x + plot.w, xs[i]), y = scaleLinear(yDomain, plot.y + plot.h, plot.y, ys[i])))
    }
    return out
  }

fun normalizeStack(seriesValues: List<List<Double>>): List<List<Double>> {
    var n = 0
    for (s in seriesValues) {
      if (s.length > n) {
        n = s.length
      }
    }
    val totals: MutableList<Double> = mutableListOf()
    for (i in 0 until n) {
      var sum = 0.0
      for (s in seriesValues) {
        val v = if (i < s.length) s[i] else 0.0
        if (v > 0.0) {
          sum = sum + v
        }
      }
      totals.add(sum)
    }
    val out: MutableList<List<Double>> = mutableListOf()
    for (s in seriesValues) {
      val row: MutableList<Double> = mutableListOf()
      for (i in 0 until s.length) {
        val v = s[i]
        val total = totals[i]
        row.add(if (total > 0.0) (v).toDouble() / (total).toDouble() else if (isFiniteNumber(v)) 0.0 else v)
      }
      out.add(row)
    }
    return out
  }

fun layoutWaterfall(values: List<Double>, plot: PyreonChartRect, yDomain: Domain, gapRatio: Double): List<WaterfallStep> {
    val out: MutableList<WaterfallStep> = mutableListOf()
    val n = values.length
    if (n == 0) {
      return out
    }
    val ratio = if (gapRatio < 0.0) 0.0 else if (gapRatio > 0.9) 0.9 else gapRatio
    val band = (plot.w).toDouble() / (n).toDouble()
    val bw = band * (1.0 - ratio)
    var acc = 0.0
    for (i in 0 until n) {
      val v = values[i]
      if (!isFiniteNumber(v)) {
        continue
      }
      val start = acc
      val end = acc + v
      val y0 = scaleLinear(yDomain, plot.y + plot.h, plot.y, start)
      val y1 = scaleLinear(yDomain, plot.y + plot.h, plot.y, end)
      out.add(WaterfallStep(rect = PyreonChartRect(x = plot.x + band * i + ((band - bw)).toDouble() / (2.0).toDouble(), y = if (y0 < y1) y0 else y1, w = bw, h = (Math.abs(y1 - y0)).toDouble()), datumIndex = i, value = v, start = start, end = end))
      acc = end
    }
    return out
  }

fun waterfallExtent(values: List<Double>): Domain {
    var acc = 0.0
    var lo = 0.0
    var hi = 0.0
    for (v in values) {
      if (!isFiniteNumber(v)) {
        continue
      }
      acc = acc + v
      if (acc < lo) {
        lo = acc
      }
      if (acc > hi) {
        hi = acc
      }
    }
    return Domain(min = lo, max = if (hi == lo) lo + 1.0 else hi)
  }

fun symbolPoints(cell: PyreonChartRect, symbol: String): List<PyreonChartPt> {
    if (symbol == "circle") {
      val r = ((if (cell.w < cell.h) cell.w else cell.h)).toDouble() / (2.0).toDouble()
      val cx = cell.x + (cell.w).toDouble() / (2.0).toDouble()
      val cy = cell.y + (cell.h).toDouble() / (2.0).toDouble()
      val pts: MutableList<PyreonChartPt> = mutableListOf()
      for (i in 0 until POLYGON_CIRCLE_SIDES) {
        val a = ((kotlin.math.PI * 2.0 * i)).toDouble() / (POLYGON_CIRCLE_SIDES).toDouble()
        pts.add(PyreonChartPt(x = cx + Math.cos((a).toDouble()) * r, y = cy + Math.sin((a).toDouble()) * r))
      }
      return pts
    }
    if (symbol == "diamond") {
      return listOf(PyreonChartPt(x = cell.x + (cell.w).toDouble() / (2.0).toDouble(), y = cell.y), PyreonChartPt(x = cell.x + cell.w, y = cell.y + (cell.h).toDouble() / (2.0).toDouble()), PyreonChartPt(x = cell.x + (cell.w).toDouble() / (2.0).toDouble(), y = cell.y + cell.h), PyreonChartPt(x = cell.x, y = cell.y + (cell.h).toDouble() / (2.0).toDouble()))
    }
    if (symbol == "triangle") {
      return listOf(PyreonChartPt(x = cell.x + (cell.w).toDouble() / (2.0).toDouble(), y = cell.y), PyreonChartPt(x = cell.x + cell.w, y = cell.y + cell.h), PyreonChartPt(x = cell.x, y = cell.y + cell.h))
    }
    return listOf(PyreonChartPt(x = cell.x, y = cell.y), PyreonChartPt(x = cell.x + cell.w, y = cell.y), PyreonChartPt(x = cell.x + cell.w, y = cell.y + cell.h), PyreonChartPt(x = cell.x, y = cell.y + cell.h))
  }

fun rotatePoints(points: List<PyreonChartPt>, center: PyreonChartPt, degrees: Double): List<PyreonChartPt> {
    if (degrees == 0.0) {
      return points
    }
    val a = ((degrees * kotlin.math.PI)).toDouble() / (180.0).toDouble()
    val c = Math.cos((a).toDouble())
    val s = Math.sin((a).toDouble())
    val out: MutableList<PyreonChartPt> = mutableListOf()
    for (p in points) {
      val dx = p.x - center.x
      val dy = p.y - center.y
      out.add(PyreonChartPt(x = center.x + dx * c - dy * s, y = center.y + dx * s + dy * c))
    }
    return out
  }

fun clipPolygonToRect(points: List<PyreonChartPt>, rect: PyreonChartRect): List<PyreonChartPt> {
    var current = points
    val x0 = rect.x
    val x1 = rect.x + rect.w
    val y0 = rect.y
    val y1 = rect.y + rect.h
    for (edge in 0 until 4) {
      if (current.length == 0) {
        return current
      }
      val next: MutableList<PyreonChartPt> = mutableListOf()
      for (i in 0 until current.length) {
        val p = current[i]
        val q = current[(i + 1) % current.length]
        val pIn = insideEdge(p, edge, x0, x1, y0, y1)
        val qIn = insideEdge(q, edge, x0, x1, y0, y1)
        if (pIn && qIn) {
          next.add(q)
        } else {
          if (pIn && !qIn) {
            next.add(intersectEdge(p, q, edge, x0, x1, y0, y1))
          } else {
            if (!pIn && qIn) {
              next.add(intersectEdge(p, q, edge, x0, x1, y0, y1))
              next.add(q)
            }
          }
        }
      }
      current = next
    }
    return current
  }

fun insideEdge(p: PyreonChartPt, edge: Int, x0: Double, x1: Double, y0: Double, y1: Double): Boolean {
    if (edge == 0) {
      return p.x >= x0
    }
    if (edge == 1) {
      return p.x <= x1
    }
    if (edge == 2) {
      return p.y >= y0
    }
    return p.y <= y1
  }

fun intersectEdge(p: PyreonChartPt, q: PyreonChartPt, edge: Int, x0: Double, x1: Double, y0: Double, y1: Double): PyreonChartPt {
    if (edge == 0 || edge == 1) {
      val x = if (edge == 0) x0 else x1
      val t = if (q.x == p.x) 0.0 else ((x - p.x)).toDouble() / ((q.x - p.x)).toDouble()
      return PyreonChartPt(x = x, y = p.y + (q.y - p.y) * t)
    }
    val y = if (edge == 2) y0 else y1
    val t = if (q.y == p.y) 0.0 else ((y - p.y)).toDouble() / ((q.y - p.y)).toDouble()
    return PyreonChartPt(x = p.x + (q.x - p.x) * t, y = y)
  }

fun symbolCommands(cell: PyreonChartRect, b: PictorialBar, clipTo: PyreonChartRect?): List<PyreonDrawCmd> {
    val out: MutableList<PyreonDrawCmd> = mutableListOf()
    val needsPolygon = b.symbol != "rect" || b.rotate != 0.0 || clipTo != null
    val nudged = PyreonChartRect(x = cell.x + b.offsetX, y = cell.y + b.offsetY, w = cell.w, h = cell.h)
    if (b.symbol == "circle" && b.rotate == 0.0 && clipTo == null) {
      val r = ((if (nudged.w < nudged.h) nudged.w else nudged.h)).toDouble() / (2.0).toDouble()
      out.add(PyreonDrawCmd(kind = "circle", fill = b.fill, center = PyreonChartPt(x = nudged.x + (nudged.w).toDouble() / (2.0).toDouble(), y = nudged.y + (nudged.h).toDouble() / (2.0).toDouble()), radius = r))
      return out
    }
    if (!needsPolygon) {
      out.add(PyreonDrawCmd(kind = "rect", rect = nudged, fill = b.fill))
      return out
    }
    var pts = symbolPoints(nudged, b.symbol)
    if (b.rotate != 0.0) {
      pts = rotatePoints(pts, PyreonChartPt(x = nudged.x + (nudged.w).toDouble() / (2.0).toDouble(), y = nudged.y + (nudged.h).toDouble() / (2.0).toDouble()), b.rotate)
    }
    if (clipTo != null) {
      pts = clipPolygonToRect(pts, clipTo)
    }
    if (pts.length >= 3) {
      out.add(PyreonDrawCmd(kind = "polygon", fill = b.fill, points = pts))
    }
    return out
  }

fun pictorialCommands(b: PictorialBar): List<PyreonDrawCmd> {
    val out: MutableList<PyreonDrawCmd> = mutableListOf()
    val bar = b.bar
    val barLength = if (b.horizontal) bar.w else bar.h
    val unit = if (b.horizontal) bar.h else bar.w
    val runLength = if (b.hasBounding && isFiniteNumber(b.boundingLength)) b.boundingLength else barLength
    val clipTo = if (b.clip) bar else null
    var shift = 0.0
    if (b.position == "end") {
      shift = barLength - runLength
    } else {
      if (b.position == "center") {
        shift = ((barLength - runLength)).toDouble() / (2.0).toDouble()
      }
    }
    val cellAt = { from: Double, length: Double -> if (b.horizontal) PyreonChartRect(x = bar.x + from, y = bar.y, w = length, h = unit) else PyreonChartRect(x = bar.x, y = bar.y + bar.h - from - length, w = unit, h = length) }
    if (!b.repeat) {
      val cell = cellAt(shift, runLength)
      if (!b.clip && (shift < 0.0 || shift + runLength > barLength + 0.001)) {
        for (c in symbolCommands(cell, b, null)) {
          out.add(c)
        }
        return out
      }
      for (c in symbolCommands(cell, b, clipTo)) {
        out.add(c)
      }
      return out
    }
    val step = unit + b.margin
    if (unit <= 0.0 || step <= 0.0) {
      return out
    }
    var from = shift
    for (k in 0 until 400) {
      val end = from + unit
      if (from >= shift + runLength - 0.001 && !b.clip) {
        break
      }
      if (from >= shift + runLength - 0.001) {
        break
      }
      val overRun = end > shift + runLength + 0.001
      if (overRun && !b.clip) {
        break
      }
      val overBar = end > barLength + 0.001 || from < -0.001
      if (overBar && !b.clip) {
        break
      }
      val length = if (overRun) shift + runLength - from else unit
      val cell = cellAt(from, unit)
      val clipRect = if (b.clip) (if (overRun) intersectRect(bar, cellAt(from, length)) else clipTo) else null
      for (c in symbolCommands(cell, b, clipRect)) {
        out.add(c)
      }
      from = from + step
    }
    return out
  }

fun intersectRect(a: PyreonChartRect, c: PyreonChartRect): PyreonChartRect {
    val x0 = if (a.x > c.x) a.x else c.x
    val y0 = if (a.y > c.y) a.y else c.y
    val x1 = if (a.x + a.w < c.x + c.w) a.x + a.w else c.x + c.w
    val y1 = if (a.y + a.h < c.y + c.h) a.y + a.h else c.y + c.h
    return PyreonChartRect(x = x0, y = y0, w = if (x1 - x0 > 0.0) x1 - x0 else 0.0, h = if (y1 - y0 > 0.0) y1 - y0 else 0.0)
  }

fun arcSweep(startAngle: Double, endAngle: Double, clockwise: Boolean): PyreonChartPt {
    val from = if (clockwise) startAngle else endAngle
    var to = if (clockwise) endAngle else startAngle
    if (to < from) {
      to = to + FULL_TURN * Math.ceil(((from - to)).toDouble() / (FULL_TURN).toDouble())
    }
    if (to - from > FULL_TURN) {
      to = from + FULL_TURN
    }
    return PyreonChartPt(x = from, y = to)
  }

fun bezierPoints(control: List<PyreonChartPt>): List<PyreonChartPt> {
    val out: MutableList<PyreonChartPt> = mutableListOf()
    if (control.length < 3) {
      return control
    }
    val cubic = control.length >= 4
    val p0 = control[0]
    val c1 = control[1]
    val c2 = if (cubic) control[2] else control[1]
    val p1 = if (cubic) control[3] else control[2]
    for (i in 0..BEZIER_STEPS) {
      val t = (i).toDouble() / (BEZIER_STEPS).toDouble()
      val u = 1.0 - t
      val x = u * u * u * p0.x + 3.0 * u * u * t * c1.x + 3.0 * u * t * t * c2.x + t * t * t * p1.x
      val y = u * u * u * p0.y + 3.0 * u * u * t * c1.y + 3.0 * u * t * t * c2.y + t * t * t * p1.y
      out.add(PyreonChartPt(x = x, y = y))
    }
    return out
  }

fun graphicElementCommands(e: GraphicElement): List<PyreonDrawCmd> {
    val out: MutableList<PyreonDrawCmd> = mutableListOf()
    val at = { p: PyreonChartPt -> (PyreonChartPt(x = e.x + p.x, y = e.y + p.y)) }
    val centre = PyreonChartPt(x = e.x + e.cx, y = e.y + e.cy)
    if (e.kind == "text") {
      val align = if (e.align == "middle") "middle" else if (e.align == "end") "end" else "start"
      out.add(PyreonDrawCmd(kind = "text", fill = e.fill, text = e.text, at = PyreonChartPt(x = e.x, y = e.y), size = e.fontSize, align = align, baseline = "top"))
      return out
    }
    if (e.kind == "rect") {
      out.add(PyreonDrawCmd(kind = "rect", rect = PyreonChartRect(x = e.x + e.cx, y = e.y + e.cy, w = e.w, h = e.h), fill = e.fill))
      return out
    }
    if (e.kind == "circle") {
      out.add(PyreonDrawCmd(kind = "circle", fill = e.fill, center = centre, radius = e.r))
      return out
    }
    if (e.kind == "line") {
      val zero = PyreonChartPt(x = 0.0, y = 0.0)
      out.add(PyreonDrawCmd(kind = "line", from = at(if (e.points.length > 0) e.points[0] else zero), to = at(if (e.points.length > 1) e.points[1] else zero), stroke = e.stroke, width = e.lineWidth))
      return out
    }
    if (e.kind == "polygon") {
      val pts = e.points.map(at)
      if (pts.length >= 2) {
        out.add(PyreonDrawCmd(kind = "polygon", fill = e.fill, points = pts))
      }
      return out
    }
    if (e.kind == "polyline") {
      val pts = e.points.map(at)
      if (pts.length >= 2) {
        out.add(PyreonDrawCmd(kind = "polyline", stroke = e.stroke, width = e.lineWidth, points = pts))
      }
      return out
    }
    if (e.kind == "bezier") {
      val pts = bezierPoints(e.points).map(at)
      if (pts.length >= 2) {
        out.add(PyreonDrawCmd(kind = "polyline", stroke = e.stroke, width = e.lineWidth, points = pts))
      }
      return out
    }
    if (e.kind == "ring") {
      if (e.r > 0.0) {
        out.add(PyreonDrawCmd(kind = "polygon", fill = e.fill, points = arcPolygon(centre, e.r, e.r0, 0.0, FULL_TURN)))
      }
      return out
    }
    if (e.kind == "sector") {
      val sweep = arcSweep(e.startAngle, e.endAngle, e.clockwise)
      if (e.r > 0.0 && sweep.y > sweep.x) {
        out.add(PyreonDrawCmd(kind = "polygon", fill = e.fill, points = arcPolygon(centre, e.r, e.r0, sweep.x, sweep.y)))
      }
      return out
    }
    if (e.kind == "arc") {
      val sweep = arcSweep(e.startAngle, e.endAngle, e.clockwise)
      if (e.r > 0.0 && sweep.y > sweep.x) {
        val fan = arcPolygon(centre, e.r, 0.0, sweep.x, sweep.y)
        val edge: MutableList<PyreonChartPt> = mutableListOf()
        for (i in 0 until fan.length - 1) {
          edge.add(fan[i])
        }
        if (edge.length >= 2) {
          out.add(PyreonDrawCmd(kind = "polyline", stroke = e.stroke, width = e.lineWidth, points = edge))
        }
      }
      return out
    }
    return out
  }

fun graphicDrawCommands(elements: List<GraphicElement>): List<PyreonDrawCmd> {
    val out: MutableList<PyreonDrawCmd> = mutableListOf()
    for (e in elements) {
      for (c in graphicElementCommands(e)) {
        out.add(c)
      }
    }
    return out
  }

fun labelLineSegments(line: String, rich: List<RichStyle>, color: String, size: Double): List<LabelSegment> {
    val segments: MutableList<LabelSegment> = mutableListOf()
    var plain = ""
    var inTag = false
    var sawBar = false
    var tagName = ""
    var tagBody = ""
    for (i in 0 until line.length) {
      val ch = line[i].toString()
      var handled = false
      if (inTag) {
        if (ch == "|" && !sawBar) {
          sawBar = true
          handled = true
        } else {
          if (ch == "}" && sawBar) {
            if (plain != "") {
              segments.add(LabelSegment(text = plain, color = color, fontSize = size))
            }
            plain = ""
            var segColor = color
            var segSize = size
            for (r in rich) {
              if (r.name == tagName) {
                if (r.color != "") {
                  segColor = r.color
                }
                if (r.fontSize > 0.0) {
                  segSize = r.fontSize
                }
              }
            }
            segments.add(LabelSegment(text = tagBody, color = segColor, fontSize = segSize))
            inTag = false
            sawBar = false
            tagName = ""
            tagBody = ""
            handled = true
          } else {
            if (ch != "{" && ch != "}") {
              if (sawBar) {
                tagBody = tagBody + ch
              } else {
                tagName = tagName + ch
              }
              handled = true
            } else {
              plain = plain + "{" + tagName + (if (sawBar) "|" + tagBody else "")
              inTag = false
              sawBar = false
              tagName = ""
              tagBody = ""
            }
          }
        }
      }
      if (!handled) {
        if (ch == "{") {
          inTag = true
        } else {
          plain = plain + ch
        }
      }
    }
    if (inTag) {
      plain = plain + "{" + tagName + (if (sawBar) "|" + tagBody else "")
    }
    if (plain != "") {
      segments.add(LabelSegment(text = plain, color = color, fontSize = size))
    }
    return segments
  }

fun labelLines(text: String, rich: List<RichStyle>, color: String, size: Double): List<List<LabelSegment>> {
    val lines: MutableList<List<LabelSegment>> = mutableListOf()
    for (line in text.split("\n")) {
      lines.add(labelLineSegments(line, rich, color, size))
    }
    return lines
  }

fun lineWidth(line: List<LabelSegment>, measure: (String, Double) -> Double): Double {
    var w = 0.0
    for (seg in line) {
      w = w + measure(seg.text, seg.fontSize)
    }
    return w
  }

fun lineHeight(line: List<LabelSegment>, size: Double): Double {
    var h = size
    for (seg in line) {
      if (seg.fontSize > h) {
        h = seg.fontSize
      }
    }
    return h
  }

fun labelCommands(text: String, rich: List<RichStyle>, at: PyreonChartPt, align: String, baseline: String, color: String, size: Double, measure: (String, Double) -> Double): List<PyreonDrawCmd> {
    val out: MutableList<PyreonDrawCmd> = mutableListOf()
    val lines = labelLines(text, rich, color, size)
    val plain = lines.length == 1 && lines[0].length <= 1
    if (plain) {
      val only = if (lines[0].length == 1) lines[0][0] else LabelSegment(text = "", color = color, fontSize = size)
      out.add(PyreonDrawCmd(kind = "text", fill = only.color, text = only.text, at = at, size = only.fontSize, align = anchorX(align), baseline = anchorY(baseline)))
      return out
    }
    var total = 0.0
    for (line in lines) {
      total = total + lineHeight(line, size) * 1.25
    }
    var y = at.y
    if (baseline == "middle") {
      y = at.y - (total).toDouble() / (2.0).toDouble()
    } else {
      if (baseline == "bottom") {
        y = at.y - total
      }
    }
    for (line in lines) {
      val h = lineHeight(line, size)
      val w = lineWidth(line, measure)
      var x = at.x
      if (align == "middle") {
        x = at.x - (w).toDouble() / (2.0).toDouble()
      } else {
        if (align == "end") {
          x = at.x - w
        }
      }
      for (seg in line) {
        out.add(PyreonDrawCmd(kind = "text", fill = seg.color, text = seg.text, at = PyreonChartPt(x = x, y = y), size = seg.fontSize, align = "start", baseline = "top"))
        x = x + measure(seg.text, seg.fontSize)
      }
      y = y + h * 1.25
    }
    return out
  }

fun anchorX(align: String): String = if (align == "middle") "middle" else if (align == "end") "end" else "start"

fun anchorY(baseline: String): String = if (baseline == "middle") "middle" else if (baseline == "bottom") "bottom" else "top"

fun linePixels(flat: List<Double>, plot: PyreonChartRect, xDomain: Domain, yDomain: Domain): List<PyreonChartPt> {
    val out: MutableList<PyreonChartPt> = mutableListOf()
    var k = 0
    while (k + 1 < flat.length) {
      out.add(PyreonChartPt(x = scaleLinear(xDomain, plot.x, plot.x + plot.w, flat[k]), y = scaleLinear(yDomain, plot.y + plot.h, plot.y, flat[k + 1])))
      k = k + 2
    }
    return out
  }

fun pointAlong(pts: List<PyreonChartPt>, dist: Double): PyreonChartPt {
    if (pts.length == 0) {
      return PyreonChartPt(x = 0.0, y = 0.0)
    }
    var remaining = dist
    for (i in 1 until pts.length) {
      val a = pts[i - 1]
      val b = pts[i]
      val seg = Math.sqrt(((b.x - a.x) * (b.x - a.x) + (b.y - a.y) * (b.y - a.y)).toDouble())
      if (remaining <= seg && seg > 0.0) {
        val f = (remaining).toDouble() / (seg).toDouble()
        return PyreonChartPt(x = a.x + (b.x - a.x) * f, y = a.y + (b.y - a.y) * f)
      }
      remaining = remaining - seg
    }
    return pts[pts.length - 1]
  }

fun subPath(pts: List<PyreonChartPt>, from: Double, to: Double): List<PyreonChartPt> {
    val out: MutableList<PyreonChartPt> = mutableListOf()
    if (pts.length < 2 || to <= from) {
      return out
    }
    out.add(pointAlong(pts, from))
    var walked = 0.0
    for (i in 1 until pts.length) {
      val a = pts[i - 1]
      val b = pts[i]
      walked = walked + Math.sqrt(((b.x - a.x) * (b.x - a.x) + (b.y - a.y) * (b.y - a.y)).toDouble())
      if (walked > from && walked < to) {
        out.add(b)
      }
    }
    out.add(pointAlong(pts, to))
    return out
  }

fun pathLength(pts: List<PyreonChartPt>): Double {
    var total = 0.0
    for (i in 1 until pts.length) {
      val a = pts[i - 1]
      val b = pts[i]
      total = total + Math.sqrt(((b.x - a.x) * (b.x - a.x) + (b.y - a.y) * (b.y - a.y)).toDouble())
    }
    return total
  }

fun linesCommands(s: LinesSeries, plot: PyreonChartRect, xDomain: Domain, yDomain: Domain, time: Double): List<PyreonDrawCmd> {
    val out: MutableList<PyreonDrawCmd> = mutableListOf()
    for (i in 0 until s.coords.length) {
      val pts = linePixels(s.coords[i], plot, xDomain, yDomain)
      if (pts.length < 2) {
        continue
      }
      val color = if (i < s.colors.length) s.colors[i] else "#334155"
      val width = if (i < s.widths.length) s.widths[i] else 1.5
      out.add(PyreonDrawCmd(kind = "polyline", stroke = color, width = width, points = pts))
    }
    if (!s.effect) {
      return out
    }
    val period = if (s.period > 0.0) s.period else 4.0
    val cycles = (time).toDouble() / (period).toDouble()
    val phase = cycles - Math.floor(cycles)
    val trail = if (s.trailLength < 0.0) 0.0 else if (s.trailLength > 1.0) 1.0 else s.trailLength
    for (i in 0 until s.coords.length) {
      val pts = linePixels(s.coords[i], plot, xDomain, yDomain)
      if (pts.length < 2) {
        continue
      }
      val total = pathLength(pts)
      if (!(total > 0.0)) {
        continue
      }
      val color = if (s.effectColor != "") s.effectColor else if (i < s.colors.length) s.colors[i] else "#334155"
      val width = if (i < s.widths.length) s.widths[i] else 1.5
      val head = phase * total
      val tail = if (head - trail * total > 0.0) head - trail * total else 0.0
      if (trail > 0.0 && head > tail) {
        out.add(PyreonDrawCmd(kind = "polyline", stroke = withAlpha(color, 0.85), width = width + 1.0, points = subPath(pts, tail, head)))
      }
      out.add(PyreonDrawCmd(kind = "circle", fill = color, center = pointAlong(pts, head), radius = (s.symbolSize).toDouble() / (2.0).toDouble()))
    }
    return out
  }

fun themeCorners(radius: Double, positive: Boolean, horizontal: Boolean): List<Double>? {
    if (radius <= 0.0) {
      return null
    }
    if (horizontal) {
      return if (positive) listOf(0.0, radius, radius, 0.0) else listOf(radius, 0.0, 0.0, radius)
    }
    return if (positive) listOf(radius, radius, 0.0, 0.0) else listOf(0.0, 0.0, radius, radius)
  }

fun labelTextAt(s: Series, index: Int, fallback: String): String {
    val texts = (s.labelTexts ?: listOf())
    if (index < 0 || index >= texts.length) {
      return fallback
    }
    val own = (texts[index] ?: "")
    return if (own == "") fallback else own
  }

fun seriesLabelCmds(s: Series, index: Int, fallback: String, at: PyreonChartPt, align: String, baseline: String, t: ChartTheme, measure: (String, Double) -> Double): List<PyreonDrawCmd> {
    val color = (s.labelColor ?: "")
    val size = (s.labelSize ?: 0.0)
    return labelCommands(labelTextAt(s, index, fallback), (s.labelRich ?: listOf()), at, align, baseline, if (color == "") t.label else color, if (size > 0.0) size else t.fontSize, measure)
  }

fun emphasisLevel(spec: ChartSpec, index: Int): Int {
    val e = (spec.emphasis ?: Emphasis(highlight = -1, selected = listOf()))
    for (sel in e.selected) {
      if (sel == index) {
        return 2
      }
    }
    return if (e.highlight == index) 1 else 0
  }

fun blurActive(spec: ChartSpec): Boolean {
    val e = (spec.emphasis ?: Emphasis(highlight = -1, selected = listOf()))
    if (e.highlight < 0) {
      return false
    }
    for (s in spec.series) {
      if (s.focus == "self" || s.focus == "series") {
        return true
      }
    }
    return false
  }

fun stateFill(spec: ChartSpec, s: Series, index: Int, fill: String): String {
    val level = emphasisLevel(spec, index)
    val selectColor = (s.selectColor ?: "")
    val emphasisColor = (s.emphasisColor ?: "")
    if (level == 2 && selectColor != "") {
      return selectColor
    }
    if (level == 1 && emphasisColor != "") {
      return emphasisColor
    }
    if (level == 0 && blurActive(spec)) {
      return withAlpha(fill, (s.blurOpacity ?: 0.1))
    }
    return fill
  }

fun emphasisOutline(r: PyreonChartRect, level: Int, stroke: String): PyreonDrawCmd = PyreonDrawCmd(kind = "polyline", stroke = stroke, width = if (level == 2) 2.5 else 1.5, points = listOf(PyreonChartPt(x = r.x, y = r.y), PyreonChartPt(x = r.x + r.w, y = r.y), PyreonChartPt(x = r.x + r.w, y = r.y + r.h), PyreonChartPt(x = r.x, y = r.y + r.h), PyreonChartPt(x = r.x, y = r.y)))

fun resolveYDomain(spec: ChartSpec): Domain {
    val d = (spec.yDomain ?: deriveOver(leftAxisSeries(spec)))
    return if (spec.yInverse == true) Domain(min = d.min, max = d.max, inverse = true) else d
  }

fun resolveY2Domain(spec: ChartSpec): Domain = (spec.y2Domain ?: deriveOver(rightAxisSeries(spec)))

fun logBounds(spec: ChartSpec): Domain {
    val pinned = (spec.yDomain ?: Domain(min = 0.0, max = 0.0))
    if (spec.yDomain != null && pinned.min > 0.0 && pinned.max > pinned.min) {
      return pinned
    }
    var lo = 0.0
    var hi = 0.0
    for (s in leftAxisSeries(spec)) {
      for (v in s.values) {
        if (!(v > 0.0)) {
          continue
        }
        if (lo == 0.0 || v < lo) {
          lo = v
        }
        if (v > hi) {
          hi = v
        }
      }
    }
    if (lo == 0.0) {
      return Domain(min = 1.0, max = 10.0)
    }
    val floor = Math.pow((10.0).toDouble(), (Math.floor(Math.log10((lo).toDouble()))).toDouble())
    var ceil = Math.pow((10.0).toDouble(), (Math.ceil(Math.log10((hi).toDouble()))).toDouble())
    if (ceil <= floor) {
      ceil = floor * 10.0
    }
    return Domain(min = floor, max = ceil)
  }

fun geometrySpec(raw: ChartSpec): ChartSpec {
    val spec = invertCategories(raw)
    val isLog = spec.yScale == "log"
    val norm = spec.stackNormalize == true
    if (!isLog && !norm) {
      return spec
    }
    val lb = if (isLog) logBounds(spec) else Domain(min = 1.0, max = 10.0)
    val viewMax = if (isLog) Math.log10(((lb.max).toDouble() / (lb.min).toDouble()).toDouble()) else 1.0
    val stacked = if (norm) normalizeStack(spec.series.filter({ s -> s.kind == "stacked" }).map({ s -> s.values })) else listOf()
    var si = 0
    val series: MutableList<Series> = mutableListOf()
    for (s in spec.series) {
      if (norm && s.kind == "stacked") {
        series.add(s.copy(values = if (si < stacked.length) stacked[si] else s.values))
        si = si + 1
      } else {
        if (isLog && !seriesOnRightAxis(s, spec) && !onExtraAxis(s, spec)) {
          val values: MutableList<Double> = mutableListOf()
          for (v in s.values) {
            values.add(if (v > 0.0) Math.log10(((v).toDouble() / (lb.min).toDouble()).toDouble()) else ((0.0).toDouble() / (0.0).toDouble()))
          }
          val lows: MutableList<Double> = mutableListOf()
          val highs: MutableList<Double> = mutableListOf()
          for (v in (s.errLow ?: listOf())) {
            lows.add(if (v > 0.0) Math.log10(((v).toDouble() / (lb.min).toDouble()).toDouble()) else ((0.0).toDouble() / (0.0).toDouble()))
          }
          for (v in (s.errHigh ?: listOf())) {
            highs.add(if (v > 0.0) Math.log10(((v).toDouble() / (lb.min).toDouble()).toDouble()) else ((0.0).toDouble() / (0.0).toDouble()))
          }
          series.add(s.copy(values = values, errLow = if (s.errLow == null) null else lows, errHigh = if (s.errHigh == null) null else highs))
        } else {
          series.add(s)
        }
      }
    }
    val notes: MutableList<Annotation> = mutableListOf()
    for (a in (spec.annotations ?: listOf())) {
      if (!isLog) {
        notes.add(a)
        continue
      }
      val ay = (a.y ?: 0.0)
      val yF = (a.yFrom ?: 0.0)
      val yT = (a.yTo ?: 0.0)
      notes.add(a.copy(y = if (a.y != null && ay > 0.0) Math.log10(((ay).toDouble() / (lb.min).toDouble()).toDouble()) else null, yFrom = if (a.yFrom != null && yF > 0.0) Math.log10(((yF).toDouble() / (lb.min).toDouble()).toDouble()) else null, yTo = if (a.yTo != null && yT > 0.0) Math.log10(((yT).toDouble() / (lb.min).toDouble()).toDouble()) else null))
    }
    val yDomain = if (isLog) Domain(min = 0.0, max = viewMax) else Domain(min = 0.0, max = 1.0)
    return spec.copy(series = series, yDomain = yDomain, annotations = if (spec.annotations == null) null else notes, yScale = "linear", stackNormalize = false)
  }

fun invertedDomain(d: Domain, inverse: Boolean): Domain = if (inverse) Domain(min = d.min, max = d.max, inverse = true) else d

fun categoriesInverted(spec: ChartSpec): Boolean = spec.xInverse == true && spec.horizontal != true && ((spec.xValues ?: listOf())).length == 0

fun categorySlots(spec: ChartSpec): Int {
    val m = seriesMaxLength(spec.series)
    return if (spec.categories.length > m) spec.categories.length else m
  }

fun categoryIndex(spec: ChartSpec, index: Int): Int {
    if (!categoriesInverted(spec) || index < 0) {
      return index
    }
    return categorySlots(spec) - 1 - index
  }

fun reversedDoubles(a: List<Double>?, n: Int): List<Double>? {
    val src = (a ?: listOf())
    val out: MutableList<Double> = mutableListOf()
    for (i in 0 until n) {
      val j = n - 1 - i
      out.add(if (j < src.length) src[j] else (0.0).toDouble() / (0.0).toDouble())
    }
    return if (a == null) null else out
  }

fun reversedStrings(a: List<String>?, n: Int): List<String>? {
    val src = (a ?: listOf())
    val out: MutableList<String> = mutableListOf()
    for (i in 0 until n) {
      val j = n - 1 - i
      out.add(if (j < src.length) src[j] else "")
    }
    return if (a == null) null else out
  }

fun invertCategories(spec: ChartSpec): ChartSpec {
    if (!categoriesInverted(spec)) {
      return spec
    }
    val n = categorySlots(spec)
    val last = n - 1.0
    val series: MutableList<Series> = mutableListOf()
    for (s in spec.series) {
      val extras: MutableList<SeriesExtra> = mutableListOf()
      for (e in (s.extras ?: listOf())) {
        extras.add(SeriesExtra(label = e.label, numbers = reversedDoubles(e.numbers, n), texts = reversedStrings(e.texts, n)))
      }
      series.add(s.copy(values = (reversedDoubles(s.values, n) ?: listOf()), rValues = reversedDoubles(s.rValues, n), radii = reversedDoubles(s.radii, n), labelTexts = reversedStrings(s.labelTexts, n), errLow = reversedDoubles(s.errLow, n), errHigh = reversedDoubles(s.errHigh, n), values2 = reversedDoubles(s.values2, n), extras = if (s.extras == null) null else extras))
    }
    val notes: MutableList<Annotation> = mutableListOf()
    for (a in (spec.annotations ?: listOf())) {
      val ax = (a.x ?: 0.0)
      val xf = (a.xFrom ?: 0.0)
      val xt = (a.xTo ?: 0.0)
      val x1 = (a.x1 ?: 0.0)
      val x2 = (a.x2 ?: 0.0)
      notes.add(a.copy(x = if (a.x == null) null else last - ax, xFrom = if (a.xTo == null) null else last - xt, xTo = if (a.xFrom == null) null else last - xf, x1 = if (a.x1 == null) null else last - x1, x2 = if (a.x2 == null) null else last - x2))
    }
    val marks: MutableList<PointMarker> = mutableListOf()
    for (m in (spec.markers ?: listOf())) {
      val at = (m.atIndex ?: 0.0)
      marks.add(m.copy(atIndex = if (m.atIndex == null) null else last - at))
    }
    val em = spec.emphasis
    val selected: MutableList<Int> = mutableListOf()
    for (k in (em?.selected ?: listOf())) {
      selected.add(n - 1 - k)
    }
    val highlight = (em?.highlight ?: -1)
    return spec.copy(series = series, categories = (reversedStrings(spec.categories, if (spec.categories.length == 0) 0 else n) ?: listOf()), annotations = if (spec.annotations == null) null else notes, markers = if (spec.markers == null) null else marks, emphasis = if (em == null) null else Emphasis(highlight = if (highlight < 0) highlight else n - 1 - highlight, selected = selected))
  }

fun seriesOnX2(s: Series, spec: ChartSpec): Boolean = s.onX2 == true && spec.horizontal != true && ((s.xs ?: listOf())).length > 0

fun hasX2Axis(spec: ChartSpec): Boolean {
    for (s in spec.series) {
      if (seriesOnX2(s, spec)) {
        return true
      }
    }
    return false
  }

fun resolveX2Domain(spec: ChartSpec): Domain {
    if (spec.x2Domain != null) {
      return (spec.x2Domain ?: Domain(min = 0.0, max = 1.0))
    }
    val all: MutableList<Double> = mutableListOf()
    for (s in spec.series) {
      if (seriesOnX2(s, spec)) {
        for (x in (s.xs ?: listOf())) {
          all.add(x)
        }
      }
    }
    return if (all.length > 0) extent(all) else Domain(min = 0.0, max = 1.0)
  }

fun onExtraAxis(s: Series, spec: ChartSpec): Boolean {
    val k = (s.axisExtra ?: -1.0)
    return spec.horizontal != true && k >= 0.0 && k < ((spec.extraYAxes ?: listOf())).length
  }

fun extraAxisDomain(spec: ChartSpec, k: Double): Domain {
    var i = 0.0
    for (a in (spec.extraYAxes ?: listOf())) {
      if (i == k) {
        return (a.domain ?: deriveOver(spec.series.filter({ q -> ((q.axisExtra ?: -1.0)) == k })))
      }
      i = i + 1.0
    }
    return Domain(min = 0.0, max = 1.0)
  }

fun resolvedExtraAxes(spec: ChartSpec): List<ExtraYAxis> {
    val out: MutableList<ExtraYAxis> = mutableListOf()
    var i = 0.0
    for (a in (spec.extraYAxes ?: listOf())) {
      out.add(ExtraYAxis(side = a.side, domain = extraAxisDomain(spec, i), title = a.title, offset = a.offset))
      i = i + 1.0
    }
    return out
  }

fun seriesDomain(s: Series, spec: ChartSpec, yDomain: Domain, y2Domain: Domain): Domain {
    if (onExtraAxis(s, spec)) {
      return extraAxisDomain(spec, (s.axisExtra ?: 0.0))
    }
    return if (seriesOnRightAxis(s, spec)) y2Domain else yDomain
  }

fun seriesOnRightAxis(s: Series, spec: ChartSpec): Boolean {
    if (spec.horizontal == true) {
      return false
    }
    if (s.axisExtra != null) {
      return false
    }
    if (s.kind == "stacked" || s.kind == "grouped" || s.kind == "stackedArea") {
      return false
    }
    if (s.axis != "right") {
      return false
    }
    var hasLeft = false
    for (q in spec.series) {
      val qRight = q.axis == "right" && q.kind != "stacked" && q.kind != "grouped" && q.kind != "stackedArea"
      if (!qRight && q.axisExtra == null) {
        hasLeft = true
      }
    }
    return hasLeft
  }

fun hasRightAxis(spec: ChartSpec): Boolean {
    for (s in spec.series) {
      if (seriesOnRightAxis(s, spec)) {
        return true
      }
    }
    return false
  }

fun leftAxisSeries(spec: ChartSpec): List<Series> = spec.series.filter({ s -> !seriesOnRightAxis(s, spec) && (s.axisExtra == null || spec.horizontal == true) })

fun rightAxisSeries(spec: ChartSpec): List<Series> = spec.series.filter({ s -> seriesOnRightAxis(s, spec) })

fun deriveOver(series: List<Series>): Domain {
    val stacked = series.filter({ s -> s.kind == "stacked" || s.kind == "stackedArea" })
    if (stacked.length > 0) {
      val e = stackedExtent(stacked.map({ s -> s.values }))
      val others: MutableList<Double> = mutableListOf()
      for (s in series) {
        if (s.kind != "stacked" && s.kind != "stackedArea") {
          for (v in s.values) {
            if (isFiniteValue(v)) {
              others.add(v)
            }
          }
        }
      }
      val max = if (others.length > 0) Math.max(e.max, extent(others).max) else e.max
      return niceDomain(Domain(min = 0.0, max = max), 5.0)
    }
    val all: MutableList<Double> = mutableListOf()
    var hasBars = false
    for (s in series) {
      if (s.kind == "bars" || s.kind == "area" || s.kind == "grouped" || s.kind == "waterfall" || s.kind == "stackedArea") {
        hasBars = true
      }
      if (s.kind == "waterfall") {
        val we = waterfallExtent(s.values)
        all.add(we.min)
        all.add(we.max)
        continue
      }
      for (v in s.values) {
        if (isFiniteValue(v)) {
          all.add(v)
        }
      }
      for (v in (s.values2 ?: listOf())) {
        if (isFiniteValue(v)) {
          all.add(v)
        }
      }
      for (v in (s.errLow ?: listOf())) {
        if (isFiniteValue(v)) {
          all.add(v)
        }
      }
      for (v in (s.errHigh ?: listOf())) {
        if (isFiniteValue(v)) {
          all.add(v)
        }
      }
    }
    val e = extent(all)
    val withZero = if (hasBars) Domain(min = if (e.min > 0.0) 0.0 else e.min, max = if (e.max < 0.0) 0.0 else e.max) else e
    return niceDomain(withZero, 5.0)
  }

fun isFiniteValue(v: Double): Boolean = isFiniteNumber(v)

fun seriesMaxLength(series: List<Series>): Int {
    var n = 0
    for (s in series) {
      if (s.values.length > n) {
        n = s.values.length
      }
    }
    return n
  }

fun layoutChart(raw: ChartSpec, measure: (String, Double) -> Double): PlotLayout {
    val spec = geometrySpec(raw)
    val n = seriesMaxLength(spec.series)
    val isLog = raw.yScale == "log"
    val lb = if (isLog) logBounds(raw) else Domain(min = 1.0, max = 10.0)
    val cfg = LayoutConfig(width = spec.width, height = spec.height, xDomain = if (((spec.xValues ?: listOf())).length > 0) invertedDomain(extent((spec.xValues ?: listOf())), spec.xInverse == true && spec.horizontal != true) else Domain(min = 0.0, max = if (n > 1) (n - 1).toDouble() else 1.0), yDomain = resolveYDomain(spec), categories = spec.categories, fontSize = spec.theme.fontSize, xTickCount = 5.0, yTickCount = 5.0, showXAxis = spec.showXAxis, showYAxis = spec.showYAxis, yFormat = (spec.yFormat ?: (if (raw.stackNormalize == true) percent(0) else null)), xFormat = spec.xFormat, xTime = spec.xTime == true, y2Domain = if (hasRightAxis(spec)) resolveY2Domain(spec) else null, y2Format = spec.y2Format, horizontal = spec.horizontal == true, xTitle = spec.xTitle, yTitle = spec.yTitle, y2Title = spec.y2Title, yLog = isLog, yLogMin = lb.min, yLogMax = lb.max, yTime = spec.yTime == true, xLabels = spec.xLabels, xTop = spec.xTop, yRight = spec.yRight, extraYAxes = resolvedExtraAxes(spec), x2Labels = spec.x2Labels, x2Title = spec.x2Title, x2Domain = if (hasX2Axis(spec)) resolveX2Domain(spec) else null, xOffset = spec.xOffset, yOffset = spec.yOffset, y2Offset = spec.y2Offset)
    return computeLayout(cfg, measure)
  }

fun renderChart(spec: ChartSpec, measure: (String, Double) -> Double): List<PyreonDrawCmd> = renderChartIn(spec, measure, layoutChart(spec, measure))

fun renderChartIn(raw: ChartSpec, measure: (String, Double) -> Double, l: PlotLayout): List<PyreonDrawCmd> {
    val spec = geometrySpec(raw)
    val printedView = invertCategories(raw)
    val printed = fun(k: Int, i: Int): Double {
      val sv = printedView.series[k].values
      return if (i < sv.length) sv[i] else (0.0).toDouble() / (0.0).toDouble()
    }
    val yDomain = resolveYDomain(spec)
    val useY2 = hasRightAxis(spec)
    val y2Domain = if (useY2) resolveY2Domain(spec) else yDomain
    val plot = l.plot
    val t = spec.theme
    val out: MutableList<PyreonDrawCmd> = mutableListOf()
    val rawProgress = (spec.progress ?: 1.0)
    val progress = if (rawProgress < 0.0) 0.0 else if (rawProgress > 1.0) 1.0 else rawProgress
    val growRect = fun(r: PyreonChartRect, dom: Domain): PyreonChartRect {
      if (progress >= 1.0) {
        return r
      }
      val zeroY = scaleLinear(dom, plot.y + plot.h, plot.y, if (dom.min < 0.0 && dom.max > 0.0) 0.0 else dom.min)
      val h = r.h * progress
      val top = if (r.y + r.h <= zeroY + 0.5) zeroY - h else zeroY
      return PyreonChartRect(x = r.x, y = top, w = r.w, h = h)
    }
    val growRectH = fun(r: PyreonChartRect): PyreonChartRect {
      if (progress >= 1.0) {
        return r
      }
      val zeroX = scaleLinear(yDomain, plot.x, plot.x + plot.w, if (yDomain.min < 0.0 && yDomain.max > 0.0) 0.0 else yDomain.min)
      val w = r.w * progress
      val left = if (r.x >= zeroX - 0.5) zeroX else zeroX - w
      return PyreonChartRect(x = left, y = r.y, w = w, h = r.h)
    }
    val reveal = fun(pts: List<PyreonChartPt>): List<PyreonChartPt> {
      if (progress >= 1.0 || pts.length < 2) {
        return pts
      }
      val span = pts.length - 1
      val cut = span * progress
      val whole = Math.floor(cut)
      val outPts: MutableList<PyreonChartPt> = mutableListOf()
      for (i in 0..Math.floor(whole).toInt()) {
        outPts.add(pts[i])
      }
      val frac = cut - whole
      if (frac > 0.0 && whole + 1 < pts.length) {
        val a = pts[(whole).toInt()]
        val b = pts[(whole + 1).toInt()]
        outPts.add(PyreonChartPt(x = a.x + (b.x - a.x) * frac, y = a.y + (b.y - a.y) * frac))
      }
      return outPts
    }
    if (spec.showGrid) {
      if (spec.horizontal == true) {
        for (tick in l.xTicks) {
          out.add(PyreonDrawCmd(kind = "line", from = PyreonChartPt(x = tick.pos, y = plot.y), to = PyreonChartPt(x = tick.pos, y = plot.y + plot.h), stroke = t.grid, width = 1.0))
        }
      } else {
        for (tick in l.yTicks) {
          out.add(PyreonDrawCmd(kind = "line", from = PyreonChartPt(x = plot.x, y = tick.pos), to = PyreonChartPt(x = plot.x + plot.w, y = tick.pos), stroke = t.grid, width = 1.0))
        }
      }
    }
    val yRight = spec.yRight == true && !useY2 && spec.horizontal != true
    val yOff = (spec.yOffset ?: 0.0)
    val y2Off = (spec.y2Offset ?: 0.0)
    val xOff = (spec.xOffset ?: 0.0)
    val yAxisX = if (yRight) plot.x + plot.w + yOff else plot.x - yOff
    if (spec.showYAxis) {
      out.add(PyreonDrawCmd(kind = "line", from = PyreonChartPt(x = yAxisX, y = plot.y), to = PyreonChartPt(x = yAxisX, y = plot.y + plot.h), stroke = t.axis, width = 1.0))
    }
    val xTop = spec.xTop == true && spec.horizontal != true
    val xAxisY = if (xTop) plot.y - xOff else plot.y + plot.h + xOff
    if (spec.showXAxis) {
      out.add(PyreonDrawCmd(kind = "line", from = PyreonChartPt(x = plot.x, y = xAxisY), to = PyreonChartPt(x = plot.x + plot.w, y = xAxisY), stroke = t.axis, width = 1.0))
    }
    if (spec.showYAxis && spec.horizontal != true) {
      for (a in (spec.extraYAxes ?: listOf())) {
        val ax = if (a.side == "left") plot.x - ((a.offset ?: 0.0)) else plot.x + plot.w + ((a.offset ?: 0.0))
        out.add(PyreonDrawCmd(kind = "line", from = PyreonChartPt(x = ax, y = plot.y), to = PyreonChartPt(x = ax, y = plot.y + plot.h), stroke = t.axis, width = 1.0))
      }
    }
    if (spec.showYAxis && useY2) {
      out.add(PyreonDrawCmd(kind = "line", from = PyreonChartPt(x = plot.x + plot.w + y2Off, y = plot.y), to = PyreonChartPt(x = plot.x + plot.w + y2Off, y = plot.y + plot.h), stroke = t.axis, width = 1.0))
    }
    val notes = (spec.annotations ?: listOf())
    for (a in notes) {
      val yFrom = (a.yFrom ?: 0.0)
      val yTo = (a.yTo ?: 0.0)
      if (a.yFrom != null && a.yTo != null) {
        val y1 = scaleLinear(yDomain, plot.y + plot.h, plot.y, yFrom)
        val y2 = scaleLinear(yDomain, plot.y + plot.h, plot.y, yTo)
        val top = if (y1 < y2) y1 else y2
        out.add(PyreonDrawCmd(kind = "rect", rect = PyreonChartRect(x = plot.x, y = top, w = plot.w, h = (Math.abs(y2 - y1)).toDouble()), fill = withAlpha((a.color ?: t.axis), 0.12)))
        if (a.label != null) {
          out.add(PyreonDrawCmd(kind = "text", fill = (a.color ?: t.label), text = a.label, at = PyreonChartPt(x = plot.x + plot.w - 4.0, y = top + 4.0), size = t.fontSize, align = "end", baseline = "top"))
        }
      }
      val xFrom = (a.xFrom ?: 0.0)
      val xTo = (a.xTo ?: 0.0)
      if (a.xFrom != null && a.xTo != null) {
        val x1 = scaleLinear(l.xDomainUsed, plot.x, plot.x + plot.w, xFrom)
        val x2 = scaleLinear(l.xDomainUsed, plot.x, plot.x + plot.w, xTo)
        val left = if (x1 < x2) x1 else x2
        out.add(PyreonDrawCmd(kind = "rect", rect = PyreonChartRect(x = left, y = plot.y, w = (Math.abs(x2 - x1)).toDouble(), h = plot.h), fill = withAlpha((a.color ?: t.axis), 0.12)))
        if (a.label != null) {
          out.add(PyreonDrawCmd(kind = "text", fill = (a.color ?: t.label), text = a.label, at = PyreonChartPt(x = left + 4.0, y = plot.y + 4.0), size = t.fontSize, align = "start", baseline = "top"))
        }
      }
    }
    for (a in notes) {
      val ay = (a.y ?: 0.0)
      if (a.y != null) {
        val yPos = scaleLinear(yDomain, plot.y + plot.h, plot.y, ay)
        out.add(PyreonDrawCmd(kind = "line", from = PyreonChartPt(x = plot.x, y = yPos), to = PyreonChartPt(x = plot.x + plot.w, y = yPos), stroke = (a.color ?: t.axis), width = 1.0, dash = listOf(4.0, 4.0)))
        val yLabel = (a.label ?: "")
        if (a.label != null) {
          out.add(PyreonDrawCmd(kind = "text", fill = (a.color ?: t.label), text = yLabel, at = PyreonChartPt(x = plot.x + plot.w, y = yPos - 4.0), size = t.fontSize, align = "end", baseline = "bottom"))
        }
      }
      val ax = (a.x ?: 0.0)
      if (a.x != null) {
        val xPos = scaleLinear(l.xDomainUsed, plot.x, plot.x + plot.w, ax)
        out.add(PyreonDrawCmd(kind = "line", from = PyreonChartPt(x = xPos, y = plot.y), to = PyreonChartPt(x = xPos, y = plot.y + plot.h), stroke = (a.color ?: t.axis), width = 1.0, dash = listOf(4.0, 4.0)))
        val xLabel = (a.label ?: "")
        if (a.label != null) {
          out.add(PyreonDrawCmd(kind = "text", fill = (a.color ?: t.label), text = xLabel, at = PyreonChartPt(x = xPos + 4.0, y = plot.y), size = t.fontSize, align = "start", baseline = "top"))
        }
      }
      val sx1 = (a.x1 ?: 0.0)
      val sy1 = (a.y1 ?: 0.0)
      val sx2 = (a.x2 ?: 0.0)
      val sy2 = (a.y2 ?: 0.0)
      if (a.x1 != null && a.y1 != null && a.x2 != null && a.y2 != null) {
        val p1 = PyreonChartPt(x = scaleLinear(l.xDomainUsed, plot.x, plot.x + plot.w, sx1), y = scaleLinear(yDomain, plot.y + plot.h, plot.y, sy1))
        val p2 = PyreonChartPt(x = scaleLinear(l.xDomainUsed, plot.x, plot.x + plot.w, sx2), y = scaleLinear(yDomain, plot.y + plot.h, plot.y, sy2))
        out.add(PyreonDrawCmd(kind = "line", from = p1, to = p2, stroke = (a.color ?: t.axis), width = 1.0, dash = listOf(4.0, 4.0)))
        val segLabel = (a.label ?: "")
        if (a.label != null) {
          out.add(PyreonDrawCmd(kind = "text", fill = (a.color ?: t.label), text = segLabel, at = PyreonChartPt(x = p2.x, y = p2.y - 4.0), size = t.fontSize, align = "middle", baseline = "bottom"))
        }
      }
    }
    val emph = (spec.emphasis ?: Emphasis(highlight = -1, selected = listOf()))
    if (emph.highlight >= 0 && spec.horizontal != true) {
      val xsE = (spec.xValues ?: listOf())
      val hi = emph.highlight
      if (xsE.length > emph.highlight) {
        val cx = scaleLinear(l.xDomainUsed, plot.x, plot.x + plot.w, xsE[emph.highlight])
        out.add(PyreonDrawCmd(kind = "rect", rect = PyreonChartRect(x = cx - 6.0, y = plot.y, w = 12.0, h = plot.h), fill = withAlpha(t.axis, 0.14)))
      } else {
        if (spec.categories.length > emph.highlight) {
          val nb = spec.categories.length
          val bandW = (plot.w).toDouble() / (nb).toDouble()
          out.add(PyreonDrawCmd(kind = "rect", rect = PyreonChartRect(x = plot.x + bandW * countToDouble(hi), y = plot.y, w = bandW, h = plot.h), fill = withAlpha(t.axis, 0.14)))
        }
      }
    }
    val stackedSeries = spec.series.filter({ s -> s.kind == "stacked" })
    if (stackedSeries.length > 0) {
      val stackSegs = if (spec.horizontal == true) layoutStackedBarsH(stackedSeries.map({ s -> s.values }), plot, yDomain, 0.25) else layoutStackedBars(stackedSeries.map({ s -> s.values }), plot, yDomain, 0.25)
      val fmtS = (spec.yFormat ?: ::plain)
      for (seg in stackSegs) {
        val rS = growRect(seg.rect, yDomain)
        val gS = seriesGradient(stackedSeries[seg.seriesIndex].gradient, plot)
        out.add(rectCmd(rS, stateFill(spec, stackedSeries[seg.seriesIndex], seg.datumIndex, stackedSeries[seg.seriesIndex].color), stackedSeries[seg.seriesIndex].corners, if (gS.stops.length == 0) null else gS, stackedSeries[seg.seriesIndex].pattern))
        val lvlS = emphasisLevel(spec, seg.datumIndex)
        if (lvlS > 0) {
          out.add(emphasisOutline(rS, lvlS, t.label))
        }
        if (stackedSeries[seg.seriesIndex].showValues == true && progress >= 1.0) {
          for (c in seriesLabelCmds(stackedSeries[seg.seriesIndex], seg.datumIndex, fmtS(seg.value), PyreonChartPt(x = rS.x + (rS.w).toDouble() / (2.0).toDouble(), y = rS.y + (rS.h).toDouble() / (2.0).toDouble()), "middle", "middle", t, measure)) {
            out.add(c)
          }
        }
      }
    }
    val groupedSeries = spec.series.filter({ s -> s.kind == "grouped" })
    if (groupedSeries.length > 0) {
      val groupSegs = if (spec.horizontal == true) layoutGroupedBarsH(groupedSeries.map({ s -> s.values }), plot, yDomain, 0.25) else layoutGroupedBars(groupedSeries.map({ s -> s.values }), plot, yDomain, 0.25)
      val fmtG = (spec.yFormat ?: ::plain)
      for (seg in groupSegs) {
        val rG = growRect(seg.rect, yDomain)
        val gG = seriesGradient(groupedSeries[seg.seriesIndex].gradient, plot)
        out.add(rectCmd(rG, stateFill(spec, groupedSeries[seg.seriesIndex], seg.datumIndex, groupedSeries[seg.seriesIndex].color), groupedSeries[seg.seriesIndex].corners, if (gG.stops.length == 0) null else gG, groupedSeries[seg.seriesIndex].pattern))
        val lvlG = emphasisLevel(spec, seg.datumIndex)
        if (lvlG > 0) {
          out.add(emphasisOutline(rG, lvlG, t.label))
        }
        if (groupedSeries[seg.seriesIndex].showValues == true && progress >= 1.0) {
          for (c in seriesLabelCmds(groupedSeries[seg.seriesIndex], seg.datumIndex, fmtG(seg.value), PyreonChartPt(x = rG.x + (rG.w).toDouble() / (2.0).toDouble(), y = if (seg.value < 0.0) rG.y + rG.h + 4.0 else rG.y - 4.0), "middle", if (seg.value < 0.0) "top" else "bottom", t, measure)) {
            out.add(c)
          }
        }
      }
    }
    val areaStack = if (spec.horizontal == true) listOf() else spec.series.filter({ s -> s.kind == "stackedArea" })
    if (areaStack.length > 0) {
      val tops = stackCumulative(areaStack.map({ s -> s.values }))
      for (k in 0 until areaStack.length) {
        val sA = areaStack[k]
        val top = tops[k]
        val below = if (k == 0) listOf() else tops[k - 1]
        val upper: MutableList<PyreonChartPt> = mutableListOf()
        val lower: MutableList<PyreonChartPt> = mutableListOf()
        for (i in 0 until top.length) {
          val xAt = plot.x + ((plot.w).toDouble() / (Math.max(1.0, countToDouble(top.length))).toDouble()) * (countToDouble(i) + 0.5)
          upper.add(PyreonChartPt(x = xAt, y = scaleLinear(yDomain, plot.y + plot.h, plot.y, top[i])))
          lower.add(PyreonChartPt(x = xAt, y = scaleLinear(yDomain, plot.y + plot.h, plot.y, if (k == 0) yDomain.min else below[i])))
        }
        if (upper.length > 1) {
          val poly: MutableList<PyreonChartPt> = mutableListOf()
          for (p in upper) {
            poly.add(p)
          }
          for (i in lower.length - 1 downTo 0) {
            poly.add(lower[i])
          }
          val gA = seriesGradient(sA.gradient, plot)
          out.add(polygonCmd(poly, sA.color, if (gA.stops.length == 0) null else gA, sA.pattern))
          if (sA.showValues == true && progress >= 1.0) {
            val fmtA = (spec.yFormat ?: ::plain)
            for (i in 0 until upper.length) {
              val v = if (i < sA.values.length) sA.values[i] else (0.0).toDouble() / (0.0).toDouble()
              if (!isFiniteValue(v)) {
                continue
              }
              for (c in seriesLabelCmds(sA, i, fmtA(v), PyreonChartPt(x = upper[i].x, y = ((upper[i].y + lower[i].y)).toDouble() / (2.0).toDouble()), "middle", "middle", t, measure)) {
                out.add(c)
              }
            }
          }
        }
      }
    }
    for (sIdx in 0 until spec.series.length) {
      val s = spec.series[sIdx]
      if (s.kind == "stacked" || s.kind == "grouped" || s.kind == "stackedArea") {
        continue
      }
      val xs = (spec.xValues ?: listOf())
      val sDomain = seriesDomain(s, spec, yDomain, y2Domain)
      val onX2 = seriesOnX2(s, spec)
      val sXs = if (onX2) (s.xs ?: listOf()) else xs
      val sXDomain = if (onX2) resolveX2Domain(spec) else l.xDomainUsed
      val place = { values: List<Double> -> if (sXs.length > 0) layoutSeriesPointsAt(values, sXs, plot, sDomain, sXDomain) else layoutSeriesPoints(values, plot, sDomain) }
      val curveFn = (s.curve ?: ({ q -> q }))
      val sGradAll = seriesGradient(s.gradient, plot)
      val sGrad = if (sGradAll.stops.length == 0) null else sGradAll
      val shape = { pts: List<PyreonChartPt> -> curveFn(pts) }
      if (spec.horizontal == true) {
        if (s.kind != "bars") {
          continue
        }
        val rects = layoutBarsH(s.values, plot, yDomain, 0.25)
        for (ri in 0 until rects.length) {
          val r = rects[ri]
          val grown = growRectH(r)
          val fillH = stateFill(spec, s, ri, s.color)
          if (s.symbol == null) {
            out.add(rectCmd(grown, fillH, (s.corners ?: themeCorners(spec.theme.radius, ((s.values[ri] ?: 0.0)) >= 0.0, true)), sGrad, s.pattern))
          } else {
            for (c in pictorialCommands(pictorialBar(s, grown, true, (s.values[ri] ?: 0.0), fillH))) {
              out.add(c)
            }
          }
        }
        for (i in 0 until rects.length) {
          val lvl = emphasisLevel(spec, i)
          if (lvl > 0) {
            out.add(emphasisOutline(growRectH(rects[i]), lvl, t.label))
          }
        }
        if (s.showValues == true && progress >= 1.0) {
          val fmt = (spec.yFormat ?: ::plain)
          for (i in 0 until rects.length) {
            val r = rects[i]
            val v = printed(sIdx, i)
            if (!isFiniteValue(v)) {
              continue
            }
            for (c in seriesLabelCmds(s, i, fmt(v), PyreonChartPt(x = if (v < 0.0) r.x - 4.0 else r.x + r.w + 4.0, y = r.y + (r.h).toDouble() / (2.0).toDouble()), if (v < 0.0) "end" else "start", "middle", t, measure)) {
              out.add(c)
            }
          }
        }
        continue
      }
      if (s.kind == "bars") {
        val rects = layoutBars(s.values, plot, sDomain, 0.25)
        for (ri in 0 until rects.length) {
          val r = rects[ri]
          val grown = growRect(r, sDomain)
          val fillV = stateFill(spec, s, ri, s.color)
          if (s.symbol == null) {
            out.add(rectCmd(grown, fillV, (s.corners ?: themeCorners(spec.theme.radius, ((s.values[ri] ?: 0.0)) >= 0.0, false)), sGrad, s.pattern))
          } else {
            for (c in pictorialCommands(pictorialBar(s, grown, false, (s.values[ri] ?: 0.0), fillV))) {
              out.add(c)
            }
          }
        }
        for (i in 0 until rects.length) {
          val lvl = emphasisLevel(spec, i)
          if (lvl > 0) {
            out.add(emphasisOutline(growRect(rects[i], sDomain), lvl, t.label))
          }
        }
        if (s.showValues == true && progress >= 1.0) {
          val fmt = (spec.yFormat ?: ::plain)
          for (i in 0 until rects.length) {
            val r = rects[i]
            val v = printed(sIdx, i)
            if (!isFiniteValue(v)) {
              continue
            }
            for (c in seriesLabelCmds(s, i, fmt(v), PyreonChartPt(x = r.x + (r.w).toDouble() / (2.0).toDouble(), y = if (v < 0.0) r.y + r.h + 4.0 else r.y - 4.0), "middle", if (v < 0.0) "top" else "bottom", t, measure)) {
              out.add(c)
            }
          }
        }
      } else {
        if (s.kind == "waterfall") {
          val steps = layoutWaterfall(s.values, plot, sDomain, 0.25)
          for (si in 0 until steps.length) {
            val st = steps[si]
            val fill = stateFill(spec, s, st.datumIndex, if (st.value < 0.0) (s.negativeColor ?: withAlpha(s.color, 0.55)) else s.color)
            val startY = scaleLinear(sDomain, plot.y + plot.h, plot.y, st.start)
            val grownH = st.rect.h * progress
            val grown = if (progress >= 1.0) st.rect else PyreonChartRect(x = st.rect.x, y = if (st.value >= 0.0) startY - grownH else startY, w = st.rect.w, h = grownH)
            out.add(rectCmd(grown, fill, s.corners, sGrad, s.pattern))
            val lvlW = emphasisLevel(spec, st.datumIndex)
            if (lvlW > 0) {
              out.add(emphasisOutline(grown, lvlW, t.label))
            }
            if (si + 1 < steps.length && progress >= 1.0) {
              val next = steps[si + 1]
              val level = scaleLinear(sDomain, plot.y + plot.h, plot.y, st.end)
              out.add(PyreonDrawCmd(kind = "line", from = PyreonChartPt(x = st.rect.x + st.rect.w, y = level), to = PyreonChartPt(x = next.rect.x, y = level), stroke = t.axis, width = 1.0, dash = listOf(2.0, 2.0)))
            }
            if (s.showValues == true && progress >= 1.0) {
              val fmt = (spec.yFormat ?: ::plain)
              val v = printed(sIdx, st.datumIndex)
              for (c in seriesLabelCmds(s, st.datumIndex, fmt(v), PyreonChartPt(x = st.rect.x + (st.rect.w).toDouble() / (2.0).toDouble(), y = if (v < 0.0) st.rect.y + st.rect.h + 4.0 else st.rect.y - 4.0), "middle", if (v < 0.0) "top" else "bottom", t, measure)) {
                out.add(c)
              }
            }
          }
        } else {
          if (s.kind == "line") {
            for (run in splitRuns(s.values, place)) {
              val pts = reveal(shape(run))
              if (pts.length > 1) {
                out.add(PyreonDrawCmd(kind = "polyline", stroke = s.color, width = s.width, dash = s.dash, points = pts))
              }
            }
            val lineSymbol = (s.symbol ?: "circle")
            if (s.symbol != null && progress >= 1.0) {
              val dots = place(s.values)
              for (i in 0 until dots.length) {
                if (!isFiniteValue(s.values[i])) {
                  continue
                }
                val d = dots[i]
                out.add(symbolCommand(PyreonChartRect(x = d.x - s.radius, y = d.y - s.radius, w = s.radius * 2.0, h = s.radius * 2.0), lineSymbol, s.color))
              }
            }
          } else {
            if (s.kind == "band") {
              val lows = (s.values2 ?: listOf())
              val paired: MutableList<Double> = mutableListOf()
              for (i in 0 until s.values.length) {
                val lo = if (i < lows.length) lows[i] else (0.0).toDouble() / (0.0).toDouble()
                paired.add(if (isFiniteValue(s.values[i]) && isFiniteValue(lo)) s.values[i] else (0.0).toDouble() / (0.0).toDouble())
              }
              for (run in splitRuns(paired, place)) {
                var upper = reveal(shape(run))
                if (upper.length < 2) {
                  continue
                }
                val loRun: MutableList<Double> = mutableListOf()
                for (i in 0 until paired.length) {
                  loRun.add(if (isFiniteValue(paired[i])) (if (i < lows.length) lows[i] else (0.0).toDouble() / (0.0).toDouble()) else (0.0).toDouble() / (0.0).toDouble())
                }
                val lowerRuns = splitRuns(loRun, place)
                var lower = if (lowerRuns.length > 0) reveal(shape(lowerRuns[0])) else listOf()
                val poly: MutableList<PyreonChartPt> = mutableListOf()
                for (p in upper) {
                  poly.add(p)
                }
                for (i in lower.length - 1 downTo 0) {
                  poly.add(lower[i])
                }
                if (poly.length > 2) {
                  out.add(polygonCmd(poly, s.color, sGrad, s.pattern))
                }
              }
            } else {
              if (s.kind == "area") {
                for (run in splitRuns(s.values, place)) {
                  val pts = reveal(shape(run))
                  if (pts.length > 1) {
                    val poly: MutableList<PyreonChartPt> = mutableListOf()
                    for (p in pts) {
                      poly.add(p)
                    }
                    val baseY = scaleLinear(sDomain, plot.y + plot.h, plot.y, sDomain.min)
                    poly.add(PyreonChartPt(x = pts[pts.length - 1].x, y = baseY))
                    poly.add(PyreonChartPt(x = pts[0].x, y = baseY))
                    out.add(polygonCmd(poly, s.color, sGrad, s.pattern))
                  }
                }
              } else {
                val pts = place(s.values)
                val radii = (s.radii ?: listOf())
                for (i in 0 until pts.length) {
                  if (!isFiniteValue(s.values[i])) {
                    continue
                  }
                  val fullR = if (radii.length > 0) (radii[i] ?: s.radius) else s.radius
                  if (s.effect == true) {
                    out.add(PyreonDrawCmd(kind = "circle", fill = withAlpha(s.color, 0.12), center = pts[i], radius = fullR * 2.6 * progress))
                    out.add(PyreonDrawCmd(kind = "circle", fill = withAlpha(s.color, 0.25), center = pts[i], radius = fullR * 1.7 * progress))
                  }
                  val lvlP = emphasisLevel(spec, i)
                  if (lvlP > 0) {
                    out.add(PyreonDrawCmd(kind = "circle", fill = withAlpha(t.label, 0.35), center = pts[i], radius = fullR * progress + (if (lvlP == 2) 4.0 else 3.0)))
                  }
                  val r = fullR * progress
                  val pointSymbol = (s.symbol ?: "circle")
                  val fillP = stateFill(spec, s, i, s.color)
                  if (pointSymbol == "circle") {
                    out.add(PyreonDrawCmd(kind = "circle", fill = fillP, center = pts[i], radius = r))
                  } else {
                    out.add(symbolCommand(PyreonChartRect(x = pts[i].x - r, y = pts[i].y - r, w = r * 2.0, h = r * 2.0), pointSymbol, fillP))
                  }
                }
              }
            }
          }
        }
      }
      if (s.showValues == true && progress >= 1.0 && (s.kind == "line" || s.kind == "area" || s.kind == "points" || s.kind == "band")) {
        val fmtP = (spec.yFormat ?: ::plain)
        val labelPts = place(s.values)
        for (i in 0 until labelPts.length) {
          val v = printed(sIdx, i)
          if (!isFiniteValue(v)) {
            continue
          }
          for (c in seriesLabelCmds(s, i, fmtP(v), PyreonChartPt(x = labelPts[i].x, y = labelPts[i].y - (s.radius + 5.0)), "middle", "bottom", t, measure)) {
            out.add(c)
          }
        }
      }
      val eLow = (s.errLow ?: listOf())
      val eHigh = (s.errHigh ?: listOf())
      if (eLow.length > 0 && eHigh.length > 0 && progress >= 1.0 && s.kind != "waterfall") {
        val centres: MutableList<Double> = mutableListOf()
        if (s.kind == "bars") {
          for (r in layoutBars(s.values, plot, sDomain, 0.25)) {
            centres.add(r.x + (r.w).toDouble() / (2.0).toDouble())
          }
        } else {
          for (p in place(s.values)) {
            centres.add(p.x)
          }
        }
        val cap = 4.0
        for (i in 0 until centres.length) {
          val lo = if (i < eLow.length) eLow[i] else (0.0).toDouble() / (0.0).toDouble()
          val hi = if (i < eHigh.length) eHigh[i] else (0.0).toDouble() / (0.0).toDouble()
          if (!isFiniteValue(lo) || !isFiniteValue(hi)) {
            continue
          }
          val cx = centres[i]
          val yLo = scaleLinear(sDomain, plot.y + plot.h, plot.y, lo)
          val yHi = scaleLinear(sDomain, plot.y + plot.h, plot.y, hi)
          out.add(PyreonDrawCmd(kind = "line", from = PyreonChartPt(x = cx, y = yLo), to = PyreonChartPt(x = cx, y = yHi), stroke = t.text, width = 1.0))
          out.add(PyreonDrawCmd(kind = "line", from = PyreonChartPt(x = cx - cap, y = yLo), to = PyreonChartPt(x = cx + cap, y = yLo), stroke = t.text, width = 1.0))
          out.add(PyreonDrawCmd(kind = "line", from = PyreonChartPt(x = cx - cap, y = yHi), to = PyreonChartPt(x = cx + cap, y = yHi), stroke = t.text, width = 1.0))
        }
      }
    }
    for (ls in (spec.lines ?: listOf())) {
      for (c in linesCommands(ls, plot, l.xDomainUsed, yDomain, (spec.effectTime ?: 0.0))) {
        out.add(c)
      }
    }
    val markers = (spec.markers ?: listOf())
    for (m in markers) {
      val rawSeriesIndex = (m.seriesIndex ?: 0.0)
      val s = spec.series[(Math.floor((rawSeriesIndex).toDouble())).toInt()]
      if (s == null) {
        continue
      }
      val n = s.values.length
      if (n == 0) {
        continue
      }
      var idx = -1
      if (m.at == "max") {
        idx = 0
        for (i in 1 until n) {
          if (s.values[i] > s.values[idx]) {
            idx = i
          }
        }
      } else {
        if (m.at == "min") {
          idx = 0
          for (i in 1 until n) {
            if (s.values[i] < s.values[idx]) {
              idx = i
            }
          }
        } else {
          if (m.at == "average") {
            var sum = 0.0
            for (i in 0 until n) {
              sum = sum + s.values[i]
            }
            val mean = (sum).toDouble() / (n).toDouble()
            idx = 0
            for (i in 1 until n) {
              if (Math.abs(s.values[i] - mean) < Math.abs(s.values[idx] - mean)) {
                idx = i
              }
            }
          } else {
            val rawAt = (m.atIndex ?: -1.0)
            if (m.atIndex != null) {
              var jf = 0.0
              for (j in 0 until n) {
                if (jf <= rawAt) {
                  idx = j
                }
                jf = jf + 1.0
              }
              if (idx < 0) {
                idx = 0
              }
            }
          }
        }
      }
      if (idx < 0) {
        continue
      }
      val mDomain = seriesDomain(s, spec, yDomain, y2Domain)
      val xsM = (spec.xValues ?: listOf())
      val segMarker = markerAnchor(spec, rawSeriesIndex, idx, plot, yDomain)
      val p = if (segMarker.length > 0) segMarker[0] else if (spec.horizontal == true) layoutSeriesPointsH(s.values, plot, mDomain)[idx] else if (xsM.length > 0) layoutSeriesPointsAt(s.values, if (seriesOnX2(s, spec)) (s.xs ?: listOf()) else xsM, plot, mDomain, if (seriesOnX2(s, spec)) resolveX2Domain(spec) else l.xDomainUsed)[idx] else layoutSeriesPoints(s.values, plot, mDomain)[idx]
      if (p == null) {
        continue
      }
      val mColor = (m.color ?: s.color)
      out.add(PyreonDrawCmd(kind = "circle", fill = mColor, center = p, radius = ((m.radius ?: 4.0)) * progress))
      val mLabel = (m.label ?: "")
      if (m.label != null && progress >= 1.0) {
        out.add(PyreonDrawCmd(kind = "text", fill = mColor, text = mLabel, at = PyreonChartPt(x = p.x, y = p.y - ((m.radius ?: 4.0)) - 4.0), size = t.fontSize, align = "middle", baseline = "bottom"))
      }
    }
    for (ti in 0 until l.yTicks.length) {
      val tick = l.yTicks[ti]
      if (l.yLabelEvery > 1 && ti % l.yLabelEvery != 0) {
        continue
      }
      out.add(PyreonDrawCmd(kind = "text", fill = t.label, text = tick.label, at = PyreonChartPt(x = if (yRight) yAxisX + 6.0 else yAxisX - 6.0, y = tick.pos), size = t.fontSize, align = if (yRight) "start" else "end", baseline = "middle"))
    }
    for (tick in l.y2Ticks) {
      out.add(PyreonDrawCmd(kind = "text", fill = t.label, text = tick.label, at = PyreonChartPt(x = plot.x + plot.w + y2Off + 6.0, y = tick.pos), size = t.fontSize, align = "start", baseline = "middle"))
    }
    val x2 = (spec.x2Labels ?: listOf())
    if ((x2.length > 0 || l.x2Ticks.length > 0) && spec.showXAxis && spec.horizontal != true) {
      val edgeY = if (xTop) plot.y + plot.h else plot.y
      out.add(PyreonDrawCmd(kind = "line", from = PyreonChartPt(x = plot.x, y = edgeY), to = PyreonChartPt(x = plot.x + plot.w, y = edgeY), stroke = t.axis, width = 1.0))
      for (tk in l.x2Ticks) {
        out.add(PyreonDrawCmd(kind = "text", fill = t.label, text = tk.label, at = PyreonChartPt(x = tk.pos, y = if (xTop) edgeY + 6.0 else edgeY - 6.0), size = t.fontSize, align = "middle", baseline = if (xTop) "top" else "bottom"))
      }
      val inv = categoriesInverted(spec)
      for (ti in 0 until l.xTicks.length) {
        val tick = l.xTicks[ti]
        val j = if (inv) x2.length - 1 - ti else ti
        if (j < 0 || j >= x2.length) {
          continue
        }
        out.add(PyreonDrawCmd(kind = "text", fill = t.label, text = x2[j], at = PyreonChartPt(x = tick.pos, y = if (xTop) edgeY + 6.0 else edgeY - 6.0), size = t.fontSize, align = "middle", baseline = if (xTop) "top" else "bottom"))
      }
      val x2Title = (spec.x2Title ?: "")
      if (x2Title != "") {
        out.add(PyreonDrawCmd(kind = "text", fill = t.label, text = x2Title, at = PyreonChartPt(x = plot.x + (plot.w).toDouble() / (2.0).toDouble(), y = if (xTop) spec.height - 2.0 else 2.0), size = t.fontSize, align = "middle", baseline = if (xTop) "bottom" else "top"))
      }
    }
    var extraIndex = 0.0
    for (a in (spec.extraYAxes ?: listOf())) {
      val left = a.side == "left"
      val ax = if (left) plot.x - ((a.offset ?: 0.0)) else plot.x + plot.w + ((a.offset ?: 0.0))
      var widest = 0.0
      for (tk in l.extraTicks) {
        if (tk.axis != extraIndex) {
          continue
        }
        out.add(PyreonDrawCmd(kind = "text", fill = t.label, text = tk.label, at = PyreonChartPt(x = if (left) ax - 6.0 else ax + 6.0, y = tk.pos), size = t.fontSize, align = if (left) "end" else "start", baseline = "middle"))
        val w = measure(tk.label, t.fontSize)
        if (w > widest) {
          widest = w
        }
      }
      val title = (a.title ?: "")
      if (title != "" && spec.showYAxis) {
        val tx = if (left) ax - 6.0 - widest - t.fontSize * 0.9 else ax + 6.0 + widest + t.fontSize * 0.9
        out.add(PyreonDrawCmd(kind = "text", fill = t.label, text = title, at = PyreonChartPt(x = tx, y = plot.y + (plot.h).toDouble() / (2.0).toDouble()), size = t.fontSize, align = "middle", baseline = "middle", rotate = if (left) -90.0 else 90.0))
      }
      extraIndex = extraIndex + 1.0
    }
    for (ti in 0 until l.xTicks.length) {
      val tick = l.xTicks[ti]
      if (l.xLabelEvery > 1 && ti % l.xLabelEvery != 0) {
        continue
      }
      if (l.xLabelRotate != 0.0) {
        out.add(PyreonDrawCmd(kind = "text", fill = t.label, text = tick.label, at = PyreonChartPt(x = tick.pos, y = if (xTop) xAxisY - 6.0 else xAxisY + 6.0), size = t.fontSize, align = "end", baseline = "middle", rotate = if (xTop) -l.xLabelRotate else l.xLabelRotate))
      } else {
        out.add(PyreonDrawCmd(kind = "text", fill = t.label, text = tick.label, at = PyreonChartPt(x = tick.pos, y = if (xTop) xAxisY - 6.0 else xAxisY + 6.0), size = t.fontSize, align = "middle", baseline = if (xTop) "bottom" else "top"))
      }
    }
    val xTitle = (spec.xTitle ?: "")
    if (xTitle != "" && spec.showXAxis) {
      out.add(PyreonDrawCmd(kind = "text", fill = t.label, text = xTitle, at = PyreonChartPt(x = plot.x + (plot.w).toDouble() / (2.0).toDouble(), y = if (xTop) 2.0 else spec.height - 2.0), size = t.fontSize, align = "middle", baseline = if (xTop) "top" else "bottom"))
    }
    val yTitle = (spec.yTitle ?: "")
    if (yTitle != "" && spec.showYAxis) {
      out.add(PyreonDrawCmd(kind = "text", fill = t.label, text = yTitle, at = PyreonChartPt(x = if (yRight) spec.width - t.fontSize * 0.9 else t.fontSize * 0.9, y = plot.y + (plot.h).toDouble() / (2.0).toDouble()), size = t.fontSize, align = "middle", baseline = "middle", rotate = if (yRight) 90.0 else -90.0))
    }
    val y2Title = (spec.y2Title ?: "")
    if (y2Title != "" && useY2 && spec.showYAxis) {
      out.add(PyreonDrawCmd(kind = "text", fill = t.label, text = y2Title, at = PyreonChartPt(x = spec.width - t.fontSize * 0.9, y = plot.y + (plot.h).toDouble() / (2.0).toDouble()), size = t.fontSize, align = "middle", baseline = "middle", rotate = 90.0))
    }
    return out
  }

fun splitRuns(values: List<Double>, place: (List<Double>) -> List<PyreonChartPt>): List<List<PyreonChartPt>> {
    val runs: MutableList<List<PyreonChartPt>> = mutableListOf()
    var hasGap = false
    for (v in values) {
      if (!isFiniteValue(v)) {
        hasGap = true
      }
    }
    if (!hasGap) {
      runs.add(place(values))
      return runs
    }
    val filled: MutableList<Double> = mutableListOf()
    for (v in values) {
      filled.add(if (isFiniteValue(v)) v else 0.0)
    }
    val pts = place(filled)
    var runStart = -1
    for (i in 0 until pts.length) {
      if (isFiniteValue(values[i])) {
        if (runStart < 0) {
          runStart = i
        }
      } else {
        if (runStart >= 0) {
          val run: MutableList<PyreonChartPt> = mutableListOf()
          for (j in runStart until i) {
            run.add(pts[j])
          }
          runs.add(run)
          runStart = -1
        }
      }
    }
    if (runStart >= 0) {
      val run: MutableList<PyreonChartPt> = mutableListOf()
      for (j in runStart until pts.length) {
        run.add(pts[j])
      }
      runs.add(run)
    }
    return runs
  }

fun symbolCommand(cell: PyreonChartRect, symbol: String, fill: String): PyreonDrawCmd {
    if (symbol == "circle") {
      val r = ((if (cell.w < cell.h) cell.w else cell.h)).toDouble() / (2.0).toDouble()
      return PyreonDrawCmd(kind = "circle", fill = fill, center = PyreonChartPt(x = cell.x + (cell.w).toDouble() / (2.0).toDouble(), y = cell.y + (cell.h).toDouble() / (2.0).toDouble()), radius = r)
    }
    if (symbol == "diamond") {
      return PyreonDrawCmd(kind = "polygon", fill = fill, points = listOf(PyreonChartPt(x = cell.x + (cell.w).toDouble() / (2.0).toDouble(), y = cell.y), PyreonChartPt(x = cell.x + cell.w, y = cell.y + (cell.h).toDouble() / (2.0).toDouble()), PyreonChartPt(x = cell.x + (cell.w).toDouble() / (2.0).toDouble(), y = cell.y + cell.h), PyreonChartPt(x = cell.x, y = cell.y + (cell.h).toDouble() / (2.0).toDouble())))
    }
    if (symbol == "triangle") {
      return PyreonDrawCmd(kind = "polygon", fill = fill, points = listOf(PyreonChartPt(x = cell.x + (cell.w).toDouble() / (2.0).toDouble(), y = cell.y), PyreonChartPt(x = cell.x + cell.w, y = cell.y + cell.h), PyreonChartPt(x = cell.x, y = cell.y + cell.h)))
    }
    return PyreonDrawCmd(kind = "rect", rect = cell, fill = fill)
  }

fun pictorialBar(s: Series, bar: PyreonChartRect, horizontal: Boolean, value: Double, fill: String): PictorialBar {
    val offset = (s.symbolOffset ?: listOf())
    val barLength = if (horizontal) bar.w else bar.h
    val hasBounding = s.symbolBoundingData != null && value != 0.0
    val bound = (s.symbolBoundingData ?: 0.0)
    val boundingLength = if (hasBounding) ((barLength * Math.abs(bound))).toDouble() / (Math.abs(value)).toDouble() else 0.0
    return PictorialBar(bar = bar, horizontal = horizontal, symbol = (s.symbol ?: "rect"), repeat = s.symbolRepeat == true, fill = fill, margin = (s.symbolMargin ?: 0.0), offsetX = if (offset.length > 0) offset[0] else 0.0, offsetY = if (offset.length > 1) offset[1] else 0.0, position = (s.symbolPosition ?: "start"), rotate = (s.symbolRotate ?: 0.0), clip = s.symbolClip == true, hasBounding = hasBounding, boundingLength = boundingLength)
  }

fun barsFor(spec: ChartSpec, index: Int, measure: (String, Double) -> Double): List<PyreonChartRect> = barsForIn(spec, index, layoutChart(spec, measure).plot)

fun barsForIn(raw: ChartSpec, index: Int, plot: PyreonChartRect): List<PyreonChartRect> {
    val spec = geometrySpec(raw)
    val s = spec.series[index]
    if (s == null || (s.kind != "bars" && s.kind != "waterfall")) {
      return listOf()
    }
    val dom = seriesDomain(s, spec, resolveYDomain(spec), resolveY2Domain(spec))
    if (s.kind == "waterfall") {
      val rects: MutableList<PyreonChartRect> = mutableListOf()
      for (i in 0 until s.values.length) {
        rects.add(PyreonChartRect(x = 0.0, y = 0.0, w = -1.0, h = -1.0))
      }
      for (st in layoutWaterfall(s.values, plot, dom, 0.25)) {
        rects[st.datumIndex] = st.rect
      }
      return rects
    }
    return layoutBars(s.values, plot, dom, 0.25)
  }

fun stackedHitAt(spec: ChartSpec, measure: (String, Double) -> Double, px: Double, py: Double): Int = stackedHitIn(spec, layoutChart(spec, measure).plot, px, py)

fun markerAnchor(spec: ChartSpec, seriesIdx: Double, idx: Int, plot: PyreonChartRect, yDomain: Domain): List<PyreonChartPt> {
    val out: MutableList<PyreonChartPt> = mutableListOf()
    var kind = ""
    var f = 0.0
    for (q in spec.series) {
      if (f == seriesIdx) {
        kind = q.kind
      }
      f = f + 1.0
    }
    if (kind != "stacked" && kind != "grouped") {
      return out
    }
    var which = -1
    var seen = 0
    var g = 0.0
    for (q in spec.series) {
      if (q.kind == kind) {
        if (g == seriesIdx) {
          which = seen
        }
        seen = seen + 1
      }
      g = g + 1.0
    }
    if (which < 0) {
      return out
    }
    val values = spec.series.filter({ q -> q.kind == kind }).map({ q -> q.values })
    val flipped = spec.horizontal == true
    val segs = if (kind == "stacked") if (flipped) layoutStackedBarsH(values, plot, yDomain, 0.25) else layoutStackedBars(values, plot, yDomain, 0.25) else if (flipped) layoutGroupedBarsH(values, plot, yDomain, 0.25) else layoutGroupedBars(values, plot, yDomain, 0.25)
    for (seg in segs) {
      if (seg.seriesIndex != which) {
        continue
      }
      if (seg.datumIndex != idx) {
        continue
      }
      if (flipped) {
        out.add(PyreonChartPt(x = seg.rect.x + seg.rect.w, y = seg.rect.y + (seg.rect.h).toDouble() / (2.0).toDouble()))
      } else {
        out.add(PyreonChartPt(x = seg.rect.x + (seg.rect.w).toDouble() / (2.0).toDouble(), y = seg.rect.y))
      }
    }
    return out
  }

fun stackedHitIn(raw: ChartSpec, plot: PyreonChartRect, px: Double, py: Double): Int {
    val spec = geometrySpec(raw)
    val yDomain = resolveYDomain(spec)
    val flipped = raw.horizontal == true
    for (kind in listOf("stacked", "grouped")) {
      val series = spec.series.filter({ s -> s.kind == kind })
      if (series.length == 0) {
        continue
      }
      val values = series.map({ s -> s.values })
      val segs = if (kind == "stacked") if (flipped) layoutStackedBarsH(values, plot, yDomain, 0.25) else layoutStackedBars(values, plot, yDomain, 0.25) else if (flipped) layoutGroupedBarsH(values, plot, yDomain, 0.25) else layoutGroupedBars(values, plot, yDomain, 0.25)
      for (seg in segs) {
        val r = seg.rect
        if (px >= r.x && px <= r.x + r.w && py >= r.y && py <= r.y + r.h) {
          return categoryIndex(raw, seg.datumIndex)
        }
      }
    }
    return -1
  }

fun ohlcExtent(candles: List<Ohlc>): Domain {
    if (candles.length == 0) {
      return Domain(min = 0.0, max = 1.0)
    }
    var lo = candles[0].low
    var hi = candles[0].high
    for (c in candles) {
      if (c.low < lo) {
        lo = c.low
      }
      if (c.high > hi) {
        hi = c.high
      }
    }
    if (hi <= lo) {
      return Domain(min = lo - 1.0, max = lo + 1.0)
    }
    return Domain(min = lo, max = hi)
  }

fun renderCandles(candles: List<Ohlc>, plot: PyreonChartRect, domain: Domain, options: CandleOptions? = null): List<PyreonDrawCmd> {
    val up = (options?.upColor ?: "#15803d")
    val down = (options?.downColor ?: "#b42318")
    val rawRatio = (options?.widthRatio ?: 0.6)
    val ratio = if (rawRatio < 0.05) 0.05 else if (rawRatio > 0.9) 0.9 else rawRatio
    val out: MutableList<PyreonDrawCmd> = mutableListOf()
    val n = candles.length
    if (n == 0) {
      return out
    }
    var nF = 0.0
    for (i in 0 until n) {
      nF = nF + 1.0
    }
    val band = (plot.w).toDouble() / (nF).toDouble()
    val bw = band * ratio
    val y0 = plot.y + plot.h
    var iF = 0.0
    for (i in 0 until n) {
      val c = candles[i]
      val cx = plot.x + band * iF + (band).toDouble() / (2.0).toDouble()
      val color = if (c.close >= c.open) up else down
      out.add(PyreonDrawCmd(kind = "line", from = PyreonChartPt(x = cx, y = scaleLinear(domain, y0, plot.y, c.high)), to = PyreonChartPt(x = cx, y = scaleLinear(domain, y0, plot.y, c.low)), stroke = color, width = 1.0))
      val yo = scaleLinear(domain, y0, plot.y, c.open)
      val yc = scaleLinear(domain, y0, plot.y, c.close)
      val top = if (yo < yc) yo else yc
      val rawH = yc - yo
      val h = if (rawH < 0.0) -rawH else rawH
      out.add(PyreonDrawCmd(kind = "rect", rect = PyreonChartRect(x = cx - (bw).toDouble() / (2.0).toDouble(), y = top, w = bw, h = if (h < 1.0) 1.0 else h), fill = color))
      iF = iF + 1.0
    }
    return out
  }

fun hitCandle(count: Int, plot: PyreonChartRect, px: Double, py: Double): Int {
    if (count <= 0) {
      return -1
    }
    if (px < plot.x || px > plot.x + plot.w) {
      return -1
    }
    if (py < plot.y || py > plot.y + plot.h) {
      return -1
    }
    val band = (plot.w).toDouble() / (count).toDouble()
    val target = ((px - plot.x)).toDouble() / (band).toDouble()
    var i = 0
    var jf = 0.0
    for (j in 0 until count) {
      if (jf <= target) {
        i = j
      }
      jf = jf + 1.0
    }
    return i
  }

fun buildHeatGrid(cols: List<String>, rows: List<String>, colOf: List<Double>, rowOf: List<Double>, values: List<Double>): HeatGrid {
    val n1 = if (colOf.length < rowOf.length) colOf.length else rowOf.length
    val n = if (n1 < values.length) n1 else values.length
    val cellCol: MutableList<Double> = mutableListOf()
    val cellRow: MutableList<Double> = mutableListOf()
    val cellVal: MutableList<Double> = mutableListOf()
    for (i in 0 until n) {
      val c = colOf[i]
      val r = rowOf[i]
      if (c < 0.0 || r < 0.0) {
        continue
      }
      var found = -1
      for (k in 0 until cellCol.length) {
        if (found < 0 && cellCol[k] == c && cellRow[k] == r) {
          found = k
        }
      }
      if (found < 0) {
        cellCol.add(c)
        cellRow.add(r)
        cellVal.add(values[i])
      } else {
        cellVal[found] = cellVal[found] + values[i]
      }
    }
    val cells: MutableList<HeatCell> = mutableListOf()
    var minV = 0.0
    var maxV = 0.0
    for (k in 0 until cellCol.length) {
      cells.add(HeatCell(col = cellCol[k], row = cellRow[k], value = cellVal[k]))
      if (k == 0) {
        minV = cellVal[k]
        maxV = cellVal[k]
      } else {
        if (cellVal[k] < minV) {
          minV = cellVal[k]
        }
        if (cellVal[k] > maxV) {
          maxV = cellVal[k]
        }
      }
    }
    return HeatGrid(cols = cols, rows = rows, cells = cells, min = minV, max = maxV)
  }

fun heatHexDigit(c: Double): Double {
    if (c >= 48.0 && c <= 57.0) {
      return c - 48.0
    }
    if (c >= 97.0 && c <= 102.0) {
      return c - 87.0
    }
    if (c >= 65.0 && c <= 70.0) {
      return c - 55.0
    }
    return 0.0
  }

fun heatChannel(hex: String, at: Int): Double {
    if (hex.length < at + 2) {
      return 0.0
    }
    return heatHexDigit(hex[(at).toInt()].code.toDouble()) * 16.0 + heatHexDigit(hex[(at + 1).toInt()].code.toDouble())
  }

fun heatHashOffset(hex: String): Int {
    if (hex.length > 0 && hex[(0).toInt()].code.toDouble() == 35.0) {
      return 1
    }
    return 0
  }

fun rampColor(stops: List<String>, t: Double): String {
    val n = stops.length
    if (n == 0) {
      return "rgb(0, 0, 0)"
    }
    if (n == 1 || t <= 0.0) {
      val s0 = stops[0]
      val o0 = heatHashOffset(s0)
      return "rgb(${Math.round(heatChannel(s0, o0))}, ${Math.round(heatChannel(s0, o0 + 2))}, ${Math.round(heatChannel(s0, o0 + 4))})"
    }
    val clamped = if (t >= 1.0) 1.0 else t
    var spanF = 0.0
    for (i in 1 until n) {
      spanF = spanF + 1.0
    }
    val pos = clamped * spanF
    val rawIdx = Math.floor(pos)
    val idx = if (rawIdx > spanF - 1.0) spanF - 1.0 else rawIdx
    val frac = pos - idx
    var a = stops[0]
    var b = stops[1]
    var iF = 0.0
    val last = n - 1
    for (i in 0 until last) {
      if (iF == idx) {
        a = stops[i]
        b = stops[i + 1]
      }
      iF = iF + 1.0
    }
    val oa = heatHashOffset(a)
    val ob = heatHashOffset(b)
    val r = heatChannel(a, oa) + (heatChannel(b, ob) - heatChannel(a, oa)) * frac
    val g = heatChannel(a, oa + 2) + (heatChannel(b, ob + 2) - heatChannel(a, oa + 2)) * frac
    val bl = heatChannel(a, oa + 4) + (heatChannel(b, ob + 4) - heatChannel(a, oa + 4)) * frac
    return "rgb(${Math.round(r)}, ${Math.round(g)}, ${Math.round(bl)})"
  }

fun visualOutside(v: Double, inRange: Domain?, outBands: List<Double>?): Boolean {
    val lo = (inRange?.min ?: v)
    val hi = (inRange?.max ?: v)
    if (v < lo || v > hi) {
      return true
    }
    val bands = (outBands ?: listOf())
    var i = 0
    while (i + 1 < bands.length) {
      if (v >= bands[i] && v <= bands[i + 1]) {
        return true
      }
      i = i + 2
    }
    return false
  }

fun renderHeat(options: HeatmapOptions): List<PyreonDrawCmd> {
    val grid = options.grid
    val plot = options.plot
    val stops = (options.stops ?: HEAT_RAMP)
    val gap = (options.gap ?: 1.0)
    val rawP = (options.progress ?: 1.0)
    val progress = if (rawP < 0.0) 0.0 else if (rawP > 1.0) 1.0 else rawP
    val out: MutableList<PyreonDrawCmd> = mutableListOf()
    val nc = grid.cols.length
    val nr = grid.rows.length
    if (nc == 0 || nr == 0) {
      return out
    }
    var ncF = 0.0
    for (i in 0 until nc) {
      ncF = ncF + 1.0
    }
    var nrF = 0.0
    for (i in 0 until nr) {
      nrF = nrF + 1.0
    }
    val cw = (plot.w).toDouble() / (ncF).toDouble()
    val ch = (plot.h).toDouble() / (nrF).toDouble()
    val lo = (options.domain?.min ?: grid.min)
    val span = ((options.domain?.max ?: grid.max)) - lo
    val outColor = (options.outColor ?: "#cccccc")
    for (cell in grid.cells) {
      if (cell.col >= ncF || cell.row >= nrF) {
        continue
      }
      val rawT = if (span <= 0.0) 1.0 else ((cell.value - lo)).toDouble() / (span).toDouble()
      val t = if (rawT < 0.0) 0.0 else if (rawT > 1.0) 1.0 else rawT
      val fullW = cw - gap
      val fullH = ch - gap
      val w = fullW * progress
      val h = fullH * progress
      val x = plot.x + cell.col * cw + (gap).toDouble() / (2.0).toDouble() + ((fullW - w)).toDouble() / (2.0).toDouble()
      val y = plot.y + cell.row * ch + (gap).toDouble() / (2.0).toDouble() + ((fullH - h)).toDouble() / (2.0).toDouble()
      out.add(PyreonDrawCmd(kind = "rect", rect = PyreonChartRect(x = x, y = y, w = w, h = h), fill = if (visualOutside(cell.value, options.inRange, options.outBands)) outColor else rampColor(stops, t)))
    }
    return out
  }

fun hitHeatCell(grid: HeatGrid, plot: PyreonChartRect, gap: Double, px: Double, py: Double): Int {
    val nc = grid.cols.length
    val nr = grid.rows.length
    if (nc == 0 || nr == 0) {
      return -1
    }
    if (px < plot.x || px > plot.x + plot.w || py < plot.y || py > plot.y + plot.h) {
      return -1
    }
    var ncF = 0.0
    for (i in 0 until nc) {
      ncF = ncF + 1.0
    }
    var nrF = 0.0
    for (i in 0 until nr) {
      nrF = nrF + 1.0
    }
    val cw = (plot.w).toDouble() / (ncF).toDouble()
    val ch = (plot.h).toDouble() / (nrF).toDouble()
    val rawCol = Math.floor(((px - plot.x)).toDouble() / (cw).toDouble())
    val col = if (rawCol > ncF - 1.0) ncF - 1.0 else rawCol
    val rawRow = Math.floor(((py - plot.y)).toDouble() / (ch).toDouble())
    val row = if (rawRow > nrF - 1.0) nrF - 1.0 else rawRow
    val inX = px - (plot.x + col * cw)
    val inY = py - (plot.y + row * ch)
    if (inX < (gap).toDouble() / (2.0).toDouble() || inX > cw - (gap).toDouble() / (2.0).toDouble()) {
      return -1
    }
    if (inY < (gap).toDouble() / (2.0).toDouble() || inY > ch - (gap).toDouble() / (2.0).toDouble()) {
      return -1
    }
    var hit = -1
    for (i in 0 until grid.cells.length) {
      val c = grid.cells[i]
      if (hit < 0 && c.col == col && c.row == row) {
        hit = i
      }
    }
    return hit
  }

fun labelWidth(s: VisualStrip): Double = s.fontSize * 3.2

fun pieceTextWidth(s: VisualStrip, label: String): Double = label.length * s.fontSize * 0.55

fun span(d: Domain): Double = d.max - d.min

fun barOrigin(s: VisualStrip, at: PyreonChartPt): PyreonChartPt {
    if (s.vertical) {
      return PyreonChartPt(x = at.x, y = at.y + s.fontSize + STRIP_GAP)
    }
    return PyreonChartPt(x = at.x + labelWidth(s) + STRIP_GAP, y = at.y)
  }

fun visualStripSize(s: VisualStrip): PyreonChartPt {
    if (s.piecewise) {
      if (s.vertical) {
        var widest = 0.0
        for (p in s.pieces) {
          if (pieceTextWidth(s, p.label) > widest) {
            widest = pieceTextWidth(s, p.label)
          }
        }
        var n = 0.0
        for (_p in s.pieces) {
          n = n + 1.0
        }
        return PyreonChartPt(x = s.itemSize + STRIP_GAP + widest, y = if (n <= 0) 0.0 else n * (s.itemSize + STRIP_GAP) - STRIP_GAP)
      }
      var w = 0.0
      for (p in s.pieces) {
        w = w + s.itemSize + STRIP_GAP + pieceTextWidth(s, p.label) + STRIP_GAP * 2.0
      }
      return PyreonChartPt(x = if (w <= 0.0) 0.0 else w - STRIP_GAP * 2.0, y = s.itemSize)
    }
    val handleSpace = if (s.calculable) STRIP_HANDLE + STRIP_GAP + labelWidth(s) else 0.0
    if (s.vertical) {
      var w = s.itemSize + handleSpace
      return PyreonChartPt(x = if (w > labelWidth(s)) w else labelWidth(s), y = s.fontSize * 2.0 + STRIP_GAP * 2.0 + s.itemLength)
    }
    return PyreonChartPt(x = labelWidth(s) * 2.0 + STRIP_GAP * 2.0 + s.itemLength, y = s.itemSize + (if (s.calculable) STRIP_HANDLE + STRIP_GAP + s.fontSize + 2.0 else 0.0))
  }

fun fraction(s: VisualStrip, v: Double): Double {
    val sp = span(s.domain)
    if (!(sp > 0.0)) {
      return 1.0
    }
    val t = ((v - s.domain.min)).toDouble() / (sp).toDouble()
    return if (t < 0.0) 0.0 else if (t > 1.0) 1.0 else t
  }

fun valuePoint(s: VisualStrip, at: PyreonChartPt, v: Double): PyreonChartPt {
    val o = barOrigin(s, at)
    val t = fraction(s, v)
    if (s.vertical) {
      return PyreonChartPt(x = o.x + s.itemSize, y = o.y + (1.0 - t) * s.itemLength)
    }
    return PyreonChartPt(x = o.x + t * s.itemLength, y = o.y + s.itemSize)
  }

fun pieceContains(p: VisualPiece, v: Double): Boolean {
    if (p.min != null && v < ((p.min ?: v))) {
      return false
    }
    if (p.max != null && v > ((p.max ?: v))) {
      return false
    }
    return true
  }

fun visualInRange(s: VisualStrip, v: Double, range: Domain, selected: List<Boolean>): Boolean {
    if (s.piecewise) {
      var inAny = false
      for (i in 0 until s.pieces.length) {
        if (!pieceContains(s.pieces[i], v)) {
          continue
        }
        inAny = true
        if (i >= selected.length || selected[i]) {
          return true
        }
      }
      return !inAny
    }
    return v >= range.min && v <= range.max
  }

fun visualColorFor(s: VisualStrip, v: Double, range: Domain, selected: List<Boolean>): String {
    if (!visualInRange(s, v, range, selected)) {
      return s.outColor
    }
    if (s.piecewise) {
      for (p in s.pieces) {
        if (pieceContains(p, v)) {
          return p.color
        }
      }
    }
    return rampColor(s.stops, fraction(s, v))
  }

fun renderVisualStrip(s: VisualStrip, at: PyreonChartPt, range: Domain, selected: List<Boolean>): List<PyreonDrawCmd> {
    val out: MutableList<PyreonDrawCmd> = mutableListOf()
    val fs = s.fontSize
    if (s.piecewise) {
      var x = at.x
      var y = at.y
      for (i in 0 until s.pieces.length) {
        val p = s.pieces[i]
        val on = i >= selected.length || selected[i]
        out.add(PyreonDrawCmd(kind = "rect", rect = PyreonChartRect(x = x, y = y, w = s.itemSize, h = s.itemSize), fill = if (on) p.color else s.outColor))
        out.add(PyreonDrawCmd(kind = "text", fill = if (on) s.labelColor else s.outColor, text = p.label, at = PyreonChartPt(x = x + s.itemSize + STRIP_GAP, y = y + (s.itemSize).toDouble() / (2.0).toDouble()), size = fs, align = "start", baseline = "middle"))
        if (s.vertical) {
          y = y + s.itemSize + STRIP_GAP
        } else {
          x = x + s.itemSize + STRIP_GAP + pieceTextWidth(s, p.label) + STRIP_GAP * 2.0
        }
      }
      return out
    }
    val o = barOrigin(s, at)
    val high = if (s.highText == "") plain(s.domain.max) else s.highText
    val low = if (s.lowText == "") plain(s.domain.min) else s.lowText
    var i = 0.0
    while (i < STRIP_COUNT) {
      val t = if (s.vertical) 1.0 - ((i + 0.5)).toDouble() / (STRIP_COUNT).toDouble() else ((i + 0.5)).toDouble() / (STRIP_COUNT).toDouble()
      val v = s.domain.min + t * span(s.domain)
      val fill = if (s.calculable && (v < range.min || v > range.max)) s.outColor else rampColor(s.stops, t)
      if (s.vertical) {
        out.add(PyreonDrawCmd(kind = "rect", rect = PyreonChartRect(x = o.x, y = o.y + ((s.itemLength * i)).toDouble() / (STRIP_COUNT).toDouble(), w = s.itemSize, h = (s.itemLength).toDouble() / (STRIP_COUNT).toDouble() + 0.5), fill = fill))
      } else {
        out.add(PyreonDrawCmd(kind = "rect", rect = PyreonChartRect(x = o.x + ((s.itemLength * i)).toDouble() / (STRIP_COUNT).toDouble(), y = o.y, w = (s.itemLength).toDouble() / (STRIP_COUNT).toDouble() + 0.5, h = s.itemSize), fill = fill))
      }
      i = i + 1.0
    }
    if (s.vertical) {
      out.add(PyreonDrawCmd(kind = "text", fill = s.labelColor, text = high, at = PyreonChartPt(x = o.x + (s.itemSize).toDouble() / (2.0).toDouble(), y = at.y), size = fs, align = "middle", baseline = "top"))
      out.add(PyreonDrawCmd(kind = "text", fill = s.labelColor, text = low, at = PyreonChartPt(x = o.x + (s.itemSize).toDouble() / (2.0).toDouble(), y = o.y + s.itemLength + STRIP_GAP), size = fs, align = "middle", baseline = "top"))
    } else {
      out.add(PyreonDrawCmd(kind = "text", fill = s.labelColor, text = low, at = PyreonChartPt(x = o.x - STRIP_GAP, y = o.y + (s.itemSize).toDouble() / (2.0).toDouble()), size = fs, align = "end", baseline = "middle"))
      out.add(PyreonDrawCmd(kind = "text", fill = s.labelColor, text = high, at = PyreonChartPt(x = o.x + s.itemLength + STRIP_GAP, y = o.y + (s.itemSize).toDouble() / (2.0).toDouble()), size = fs, align = "start", baseline = "middle"))
    }
    if (!s.calculable) {
      return out
    }
    val ends = listOf(range.min, range.max)
    for (e in 0 until 2) {
      val v = ends[e]
      val p = valuePoint(s, at, v)
      val color = rampColor(s.stops, fraction(s, v))
      if (s.vertical) {
        out.add(PyreonDrawCmd(kind = "polygon", fill = color, points = listOf(PyreonChartPt(x = p.x, y = p.y), PyreonChartPt(x = p.x + STRIP_HANDLE, y = p.y - (STRIP_HANDLE).toDouble() / (2.0).toDouble()), PyreonChartPt(x = p.x + STRIP_HANDLE, y = p.y + (STRIP_HANDLE).toDouble() / (2.0).toDouble()))))
        out.add(PyreonDrawCmd(kind = "text", fill = s.labelColor, text = plain(v), at = PyreonChartPt(x = p.x + STRIP_HANDLE + STRIP_GAP, y = p.y), size = fs, align = "start", baseline = "middle"))
      } else {
        out.add(PyreonDrawCmd(kind = "polygon", fill = color, points = listOf(PyreonChartPt(x = p.x, y = p.y), PyreonChartPt(x = p.x - (STRIP_HANDLE).toDouble() / (2.0).toDouble(), y = p.y + STRIP_HANDLE), PyreonChartPt(x = p.x + (STRIP_HANDLE).toDouble() / (2.0).toDouble(), y = p.y + STRIP_HANDLE))))
        out.add(PyreonDrawCmd(kind = "text", fill = s.labelColor, text = plain(v), at = PyreonChartPt(x = p.x, y = p.y + STRIP_HANDLE + STRIP_GAP), size = fs, align = "middle", baseline = "top"))
      }
    }
    return out
  }

fun visualStripHandleAt(s: VisualStrip, at: PyreonChartPt, range: Domain, px: Double, py: Double): Double {
    if (s.piecewise || !s.calculable) {
      return -1.0
    }
    val reach = STRIP_HANDLE + 4.0
    var best = -1.0
    var bestD = reach * 1.5
    var e = 0.0
    while (e < 2.0) {
      val p = valuePoint(s, at, if (e == 0.0) range.min else range.max)
      val cx = if (s.vertical) p.x + (STRIP_HANDLE).toDouble() / (2.0).toDouble() else p.x
      val cy = if (s.vertical) p.y else p.y + (STRIP_HANDLE).toDouble() / (2.0).toDouble()
      val d = Math.abs(px - cx) + Math.abs(py - cy)
      if (d <= bestD) {
        bestD = d
        best = e
      }
      e = e + 1.0
    }
    return best
  }

fun visualStripValueAt(s: VisualStrip, at: PyreonChartPt, px: Double, py: Double): Double {
    val o = barOrigin(s, at)
    val raw = if (s.vertical) 1.0 - ((py - o.y)).toDouble() / ((if (s.itemLength > 0.0) s.itemLength else 1.0)).toDouble() else ((px - o.x)).toDouble() / ((if (s.itemLength > 0.0) s.itemLength else 1.0)).toDouble()
    val t = if (raw < 0.0) 0.0 else if (raw > 1.0) 1.0 else raw
    return s.domain.min + t * span(s.domain)
  }

fun visualStripDrag(s: VisualStrip, range: Domain, handle: Double, value: Double): Domain {
    if (handle == 0.0) {
      return Domain(min = if (value < range.max) value else range.max, max = range.max)
    }
    return Domain(min = range.min, max = if (value > range.min) value else range.min)
  }

fun visualStripPieceAt(s: VisualStrip, at: PyreonChartPt, px: Double, py: Double): Double {
    if (!s.piecewise) {
      return -1.0
    }
    var x = at.x
    var y = at.y
    var i = 0.0
    for (piece in s.pieces) {
      val w = s.itemSize + STRIP_GAP + pieceTextWidth(s, piece.label)
      if (px >= x && px <= x + w && py >= y && py <= y + s.itemSize) {
        return i
      }
      i = i + 1.0
      if (s.vertical) {
        y = y + s.itemSize + STRIP_GAP
      } else {
        x = x + w + STRIP_GAP * 2.0
      }
    }
    return -1.0
  }

fun visualStripToggle(s: VisualStrip, selected: List<Boolean>, index: Double): List<Boolean> {
    val out: MutableList<Boolean> = mutableListOf()
    var i = 0.0
    for (_p in s.pieces) {
      val on = i >= selected.length || selected[(i).toInt()]
      out.add(if (i == index) !on else on)
      i = i + 1.0
    }
    return out
  }

fun visualOutBands(s: VisualStrip, selected: List<Boolean>): List<Double> {
    val out: MutableList<Double> = mutableListOf()
    if (!s.piecewise) {
      return out
    }
    val reach = (s.domain.max - s.domain.min) * 1000.0 + 1000000.0
    var i = 0.0
    for (p in s.pieces) {
      val on = i >= selected.length || selected[(i).toInt()]
      if (!on) {
        out.add((p.min ?: s.domain.min - reach))
        out.add((p.max ?: s.domain.max + reach))
      }
      i = i + 1.0
    }
    return out
  }

fun visualStripPlace(s: VisualStrip, w: Double, h: Double): VisualStripPlacement {
    val size = visualStripSize(s)
    val margin = 8.0
    if (s.vertical) {
      val chartW = w - size.x - margin
      return VisualStripPlacement(at = PyreonChartPt(x = w - size.x, y = if (h - size.y > 0.0) h - size.y else 0.0), chartW = if (chartW > 0.0) chartW else 0.0, chartH = h)
    }
    val chartH = h - size.y - margin
    return VisualStripPlacement(at = PyreonChartPt(x = 0.0, y = h - size.y), chartW = w, chartH = if (chartH > 0.0) chartH else 0.0)
  }

fun axisSpan(s: TimelineStrip, box: PyreonChartRect): TimelineAxis {
    var left = box.x + PAD
    if (s.showPlay) {
      left = left + BTN + BTN_GAP
    }
    if (s.showPrev) {
      left = left + BTN + BTN_GAP
    }
    var right = box.x + box.w - PAD
    if (s.showNext) {
      right = right - BTN - BTN_GAP
    }
    return TimelineAxis(x0 = left, x1 = if (right > left) right else left, cy = box.y + box.h * 0.4)
  }

fun stepCount(s: TimelineStrip): Double {
    var n = 0.0
    for (_l in s.labels) {
      n = n + 1.0
    }
    return n
  }

fun checkpointX(s: TimelineStrip, box: PyreonChartRect, i: Double): Double {
    val a = axisSpan(s, box)
    val n = stepCount(s)
    return if (n <= 1.0) ((a.x0 + a.x1)).toDouble() / (2.0).toDouble() else a.x0 + (((a.x1 - a.x0) * i)).toDouble() / ((n - 1.0)).toDouble()
  }

fun playCenter(s: TimelineStrip, box: PyreonChartRect): Double = box.x + PAD + (BTN).toDouble() / (2.0).toDouble()

fun prevCenter(s: TimelineStrip, box: PyreonChartRect): Double = box.x + PAD + (if (s.showPlay) BTN + BTN_GAP else 0.0) + (BTN).toDouble() / (2.0).toDouble()

fun nextCenter(_s: TimelineStrip, box: PyreonChartRect): Double = box.x + box.w - PAD - (BTN).toDouble() / (2.0).toDouble()

fun renderTimeline(s: TimelineStrip, box: PyreonChartRect, current: Double, playing: Boolean): List<PyreonDrawCmd> {
    val out: MutableList<PyreonDrawCmd> = mutableListOf()
    val n = stepCount(s)
    if (n <= 0.0) {
      return out
    }
    val a = axisSpan(s, box)
    val cy = a.cy
    out.add(PyreonDrawCmd(kind = "line", from = PyreonChartPt(x = a.x0, y = cy), to = PyreonChartPt(x = a.x1, y = cy), stroke = s.line, width = 1.0))
    var i = 0.0
    for (label in s.labels) {
      val x = checkpointX(s, box, i)
      val on = i == current
      out.add(PyreonDrawCmd(kind = "circle", fill = s.accent, center = PyreonChartPt(x = x, y = cy), radius = if (on) 5.0 else 3.5))
      if (!on) {
        out.add(PyreonDrawCmd(kind = "circle", fill = "#ffffff", center = PyreonChartPt(x = x, y = cy), radius = 2.5))
      }
      out.add(PyreonDrawCmd(kind = "text", fill = if (on) s.accent else s.label, text = label, at = PyreonChartPt(x = x, y = cy + 8.0), size = s.fontSize, align = "middle", baseline = "top"))
      i = i + 1.0
    }
    val h = (BTN).toDouble() / (2.0).toDouble()
    if (s.showPlay) {
      val px = playCenter(s, box)
      if (playing) {
        out.add(PyreonDrawCmd(kind = "rect", rect = PyreonChartRect(x = px - h * 0.7, y = cy - h * 0.7, w = h * 0.5, h = h * 1.4), fill = s.accent))
        out.add(PyreonDrawCmd(kind = "rect", rect = PyreonChartRect(x = px + h * 0.2, y = cy - h * 0.7, w = h * 0.5, h = h * 1.4), fill = s.accent))
      } else {
        out.add(PyreonDrawCmd(kind = "polygon", fill = s.accent, points = listOf(PyreonChartPt(x = px - h * 0.6, y = cy - h * 0.75), PyreonChartPt(x = px + h * 0.8, y = cy), PyreonChartPt(x = px - h * 0.6, y = cy + h * 0.75))))
      }
    }
    if (s.showPrev) {
      val px = prevCenter(s, box)
      out.add(PyreonDrawCmd(kind = "polygon", fill = s.line, points = listOf(PyreonChartPt(x = px + h * 0.6, y = cy - h * 0.7), PyreonChartPt(x = px - h * 0.6, y = cy), PyreonChartPt(x = px + h * 0.6, y = cy + h * 0.7))))
    }
    if (s.showNext) {
      val px = nextCenter(s, box)
      out.add(PyreonDrawCmd(kind = "polygon", fill = s.line, points = listOf(PyreonChartPt(x = px - h * 0.6, y = cy - h * 0.7), PyreonChartPt(x = px + h * 0.6, y = cy), PyreonChartPt(x = px - h * 0.6, y = cy + h * 0.7))))
    }
    return out
  }

fun timelineHit(s: TimelineStrip, box: PyreonChartRect, px: Double, py: Double): TimelineHit {
    val none = TimelineHit(kind = 0.0, index = -1.0)
    if (py < box.y || py > box.y + box.h || stepCount(s) <= 0.0) {
      return none
    }
    val cy = axisSpan(s, box).cy
    val reach = (BTN).toDouble() / (2.0).toDouble() + 4.0
    val near = { cx: Double -> (if (px - cx < 0.0) cx - px else px - cx) <= reach && (if (py - cy < 0.0) cy - py else py - cy) <= reach + 6.0 }
    if (s.showPlay && near(playCenter(s, box))) {
      return TimelineHit(kind = 2.0, index = -1.0)
    }
    if (s.showPrev && near(prevCenter(s, box))) {
      return TimelineHit(kind = 3.0, index = -1.0)
    }
    if (s.showNext && near(nextCenter(s, box))) {
      return TimelineHit(kind = 4.0, index = -1.0)
    }
    var best = -1.0
    var bestD = 14.0
    var i = 0.0
    for (_l in s.labels) {
      val d = px - checkpointX(s, box, i)
      val ad = if (d < 0.0) 0.0 - d else d
      if (ad <= bestD) {
        bestD = ad
        best = i
      }
      i = i + 1.0
    }
    return if (best < 0.0) none else TimelineHit(kind = 1.0, index = best)
  }

fun timelineAdvance(s: TimelineStrip, current: Double, dir: Double, wrap: Boolean): Double {
    val n = stepCount(s)
    if (n <= 0.0) {
      return -1.0
    }
    val next = current + dir
    if (next >= 0.0 && next < n) {
      return next
    }
    if (!wrap) {
      return -1.0
    }
    return if (next < 0.0) n - 1.0 else 0.0
  }

fun timelineTick(s: TimelineStrip, current: Double): Double = timelineAdvance(s, current, if (s.rewind) -1.0 else 1.0, s.loop)

fun layoutFunnel(stages: List<FunnelStage>, plot: PyreonChartRect, options: FunnelOptions? = null): List<FunnelStageGeometry> {
    val out: MutableList<FunnelStageGeometry> = mutableListOf()
    val n = stages.length
    if (n == 0) {
      return out
    }
    val gap = (options?.gap ?: 2.0)
    val rawMin = (options?.minWidthRatio ?: 0.0)
    val minRatio = if (rawMin < 0.0) 0.0 else if (rawMin > 1.0) 1.0 else rawMin
    val sort = (options?.sort ?: "descending")
    val align = (options?.align ?: "center")
    val order: MutableList<Int> = mutableListOf()
    var nf = 0.0
    for (i in 0 until n) {
      order.add(i)
      nf = nf + 1.0
    }
    if (sort != "none") {
      for (i in 1 until n) {
        val cur = order[i]
        var j = i - 1
        while (j >= 0) {
          val a = stages[order[j]].value
          val b = stages[cur].value
          val swap = if (sort == "descending") a < b else a > b
          if (!swap) {
            break
          }
          order[j + 1] = order[j]
          j = j - 1
        }
        order[j + 1] = cur
      }
    }
    var maxV = 0.0
    for (s in stages) {
      if (s.value > maxV) {
        maxV = s.value
      }
    }
    val stageH = ((plot.h - gap * (nf - 1.0))).toDouble() / (nf).toDouble()
    var kf = 0.0
    for (k in 0 until n) {
      val idx = order[k]
      val next = if (k + 1 < n) order[k + 1] else -1
      val topRatio = if (maxV <= 0.0) 1.0 else (stages[idx].value).toDouble() / (maxV).toDouble()
      val topW = plot.w * (if (topRatio < minRatio) minRatio else topRatio)
      val nextRatio = if (next >= 0) (if (maxV <= 0.0) 1.0 else (stages[next].value).toDouble() / (maxV).toDouble()) else minRatio
      val bottomW = plot.w * (if (nextRatio < minRatio) minRatio else nextRatio)
      val top = plot.y + kf * (stageH + gap)
      val cx = if (align == "left") plot.x + (topW).toDouble() / (2.0).toDouble() else if (align == "right") plot.x + plot.w - (topW).toDouble() / (2.0).toDouble() else plot.x + (plot.w).toDouble() / (2.0).toDouble()
      out.add(FunnelStageGeometry(index = idx, top = top, bottom = top + stageH, topWidth = topW, bottomWidth = bottomW, centerX = cx))
      kf = kf + 1.0
    }
    return out
  }

fun renderFunnel(stages: List<FunnelStage>, plot: PyreonChartRect, options: FunnelOptions? = null): List<PyreonDrawCmd> {
    val out: MutableList<PyreonDrawCmd> = mutableListOf()
    val geo = layoutFunnel(stages, plot, options)
    val rawP = (options?.progress ?: 1.0)
    val progress = if (rawP < 0.0) 0.0 else if (rawP > 1.0) 1.0 else rawP
    val showLabels = (options?.showLabels ?: true)
    val labelColor = (options?.labelColor ?: "#ffffff")
    val fontSize = (options?.fontSize ?: 11.0)
    val align = (options?.align ?: "center")
    for (g in geo) {
      val s = stages[g.index]
      val tw = g.topWidth * progress
      val bw = g.bottomWidth * progress
      val cxTop = if (align == "left") plot.x + (tw).toDouble() / (2.0).toDouble() else g.centerX
      val cxBottom = if (align == "left") plot.x + (bw).toDouble() / (2.0).toDouble() else if (align == "right") plot.x + plot.w - (bw).toDouble() / (2.0).toDouble() else g.centerX
      out.add(PyreonDrawCmd(kind = "polygon", fill = s.color, points = listOf(PyreonChartPt(x = cxTop - (tw).toDouble() / (2.0).toDouble(), y = g.top), PyreonChartPt(x = cxTop + (tw).toDouble() / (2.0).toDouble(), y = g.top), PyreonChartPt(x = cxBottom + (bw).toDouble() / (2.0).toDouble(), y = g.bottom), PyreonChartPt(x = cxBottom - (bw).toDouble() / (2.0).toDouble(), y = g.bottom))))
      if (showLabels && progress >= 1.0) {
        out.add(PyreonDrawCmd(kind = "text", fill = labelColor, text = s.label, at = PyreonChartPt(x = cxTop, y = ((g.top + g.bottom)).toDouble() / (2.0).toDouble()), size = fontSize, align = "middle", baseline = "middle"))
      }
    }
    return out
  }

fun hitFunnel(stages: List<FunnelStage>, plot: PyreonChartRect, px: Double, py: Double, options: FunnelOptions? = null): Int {
    for (g in layoutFunnel(stages, plot, options)) {
      if (py < g.top || py > g.bottom) {
        continue
      }
      val t = if (g.bottom <= g.top) 0.0 else ((py - g.top)).toDouble() / ((g.bottom - g.top)).toDouble()
      val w = g.topWidth + (g.bottomWidth - g.topWidth) * t
      if (px >= g.centerX - (w).toDouble() / (2.0).toDouble() && px <= g.centerX + (w).toDouble() / (2.0).toDouble()) {
        return g.index
      }
    }
    return -1
  }

fun nodeValue(node: TreeNode): Double {
    if (node.value != null) {
      return (node.value ?: 0.0)
    }
    var sum = 0.0
    val stack: MutableList<TreeNode> = mutableListOf()
    var sp = 0
    for (c in (node.children ?: listOf())) {
      if (sp < stack.length) {
        stack[sp] = c
      } else {
        stack.add(c)
      }
      sp = sp + 1
    }
    while (sp > 0) {
      sp = sp - 1
      val cur = stack[sp]
      val own = cur.value
      if (own != null) {
        sum = sum + ((own ?: 0.0))
      } else {
        for (c in (cur.children ?: listOf())) {
          if (sp < stack.length) {
            stack[sp] = c
          } else {
            stack.add(c)
          }
          sp = sp + 1
        }
      }
    }
    return sum
  }

fun worstRatio(row: List<Double>, side: Double, areaScale: Double): Double {
    if (row.length == 0 || side <= 0.0) {
      return -1.0
    }
    var sum = 0.0
    var maxA = 0.0
    var minA = -1.0
    for (v in row) {
      val a = v * areaScale
      sum = sum + a
      if (a > maxA) {
        maxA = a
      }
      if (minA < 0.0 || a < minA) {
        minA = a
      }
    }
    if (sum <= 0.0 || minA <= 0.0) {
      return -1.0
    }
    val s2 = side * side
    val r1 = ((s2 * maxA)).toDouble() / ((sum * sum)).toDouble()
    val r2 = ((sum * sum)).toDouble() / ((s2 * minA)).toDouble()
    return if (r1 > r2) r1 else r2
  }

fun squarify(values: List<Double>, rect: PyreonChartRect): List<PyreonChartRect> {
    val out: MutableList<PyreonChartRect> = mutableListOf()
    var total = 0.0
    for (v in values) {
      total = total + v
    }
    for (i in 0 until values.length) {
      out.add(PyreonChartRect(x = rect.x, y = rect.y, w = 0.0, h = 0.0))
    }
    if (values.length == 0 || total <= 0.0 || rect.w <= 0.0 || rect.h <= 0.0) {
      return out
    }
    val areaScale = ((rect.w * rect.h)).toDouble() / (total).toDouble()
    var x = rect.x
    var y = rect.y
    var w = rect.w
    var h = rect.h
    var i = 0
    while (i < values.length) {
      val row: MutableList<Double> = mutableListOf()
      val rowIdx: MutableList<Int> = mutableListOf()
      var grow = true
      while (grow && i < values.length) {
        val v = values[i]
        val side = if (w >= h) h else w
        if (row.length > 0) {
          val before = worstRatio(row, side, areaScale)
          val candidate: MutableList<Double> = mutableListOf()
          for (r in row) {
            candidate.add(r)
          }
          candidate.add(v)
          val after = worstRatio(candidate, side, areaScale)
          if (before >= 0.0 && after > before) {
            grow = false
          }
        }
        if (grow) {
          row.add(v)
          rowIdx.add(i)
          i = i + 1
        }
      }
      var rowSum = 0.0
      for (v in row) {
        rowSum = rowSum + v * areaScale
      }
      val vertical = w >= h
      val side = if (vertical) h else w
      val thick = if (side <= 0.0) 0.0 else (rowSum).toDouble() / (side).toDouble()
      var offset = 0.0
      for (k in 0 until row.length) {
        val a = row[k] * areaScale
        val len = if (thick <= 0.0) 0.0 else (a).toDouble() / (thick).toDouble()
        val target = rowIdx[k]
        if (vertical) {
          out[target] = PyreonChartRect(x = x, y = y + offset, w = thick, h = len)
        } else {
          out[target] = PyreonChartRect(x = x + offset, y = y, w = len, h = thick)
        }
        offset = offset + len
      }
      if (vertical) {
        x = x + thick
        w = w - thick
      } else {
        y = y + thick
        h = h - thick
      }
    }
    return out
  }

fun orderByValue(children: List<TreeNode>): List<Int> {
    val order: MutableList<Int> = mutableListOf()
    val vals: MutableList<Double> = mutableListOf()
    for (i in 0 until children.length) {
      order.add(i)
      vals.add(nodeValue(children[i]))
    }
    for (i in 1 until order.length) {
      val cur = order[i]
      val cv = vals[cur]
      var j = i - 1
      while (j >= 0) {
        if (vals[order[j]] >= cv) {
          break
        }
        order[j + 1] = order[j]
        j = j - 1
      }
      order[j + 1] = cur
    }
    return order
  }

fun layoutTreemap(nodes: List<TreeNode>, rect: PyreonChartRect, options: TreemapOptions? = null): List<TreemapCell> {
    val palette = (options?.palette ?: DEFAULT_PALETTE)
    val cells: MutableList<TreemapCell> = mutableListOf()
    val padding = (options?.padding ?: 2.0)
    val maxDepth = (options?.maxDepth ?: 64.0)
    val stack: MutableList<TreemapFrame> = mutableListOf()
    stack.add(TreemapFrame(children = nodes, area = rect, depth = 0, path = listOf(), inherited = "", hasInherited = false))
    var sp = 1
    while (sp > 0) {
      sp = sp - 1
      val frame = stack[sp]
      var depthF = 0.0
      for (d in 0 until frame.depth) {
        depthF = depthF + 1.0
      }
      if (depthF >= maxDepth || frame.children.length == 0) {
        continue
      }
      val order = orderByValue(frame.children)
      val values: MutableList<Double> = mutableListOf()
      for (i in order) {
        val v = nodeValue(frame.children[i])
        values.add(if (v < 0.0) 0.0 else v)
      }
      val rects = squarify(values, frame.area)
      val pushed: MutableList<TreemapFrame> = mutableListOf()
      for (k in 0 until order.length) {
        val idx = order[k]
        val node = frame.children[idx]
        val r = rects[k]
        val color = (node.color ?: (if (frame.hasInherited) frame.inherited else paletteAt(palette, idx)))
        val kids = (node.children ?: listOf())
        val cellPath: MutableList<Int> = mutableListOf()
        for (p in frame.path) {
          cellPath.add(p)
        }
        cellPath.add(idx)
        cells.add(TreemapCell(name = node.name, value = values[k], rect = r, depth = frame.depth, path = cellPath, color = color, leaf = kids.length == 0))
        if (kids.length > 0) {
          val innerW = r.w - padding * 2.0
          val innerH = r.h - padding * 2.0
          pushed.add(TreemapFrame(children = kids, area = PyreonChartRect(x = r.x + padding, y = r.y + padding, w = if (innerW < 0.0) 0.0 else innerW, h = if (innerH < 0.0) 0.0 else innerH), depth = frame.depth + 1, path = cellPath, inherited = color, hasInherited = true))
        }
      }
      var pk = pushed.length - 1
      while (pk >= 0) {
        if (sp < stack.length) {
          stack[sp] = pushed[pk]
        } else {
          stack.add(pushed[pk])
        }
        sp = sp + 1
        pk = pk - 1
      }
    }
    return cells
  }

fun hexPair(hex: String, at: Int): Double {
    if (hex.length < at + 2) {
      return 0.0
    }
    return hexDigit(hex[(at).toInt()].code.toDouble()) * 16.0 + hexDigit(hex[(at + 1).toInt()].code.toDouble())
  }

fun tintHex(hex: String, t: Double): String {
    if (hex.length < 7) {
      return hex
    }
    val r = Math.round(hexPair(hex, 1) + (255.0 - hexPair(hex, 1)) * t)
    val g = Math.round(hexPair(hex, 3) + (255.0 - hexPair(hex, 3)) * t)
    val b = Math.round(hexPair(hex, 5) + (255.0 - hexPair(hex, 5)) * t)
    return "rgb(${r}, ${g}, ${b})"
  }

fun approxTextWidth(text: String, fontSize: Double): Double {
    var units = 0.0
    for (i in 0 until text.length) {
      val c = text[(i).toInt()].code.toDouble()
      if (c >= 48.0 && c <= 57.0) {
        units = units + 0.9
      } else {
        if (c == 46.0 || c == 44.0 || c == 32.0) {
          units = units + 0.45
        } else {
          units = units + 1.0
        }
      }
    }
    return units * fontSize * 0.52
  }

fun renderTreemap(cells: List<TreemapCell>, options: TreemapOptions? = null, measure: ((String, Double) -> Double)? = null): List<PyreonDrawCmd> {
    val out: MutableList<PyreonDrawCmd> = mutableListOf()
    val rawP = (options?.progress ?: 1.0)
    val progress = if (rawP < 0.0) 0.0 else if (rawP > 1.0) 1.0 else rawP
    val showLabels = (options?.showLabels ?: true)
    val fontSize = (options?.fontSize ?: 11.0)
    val labelColor = (options?.labelColor ?: "#ffffff")
    val m = (measure ?: ::approxTextWidth)
    for (c in cells) {
      val w = c.rect.w * progress
      val h = c.rect.h * progress
      val x = c.rect.x + ((c.rect.w - w)).toDouble() / (2.0).toDouble()
      val y = c.rect.y + ((c.rect.h - h)).toDouble() / (2.0).toDouble()
      var depthF = 0.0
      for (d in 0 until c.depth) {
        depthF = depthF + 1.0
      }
      val tintT = 0.35 + depthF * 0.15
      out.add(PyreonDrawCmd(kind = "rect", rect = PyreonChartRect(x = x, y = y, w = w, h = h), fill = if (c.leaf) c.color else tintHex(c.color, if (tintT > 0.6) 0.6 else tintT)))
      if (showLabels && progress >= 1.0 && c.leaf) {
        val tw = m(c.name, fontSize)
        if (tw + 8.0 <= c.rect.w && fontSize + 6.0 <= c.rect.h) {
          out.add(PyreonDrawCmd(kind = "text", fill = labelColor, text = c.name, at = PyreonChartPt(x = c.rect.x + 4.0, y = c.rect.y + 4.0), size = fontSize, align = "start", baseline = "top"))
        }
      }
    }
    return out
  }

fun hitTreemapIndex(cells: List<TreemapCell>, px: Double, py: Double): Int {
    var bestIdx = -1
    var bestDepth = -1
    for (i in 0 until cells.length) {
      val c = cells[i]
      val r = c.rect
      if (px < r.x || px > r.x + r.w || py < r.y || py > r.y + r.h) {
        continue
      }
      if (c.depth > bestDepth) {
        bestDepth = c.depth
        bestIdx = i
      }
    }
    return bestIdx
  }

fun hitTreemap(cells: List<TreemapCell>, px: Double, py: Double): TreemapCell? {
    val i = hitTreemapIndex(cells, px, py)
    return if (i < 0) null else cells[i]
  }

fun treeDepth(nodes: List<TreeNode>): Int {
    var deepest = 0
    val stack: MutableList<TreeNode> = mutableListOf()
    val depths: MutableList<Int> = mutableListOf()
    var sp = 0
    for (n in nodes) {
      stack.add(n)
      depths.add(1)
      sp = sp + 1
    }
    while (sp > 0) {
      sp = sp - 1
      val cur = stack[sp]
      val d = depths[sp]
      if (d > deepest) {
        deepest = d
      }
      for (c in (cur.children ?: listOf())) {
        if (sp < stack.length) {
          stack[sp] = c
          depths[sp] = d + 1
        } else {
          stack.add(c)
          depths.add(d + 1)
        }
        sp = sp + 1
      }
    }
    return deepest
  }

fun layoutSunburst(nodes: List<TreeNode>, innerR: Double, outerR: Double, options: SunburstOptions? = null): List<SunburstArc> {
    val palette = (options?.palette ?: DEFAULT_PALETTE)
    val arcs: MutableList<SunburstArc> = mutableListOf()
    val rawLevels = treeDepth(nodes)
    val maxDepth = (options?.maxDepth ?: 64.0)
    var levelsF = 0.0
    for (i in 0 until rawLevels) {
      levelsF = levelsF + 1.0
    }
    if (levelsF > maxDepth) {
      levelsF = maxDepth
    }
    if (levelsF <= 0.0) {
      return arcs
    }
    val ringW = ((outerR - innerR)).toDouble() / (levelsF).toDouble()
    val pad = (options?.padAngle ?: 0.0)
    val sortMode = (options?.sort ?: "desc")
    val startAngle = (options?.startAngle ?: (-kotlin.math.PI).toDouble() / (2.0).toDouble())
    val stack: MutableList<SunburstFrame> = mutableListOf()
    stack.add(SunburstFrame(children = nodes, a0 = startAngle, a1 = startAngle + SUNBURST_TAU, depth = 0, path = listOf(), inherited = "", hasInherited = false))
    var sp = 1
    while (sp > 0) {
      sp = sp - 1
      val frame = stack[sp]
      var depthF = 0.0
      for (d in 0 until frame.depth) {
        depthF = depthF + 1.0
      }
      if (depthF >= levelsF || frame.children.length == 0) {
        continue
      }
      val order: MutableList<Int> = mutableListOf()
      if (sortMode == "desc") {
        for (i in orderByValue(frame.children)) {
          order.add(i)
        }
      } else {
        for (i in 0 until frame.children.length) {
          order.add(i)
        }
      }
      var total = 0.0
      var count = 0.0
      for (i in order) {
        val v = nodeValue(frame.children[i])
        total = total + (if (v < 0.0) 0.0 else v)
        count = count + 1.0
      }
      val usable = frame.a1 - frame.a0 - pad * (count - 1.0)
      var cursor = frame.a0
      val pushed: MutableList<SunburstFrame> = mutableListOf()
      for (idx in order) {
        val node = frame.children[idx]
        val raw = nodeValue(node)
        val v = if (raw < 0.0) 0.0 else raw
        val span = if (total <= 0.0 || usable <= 0.0) 0.0 else usable * ((v).toDouble() / (total).toDouble())
        val color = (node.color ?: (if (frame.hasInherited) frame.inherited else paletteAt(palette, idx)))
        val kids = (node.children ?: listOf())
        val cellPath: MutableList<Int> = mutableListOf()
        for (p in frame.path) {
          cellPath.add(p)
        }
        cellPath.add(idx)
        val r0 = innerR + ringW * depthF
        arcs.add(SunburstArc(name = node.name, value = v, depth = frame.depth, path = cellPath, start = cursor, end = cursor + span, innerR = r0, outerR = r0 + ringW, color = color, leaf = kids.length == 0))
        if (kids.length > 0) {
          pushed.add(SunburstFrame(children = kids, a0 = cursor, a1 = cursor + span, depth = frame.depth + 1, path = cellPath, inherited = color, hasInherited = true))
        }
        cursor = cursor + span + pad
      }
      var pk = pushed.length - 1
      while (pk >= 0) {
        if (sp < stack.length) {
          stack[sp] = pushed[pk]
        } else {
          stack.add(pushed[pk])
        }
        sp = sp + 1
        pk = pk - 1
      }
    }
    return arcs
  }

fun renderSunburst(arcs: List<SunburstArc>, center: PyreonChartPt, options: SunburstOptions? = null, measure: ((String, Double) -> Double)? = null): List<PyreonDrawCmd> {
    val out: MutableList<PyreonDrawCmd> = mutableListOf()
    val rawP = (options?.progress ?: 1.0)
    val progress = if (rawP < 0.0) 0.0 else if (rawP > 1.0) 1.0 else rawP
    val startAngle = (options?.startAngle ?: (-kotlin.math.PI).toDouble() / (2.0).toDouble())
    val limit = startAngle + SUNBURST_TAU * progress
    val showLabels = (options?.showLabels ?: true)
    val fontSize = (options?.fontSize ?: 11.0)
    val labelColor = (options?.labelColor ?: "#ffffff")
    val m = (measure ?: ::approxTextWidth)
    for (a in arcs) {
      if (a.start >= limit || a.end <= a.start) {
        continue
      }
      val end = if (a.end < limit) a.end else limit
      var depthF = 0.0
      for (d in 0 until a.depth) {
        depthF = depthF + 1.0
      }
      val tintT = 0.2 + depthF * 0.15
      val fill = if (a.leaf) a.color else tintHex(a.color, if (tintT > 0.5) 0.5 else tintT)
      out.add(PyreonDrawCmd(kind = "polygon", fill = fill, points = arcPolygon(center, a.outerR, a.innerR, a.start, end)))
      if (showLabels && progress >= 1.0) {
        val midR = ((a.innerR + a.outerR)).toDouble() / (2.0).toDouble()
        val chord = midR * (a.end - a.start)
        val tw = m(a.name, fontSize)
        if (chord >= tw + 4.0 && a.outerR - a.innerR >= fontSize + 4.0) {
          val mid = ((a.start + a.end)).toDouble() / (2.0).toDouble()
          out.add(PyreonDrawCmd(kind = "text", fill = labelColor, text = a.name, at = PyreonChartPt(x = center.x + Math.cos((mid).toDouble()) * midR, y = center.y + Math.sin((mid).toDouble()) * midR), size = fontSize, align = "middle", baseline = "middle"))
        }
      }
    }
    return out
  }

fun hitSunburstIndex(arcs: List<SunburstArc>, center: PyreonChartPt, px: Double, py: Double): Int {
    val dx = px - center.x
    val dy = py - center.y
    val dist = Math.sqrt((dx * dx + dy * dy).toDouble())
    val ang = Math.atan2((dy).toDouble(), (dx).toDouble())
    var bestIdx = -1
    var bestDepth = -1
    for (i in 0 until arcs.length) {
      val a = arcs[i]
      if (dist < a.innerR || dist > a.outerR) {
        continue
      }
      var t = ang
      while (t < a.start) {
        t = t + SUNBURST_TAU
      }
      while (t >= a.start + SUNBURST_TAU) {
        t = t - SUNBURST_TAU
      }
      if (t > a.end) {
        continue
      }
      if (a.depth > bestDepth) {
        bestDepth = a.depth
        bestIdx = i
      }
    }
    return bestIdx
  }

fun hitSunburst(arcs: List<SunburstArc>, center: PyreonChartPt, px: Double, py: Double): SunburstArc? {
    val i = hitSunburstIndex(arcs, center, px, py)
    return if (i < 0) null else arcs[i]
  }

fun placeTreeNode(orient: String, box: PyreonChartRect, gutter: Double, levelsF: Double, slotsF: Double, depthF: Double, t: Double): Placed {
    val depthFrac = if (levelsF <= 1.0) 0.0 else (depthF).toDouble() / ((levelsF - 1.0)).toDouble()
    val slotFrac = if (slotsF <= 1.0) 0.5 else (t).toDouble() / ((slotsF - 1.0)).toDouble()
    if (orient == "radial") {
      val cx = box.x + (box.w).toDouble() / (2.0).toDouble()
      val cy = box.y + (box.h).toDouble() / (2.0).toDouble()
      val side = if (box.w < box.h) box.w else box.h
      val rawR = (side).toDouble() / (2.0).toDouble() - gutter
      val bigR = if (rawR < 0.0) 0.0 else rawR
      val ang = (-kotlin.math.PI).toDouble() / (2.0).toDouble() + (if (slotsF <= 0.0) 0.0 else ((t).toDouble() / (slotsF).toDouble()) * TREE_TAU)
      val r = bigR * depthFrac
      val dir = if (depthF == 0.0) PyreonChartPt(x = 1.0, y = 0.0) else PyreonChartPt(x = Math.cos((ang).toDouble()), y = Math.sin((ang).toDouble()))
      return Placed(at = PyreonChartPt(x = cx + Math.cos((ang).toDouble()) * r, y = cy + Math.sin((ang).toDouble()) * r), dir = dir)
    }
    val x0 = box.x + (gutter).toDouble() / (2.0).toDouble()
    val y0 = box.y + (gutter).toDouble() / (4.0).toDouble()
    val rawW = box.w - gutter
    val w = if (rawW < 0.0) 0.0 else rawW
    val rawH = box.h - (gutter).toDouble() / (2.0).toDouble()
    val hgt = if (rawH < 0.0) 0.0 else rawH
    if (orient == "LR") {
      return Placed(at = PyreonChartPt(x = x0 + w * depthFrac, y = y0 + hgt * slotFrac), dir = PyreonChartPt(x = 1.0, y = 0.0))
    }
    if (orient == "RL") {
      return Placed(at = PyreonChartPt(x = x0 + w * (1.0 - depthFrac), y = y0 + hgt * slotFrac), dir = PyreonChartPt(x = -1.0, y = 0.0))
    }
    if (orient == "TB") {
      return Placed(at = PyreonChartPt(x = x0 + w * slotFrac, y = y0 + hgt * depthFrac), dir = PyreonChartPt(x = 0.0, y = 1.0))
    }
    return Placed(at = PyreonChartPt(x = x0 + w * slotFrac, y = y0 + hgt * (1.0 - depthFrac)), dir = PyreonChartPt(x = 0.0, y = -1.0))
  }

fun layoutTree(roots: List<TreeNode>, box: PyreonChartRect, options: TreeOptions? = null): TreeLayout {
    val palette = (options?.palette ?: DEFAULT_PALETTE)
    val orient = (options?.orient ?: "LR")
    val maxDepth = (options?.maxDepth ?: 64.0)
    val gutter = (options?.labelGutter ?: 60.0)
    val stack: MutableList<TreeFrame> = mutableListOf()
    var sp = 0
    var ri = roots.length - 1
    while (ri >= 0) {
      val root = roots[ri]
      stack.add(TreeFrame(node = root, depth = 0, path = listOf(ri), color = (root.color ?: paletteAt(palette, ri)), parent = -1))
      sp = sp + 1
      ri = ri - 1
    }
    val frames: MutableList<TreeFrame> = mutableListOf()
    val leafFlags: MutableList<Boolean> = mutableListOf()
    var levelsF = 0.0
    while (sp > 0) {
      sp = sp - 1
      val frame = stack[sp]
      var depthF = 0.0
      for (d in 0 until frame.depth) {
        depthF = depthF + 1.0
      }
      if (depthF + 1.0 > levelsF) {
        levelsF = depthF + 1.0
      }
      val kids: MutableList<TreeNode> = mutableListOf()
      if (depthF + 1.0 < maxDepth) {
        for (k in (frame.node.children ?: listOf())) {
          kids.add(k)
        }
      }
      val index = frames.length
      frames.add(frame)
      leafFlags.add(kids.length == 0)
      var ki = kids.length - 1
      while (ki >= 0) {
        val kid = kids[ki]
        val childPath: MutableList<Int> = mutableListOf()
        for (p in frame.path) {
          childPath.add(p)
        }
        childPath.add(ki)
        val next = TreeFrame(node = kid, depth = frame.depth + 1, path = childPath, color = (kid.color ?: frame.color), parent = index)
        if (sp < stack.length) {
          stack[sp] = next
        } else {
          stack.add(next)
        }
        sp = sp + 1
        ki = ki - 1
      }
    }
    val lo: MutableList<Double> = mutableListOf()
    val hi: MutableList<Double> = mutableListOf()
    var nextSlot = 0.0
    for (i in 0 until frames.length) {
      if (leafFlags[i]) {
        lo.add(nextSlot)
        hi.add(nextSlot)
        nextSlot = nextSlot + 1.0
      } else {
        lo.add(-1.0)
        hi.add(-1.0)
      }
    }
    var bi = frames.length - 1
    while (bi >= 0) {
      val parent = frames[bi].parent
      if (parent >= 0) {
        if (lo[parent] < 0.0 || lo[bi] < lo[parent]) {
          lo[parent] = lo[bi]
        }
        if (hi[parent] < 0.0 || hi[bi] > hi[parent]) {
          hi[parent] = hi[bi]
        }
      }
      bi = bi - 1
    }
    val slotsF = nextSlot
    val nodes: MutableList<TreeLayoutNode> = mutableListOf()
    val links: MutableList<TreeLink> = mutableListOf()
    for (i in 0 until frames.length) {
      val f = frames[i]
      var depthF = 0.0
      for (d in 0 until f.depth) {
        depthF = depthF + 1.0
      }
      val t = ((lo[i] + hi[i])).toDouble() / (2.0).toDouble()
      val p = placeTreeNode(orient, box, gutter, levelsF, slotsF, depthF, t)
      nodes.add(TreeLayoutNode(name = f.node.name, value = f.node.value, at = p.at, depth = f.depth, path = f.path, color = f.color, leaf = leafFlags[i], dir = p.dir))
    }
    for (i in 0 until frames.length) {
      val f = frames[i]
      if (f.parent < 0) {
        continue
      }
      links.add(TreeLink(from = nodes[f.parent].at, to = nodes[i].at, path = f.path, depth = f.depth))
    }
    return TreeLayout(nodes = nodes, links = links)
  }

fun linkPoints(link: TreeLink, orient: String, shape: String): List<PyreonChartPt> {
    val a = link.from
    val b = link.to
    if (orient == "radial") {
      return listOf(a, b)
    }
    val horizontal = orient == "LR" || orient == "RL"
    if (shape == "elbow") {
      if (horizontal) {
        return listOf(a, PyreonChartPt(x = ((a.x + b.x)).toDouble() / (2.0).toDouble(), y = a.y), PyreonChartPt(x = ((a.x + b.x)).toDouble() / (2.0).toDouble(), y = b.y), b)
      }
      return listOf(a, PyreonChartPt(x = a.x, y = ((a.y + b.y)).toDouble() / (2.0).toDouble()), PyreonChartPt(x = b.x, y = ((a.y + b.y)).toDouble() / (2.0).toDouble()), b)
    }
    val pts: MutableList<PyreonChartPt> = mutableListOf()
    var iF = 0.0
    for (i in 0..12) {
      val t = (iF).toDouble() / (12.0).toDouble()
      val e = t * t * (3.0 - 2.0 * t)
      if (horizontal) {
        pts.add(PyreonChartPt(x = a.x + (b.x - a.x) * t, y = a.y + (b.y - a.y) * e))
      } else {
        pts.add(PyreonChartPt(x = a.x + (b.x - a.x) * e, y = a.y + (b.y - a.y) * t))
      }
      iF = iF + 1.0
    }
    return pts
  }

fun renderTree(layout: TreeLayout, options: TreeOptions? = null): List<PyreonDrawCmd> {
    val out: MutableList<PyreonDrawCmd> = mutableListOf()
    val orient = (options?.orient ?: "LR")
    val shape = (options?.edgeShape ?: "curve")
    val rawP = (options?.progress ?: 1.0)
    val progress = if (rawP < 0.0) 0.0 else if (rawP > 1.0) 1.0 else rawP
    var levelsF = 0.0
    for (n in layout.nodes) {
      var depthF = 0.0
      for (d in 0 until n.depth) {
        depthF = depthF + 1.0
      }
      if (depthF + 1.0 > levelsF) {
        levelsF = depthF + 1.0
      }
    }
    var shownF = 0.0
    if (progress >= 1.0) {
      shownF = levelsF
    } else {
      while (shownF + 1.0 <= levelsF * progress) {
        shownF = shownF + 1.0
      }
    }
    val size = (options?.symbolSize ?: 8.0)
    val linkColor = (options?.linkColor ?: "#94a3b8")
    val showLabels = (options?.showLabels ?: true)
    val fontSize = (options?.fontSize ?: 11.0)
    val labelColor = (options?.labelColor ?: "#334155")
    for (l in layout.links) {
      var depthF = 0.0
      for (d in 0 until l.depth) {
        depthF = depthF + 1.0
      }
      if (depthF >= shownF) {
        continue
      }
      out.add(PyreonDrawCmd(kind = "polyline", stroke = linkColor, width = 1.0, points = linkPoints(l, orient, shape)))
    }
    for (n in layout.nodes) {
      var depthF = 0.0
      for (d in 0 until n.depth) {
        depthF = depthF + 1.0
      }
      if (depthF >= shownF) {
        continue
      }
      out.add(PyreonDrawCmd(kind = "circle", fill = n.color, center = n.at, radius = (size).toDouble() / (2.0).toDouble()))
      if (!showLabels || progress < 1.0) {
        continue
      }
      val sx = if (n.leaf) n.dir.x else -n.dir.x
      val sy = if (n.leaf) n.dir.y else -n.dir.y
      val off = (size).toDouble() / (2.0).toDouble() + 4.0
      out.add(PyreonDrawCmd(kind = "text", fill = labelColor, text = n.name, at = PyreonChartPt(x = n.at.x + sx * off, y = n.at.y + sy * off), size = fontSize, align = if (sx > 0.3) "start" else if (sx < -0.3) "end" else "middle", baseline = if (sy > 0.3) "top" else if (sy < -0.3) "bottom" else "middle"))
    }
    return out
  }

fun hitTreeIndex(layout: TreeLayout, px: Double, py: Double, symbolSize: Double? = null): Int {
    val r = (((symbolSize ?: 8.0))).toDouble() / (2.0).toDouble() + 4.0
    var bestIdx = -1
    var bestD = r * r
    for (i in 0 until layout.nodes.length) {
      val n = layout.nodes[i]
      val dx = px - n.at.x
      val dy = py - n.at.y
      val d = dx * dx + dy * dy
      if (d <= bestD) {
        bestIdx = i
        bestD = d
      }
    }
    return bestIdx
  }

fun hitTree(layout: TreeLayout, px: Double, py: Double, symbolSize: Double? = null): TreeLayoutNode? {
    val i = hitTreeIndex(layout, px, py, symbolSize)
    return if (i < 0) null else layout.nodes[i]
  }

fun riverValue(s: RiverSeries, i: Int): Double {
    if (i >= s.values.length) {
      return 0.0
    }
    val v = s.values[i]
    if (!isFiniteNumber(v)) {
      return 0.0
    }
    return if (v < 0.0) 0.0 else v
  }

fun layoutRiver(series: List<RiverSeries>, box: PyreonChartRect, options: RiverOptions? = null): RiverLayout {
    val palette = (options?.palette ?: DEFAULT_PALETTE)
    val fontSize = (options?.fontSize ?: 11.0)
    val showAxis = options?.showAxis != false
    val rawH = box.h - (if (showAxis) fontSize * 1.8 else 0.0)
    val plot = PyreonChartRect(x = box.x, y = box.y, w = box.w, h = if (rawH < 0.0) 0.0 else rawH)
    var n = 0
    for (s in series) {
      if (s.values.length > n) {
        n = s.values.length
      }
    }
    val cats = (options?.categories ?: listOf())
    if (cats.length > n) {
      n = cats.length
    }
    var nF = 0.0
    for (i in 0 until n) {
      nF = nF + 1.0
    }
    val xs: MutableList<Double> = mutableListOf()
    var iF = 0.0
    for (i in 0 until n) {
      xs.add(if (nF <= 1.0) plot.x + (plot.w).toDouble() / (2.0).toDouble() else plot.x + ((plot.w * iF)).toDouble() / ((nF - 1.0)).toDouble())
      iF = iF + 1.0
    }
    val totals: MutableList<Double> = mutableListOf()
    for (i in 0 until n) {
      var t = 0.0
      for (s in series) {
        t = t + riverValue(s, i)
      }
      totals.add(t)
    }
    val zeroBase = options?.baseline == "zero"
    val base: MutableList<Double> = mutableListOf()
    for (t in totals) {
      base.add(if (zeroBase) 0.0 else (-t).toDouble() / (2.0).toDouble())
    }
    var lo = 0.0
    var hi = 1.0
    var seen = false
    for (i in 0 until n) {
      val b = base[i]
      var top = b + totals[i]
      if (!seen || b < lo) {
        lo = b
      }
      if (!seen || top > hi) {
        hi = top
      }
      seen = true
    }
    if (hi <= lo) {
      hi = lo + 1.0
    }
    val layers: MutableList<RiverLayer> = mutableListOf()
    val cursor: MutableList<Double> = mutableListOf()
    for (b in base) {
      cursor.add(b)
    }
    for (si in 0 until series.length) {
      val s = series[si]
      val top: MutableList<PyreonChartPt> = mutableListOf()
      val bottom: MutableList<PyreonChartPt> = mutableListOf()
      var widest = 0.0
      var widestAt = 0
      for (i in 0 until n) {
        val v = riverValue(s, i)
        val b = cursor[i]
        bottom.add(PyreonChartPt(x = xs[i], y = plot.y + plot.h - (((b - lo)).toDouble() / ((hi - lo)).toDouble()) * plot.h))
        top.add(PyreonChartPt(x = xs[i], y = plot.y + plot.h - (((b + v - lo)).toDouble() / ((hi - lo)).toDouble()) * plot.h))
        if (v > widest) {
          widest = v
          widestAt = i
        }
        cursor[i] = b + v
      }
      val hasPts = n > 0
      val midX = if (hasPts) xs[widestAt] else plot.x
      val midY = if (hasPts) (top[widestAt].y).toDouble() / (2.0).toDouble() + (bottom[widestAt].y).toDouble() / (2.0).toDouble() else plot.y
      val thickness = if (hasPts && widest > 0.0) bottom[widestAt].y - top[widestAt].y else 0.0
      layers.add(RiverLayer(series = si, name = s.name, color = (s.color ?: paletteAt(palette, si)), top = top, bottom = bottom, labelAt = PyreonChartPt(x = midX, y = midY), thickness = thickness))
    }
    val ticks: MutableList<RiverTick> = mutableListOf()
    if (showAxis && n > 0) {
      var every = 1
      while (every * 8 < n) {
        every = every + 1
      }
      var ti = 0
      while (ti < n) {
        ticks.add(RiverTick(x = xs[ti], label = if (ti < cats.length) cats[ti] else "${ti + 1}"))
        ti = ti + every
      }
    }
    return RiverLayout(layers = layers, xs = xs, ticks = ticks, plot = plot)
  }

fun smoothPoints(pts: List<PyreonChartPt>): List<PyreonChartPt> {
    val out: MutableList<PyreonChartPt> = mutableListOf()
    if (pts.length < 3) {
      for (p in pts) {
        out.add(p)
      }
      return out
    }
    out.add(pts[0])
    for (i in 0 until pts.length - 1) {
      val p1 = pts[i]
      val p2 = pts[i + 1]
      val p0 = if (i > 0) pts[i - 1] else p1
      val p3 = if (i + 2 < pts.length) pts[i + 2] else p2
      var kf = 1.0
      for (k in 1..8) {
        val t = (kf).toDouble() / (8.0).toDouble()
        val t2 = t * t
        val t3 = t2 * t
        val x = 0.5 * (2.0 * p1.x + (-p0.x + p2.x) * t + (2.0 * p0.x - 5.0 * p1.x + 4.0 * p2.x - p3.x) * t2 + (-p0.x + 3.0 * p1.x - 3.0 * p2.x + p3.x) * t3)
        val y = 0.5 * (2.0 * p1.y + (-p0.y + p2.y) * t + (2.0 * p0.y - 5.0 * p1.y + 4.0 * p2.y - p3.y) * t2 + (-p0.y + 3.0 * p1.y - 3.0 * p2.y + p3.y) * t3)
        out.add(PyreonChartPt(x = x, y = y))
        kf = kf + 1.0
      }
    }
    return out
  }

fun layerPolygon(layer: RiverLayer, curve: String, progress: Double): List<PyreonChartPt> {
    var lenF = 0.0
    for (i in 0 until layer.top.length) {
      lenF = lenF + 1.0
    }
    var countF = 0.0
    if (progress >= 1.0) {
      countF = lenF
    } else {
      while (countF + 1.0 <= lenF * progress) {
        countF = countF + 1.0
      }
      if (countF < 2.0) {
        countF = 2.0
      }
    }
    val topCut: MutableList<PyreonChartPt> = mutableListOf()
    val bottomCut: MutableList<PyreonChartPt> = mutableListOf()
    var iF = 0.0
    for (i in 0 until layer.top.length) {
      if (iF >= countF) {
        break
      }
      topCut.add(layer.top[i])
      if (i < layer.bottom.length) {
        bottomCut.add(layer.bottom[i])
      }
      iF = iF + 1.0
    }
    val top = if (curve == "smooth") smoothPoints(topCut) else topCut
    val bottom = if (curve == "smooth") smoothPoints(bottomCut) else bottomCut
    val out: MutableList<PyreonChartPt> = mutableListOf()
    for (p in top) {
      out.add(p)
    }
    var bi = bottom.length - 1
    while (bi >= 0) {
      out.add(bottom[bi])
      bi = bi - 1
    }
    return out
  }

fun renderRiver(layout: RiverLayout, options: RiverOptions? = null, measure: ((String, Double) -> Double)? = null): List<PyreonDrawCmd> {
    val out: MutableList<PyreonDrawCmd> = mutableListOf()
    val curve = (options?.curve ?: "smooth")
    val rawP = (options?.progress ?: 1.0)
    val progress = if (rawP < 0.0) 0.0 else if (rawP > 1.0) 1.0 else rawP
    val fontSize = (options?.fontSize ?: 11.0)
    val labelColor = (options?.labelColor ?: "#ffffff")
    val axisColor = (options?.axisColor ?: "#94a3b8")
    val tickColor = (options?.tickColor ?: "#64748b")
    val m = (measure ?: ::approxTextWidth)
    if (progress <= 0.0 || layout.xs.length < 2) {
      return out
    }
    for (l in layout.layers) {
      if (l.thickness <= 0.0) {
        continue
      }
      out.add(PyreonDrawCmd(kind = "polygon", fill = l.color, points = layerPolygon(l, curve, progress)))
    }
    if (progress < 1.0) {
      return out
    }
    if (options?.showAxis != false && layout.ticks.length > 0) {
      val y = layout.plot.y + layout.plot.h
      out.add(PyreonDrawCmd(kind = "line", from = PyreonChartPt(x = layout.plot.x, y = y), to = PyreonChartPt(x = layout.plot.x + layout.plot.w, y = y), stroke = axisColor, width = 1.0))
      for (t in layout.ticks) {
        out.add(PyreonDrawCmd(kind = "text", fill = tickColor, text = t.label, at = PyreonChartPt(x = t.x, y = y + 4.0), size = fontSize, align = "middle", baseline = "top"))
      }
    }
    if (options?.showLabels != false) {
      for (l in layout.layers) {
        if (l.thickness < fontSize + 2.0) {
          continue
        }
        if (m(l.name, fontSize) > (layout.plot.w).toDouble() / (3.0).toDouble()) {
          continue
        }
        out.add(PyreonDrawCmd(kind = "text", fill = labelColor, text = l.name, at = l.labelAt, size = fontSize, align = "middle", baseline = "middle"))
      }
    }
    return out
  }

fun riverPointInPolygon(pts: List<PyreonChartPt>, px: Double, py: Double): Boolean {
    var inside = false
    var j = pts.length - 1
    for (i in 0 until pts.length) {
      val a = pts[i]
      val b = pts[j]
      val aAbove = a.y > py
      val bAbove = b.y > py
      if (aAbove != bAbove && px < (((b.x - a.x) * (py - a.y))).toDouble() / ((b.y - a.y)).toDouble() + a.x) {
        inside = !inside
      }
      j = i
    }
    return inside
  }

fun hitRiverIndex(layout: RiverLayout, px: Double, py: Double, curve: String? = null): Int {
    val shape = (curve ?: "smooth")
    var bestIdx = -1
    for (i in layout.layers.length - 1 downTo 0) {
      if (bestIdx >= 0) {
        continue
      }
      val l = layout.layers[i]
      if (l.thickness > 0.0 && riverPointInPolygon(layerPolygon(l, shape, 1.0), px, py)) {
        bestIdx = i
      }
    }
    return bestIdx
  }

fun hitRiver(layout: RiverLayout, px: Double, py: Double, curve: String? = null): RiverLayer? {
    val i = hitRiverIndex(layout, px, py, curve)
    return if (i < 0) null else layout.layers[i]
  }

fun indexOfName(names: List<String>, name: String): Int {
    for (i in 0 until names.length) {
      if (names[i] == name) {
        return i
      }
    }
    return -1
  }

fun layoutChord(nodes: List<ChordNode>, links: List<ChordLink>, box: PyreonChartRect, options: ChordOptions? = null, measure: ((String, Double) -> Double)? = null): ChordLayout {
    val palette = (options?.palette ?: DEFAULT_PALETTE)
    val padAngle = (options?.padAngle ?: 0.04)
    val ringRatio = (options?.ringRatio ?: 0.08)
    val fontSize = (options?.fontSize ?: 11.0)
    val m = (measure ?: ::approxTextWidth)
    val names: MutableList<String> = mutableListOf()
    for (n in nodes) {
      names.add(n.name)
    }
    val totals: MutableList<Double> = mutableListOf()
    for (i in 0 until names.length) {
      totals.add(0.0)
    }
    val valid: MutableList<ChordLink> = mutableListOf()
    for (l in links) {
      val s = indexOfName(names, l.source)
      val t = indexOfName(names, l.target)
      if (s < 0 || t < 0) {
        continue
      }
      if (!isFiniteNumber(l.value) || l.value <= 0.0) {
        continue
      }
      valid.add(l)
      totals[s] = totals[s] + l.value
      totals[t] = totals[t] + l.value
    }
    var grand = 0.0
    for (t in totals) {
      grand = grand + t
    }
    var widest = 0.0
    if (options?.showLabels != false) {
      for (n in names) {
        val w = m(n, fontSize)
        if (w > widest) {
          widest = w
        }
      }
    }
    val outer = fitCircle(box)
    val radius = Math.max(8.0, outer.radius - widest - 8.0)
    val circle = Circle(center = outer.center, radius = radius)
    val thickness = Math.max(3.0, radius * ringRatio)
    val arcs: MutableList<ChordArc> = mutableListOf()
    val ribbons: MutableList<ChordRibbon> = mutableListOf()
    if (grand <= 0.0 || names.length == 0) {
      return ChordLayout(arcs = arcs, ribbons = ribbons, circle = circle, thickness = thickness, box = box)
    }
    val gaps = padAngle * names.length
    val usable = Math.max(0.0, CHORD_TAU - gaps)
    var angle = (-kotlin.math.PI).toDouble() / (2.0).toDouble()
    val starts: MutableList<Double> = mutableListOf()
    val cursors: MutableList<Double> = mutableListOf()
    for (i in 0 until names.length) {
      val span = ((totals[i]).toDouble() / (grand).toDouble()) * usable
      val start = angle
      val end = angle + span
      val mid = ((start + end)).toDouble() / (2.0).toDouble()
      val labelR = radius + 6.0
      val at = pointOnCircle(circle.center, labelR, mid)
      val cosMid = Math.cos((mid).toDouble())
      arcs.add(ChordArc(index = i, name = names[i], color = (nodes[i].color ?: paletteAt(palette, i)), start = start, end = end, total = totals[i], labelAt = at, labelAlign = if (cosMid >= 0.0) "start" else "end"))
      starts.add(start)
      cursors.add(start)
      angle = end + padAngle
    }
    for (k in 0 until valid.length) {
      val l = valid[k]
      val s = indexOfName(names, l.source)
      val t = indexOfName(names, l.target)
      val span = ((l.value).toDouble() / (grand).toDouble()) * usable
      val sStart = cursors[s]
      val sEnd = sStart + span
      cursors[s] = sEnd
      val tStart = cursors[t]
      val tEnd = tStart + span
      cursors[t] = tEnd
      ribbons.add(ChordRibbon(link = k, source = s, target = t, value = l.value, color = arcs[s].color, sourceStart = sStart, sourceEnd = sEnd, targetStart = tStart, targetEnd = tEnd))
    }
    return ChordLayout(arcs = arcs, ribbons = ribbons, circle = circle, thickness = thickness, box = box)
  }

fun ribbonPolygon(layout: ChordLayout, r: ChordRibbon, progress: Double): List<PyreonChartPt> {
    val c = layout.circle.center
    val inner = Math.max(0.0, layout.circle.radius - layout.thickness)
    val p = if (progress < 0.0) 0.0 else if (progress > 1.0) 1.0 else progress
    val pts: MutableList<PyreonChartPt> = mutableListOf()
    val sSweep = r.sourceEnd - r.sourceStart
    val sSteps = Math.max((2).toDouble(), Math.ceil(((Math.abs(sSweep)).toDouble() / (CHORD_TAU).toDouble()) * 64.0))
    for (i in 0..Math.floor(sSteps).toInt()) {
      pts.add(pointOnCircle(c, inner, r.sourceStart + ((sSweep * i)).toDouble() / (sSteps).toDouble()))
    }
    val a = pointOnCircle(c, inner, r.sourceEnd)
    val b = pointOnCircle(c, inner, r.targetStart)
    for (q in quadPoints(a, c, b, p)) {
      pts.add(q)
    }
    val tSweep = r.targetEnd - r.targetStart
    val tSteps = Math.max((2).toDouble(), Math.ceil(((Math.abs(tSweep)).toDouble() / (CHORD_TAU).toDouble()) * 64.0))
    for (i in 0..Math.floor(tSteps).toInt()) {
      pts.add(pointOnCircle(c, inner, r.targetStart + ((tSweep * i)).toDouble() / (tSteps).toDouble()))
    }
    val a2 = pointOnCircle(c, inner, r.targetEnd)
    val b2 = pointOnCircle(c, inner, r.sourceStart)
    for (q in quadPoints(a2, c, b2, p)) {
      pts.add(q)
    }
    return pts
  }

fun quadPoints(from: PyreonChartPt, control: PyreonChartPt, to: PyreonChartPt, progress: Double): List<PyreonChartPt> {
    val out: MutableList<PyreonChartPt> = mutableListOf()
    val steps = 24
    val mx = ((from.x + to.x)).toDouble() / (2.0).toDouble()
    val my = ((from.y + to.y)).toDouble() / (2.0).toDouble()
    val cx = mx + (control.x - mx) * progress
    val cy = my + (control.y - my) * progress
    for (i in 1..steps) {
      val t = (i).toDouble() / (steps).toDouble()
      val u = 1.0 - t
      val x = u * u * from.x + 2.0 * u * t * cx + t * t * to.x
      val y = u * u * from.y + 2.0 * u * t * cy + t * t * to.y
      out.add(PyreonChartPt(x = x, y = y))
    }
    return out
  }

fun renderChord(layout: ChordLayout, options: ChordOptions? = null, measure: ((String, Double) -> Double)? = null): List<PyreonDrawCmd> {
    val out: MutableList<PyreonDrawCmd> = mutableListOf()
    val rawP = (options?.progress ?: 1.0)
    val progress = if (rawP < 0.0) 0.0 else if (rawP > 1.0) 1.0 else rawP
    val opacity = (options?.linkOpacity ?: 0.62)
    val fontSize = (options?.fontSize ?: 11.0)
    val labelColor = (options?.labelColor ?: "#5a6b7a")
    val m = (measure ?: ::approxTextWidth)
    if (progress <= 0.0 || layout.arcs.length == 0) {
      return out
    }
    for (r in layout.ribbons) {
      out.add(PyreonDrawCmd(kind = "polygon", fill = withAlpha(r.color, opacity), points = ribbonPolygon(layout, r, progress)))
    }
    val c = layout.circle.center
    val inner = Math.max(0.0, layout.circle.radius - layout.thickness)
    for (a in layout.arcs) {
      out.add(PyreonDrawCmd(kind = "polygon", fill = a.color, points = arcPolygon(c, layout.circle.radius, inner, a.start, a.end)))
    }
    if (options?.showLabels != false) {
      for (a in layout.arcs) {
        if (m(a.name, fontSize) > (layout.box.w).toDouble() / (2.0).toDouble()) {
          continue
        }
        out.add(PyreonDrawCmd(kind = "text", fill = labelColor, text = a.name, at = a.labelAt, size = fontSize, align = a.labelAlign, baseline = "middle"))
      }
    }
    return out
  }

fun hitChordIndex(layout: ChordLayout, px: Double, py: Double): Int {
    val dx = px - layout.circle.center.x
    val dy = py - layout.circle.center.y
    val dist = Math.sqrt((dx * dx + dy * dy).toDouble())
    val inner = Math.max(0.0, layout.circle.radius - layout.thickness)
    if (dist < inner || dist > layout.circle.radius) {
      return -1
    }
    val raw = Math.atan2((dy).toDouble(), (dx).toDouble())
    val wrapped = raw + CHORD_TAU
    for (a in layout.arcs) {
      if (raw >= a.start && raw <= a.end) {
        return a.index
      }
      if (wrapped >= a.start && wrapped <= a.end) {
        return a.index
      }
    }
    return -1
  }

fun polarFrac(v: Double, lo: Double, hi: Double): Double {
    val span = hi - lo
    val t = if (span <= 0.0) 0.0 else ((v - lo)).toDouble() / (span).toDouble()
    return if (t < 0.0) 0.0 else if (t > 1.0) 1.0 else t
  }

fun polarTicks(lo: Double, hi: Double): List<Double> {
    val out: MutableList<Double> = mutableListOf()
    if (hi <= lo) {
      out.add(lo)
      return out
    }
    val raw = ((hi - lo)).toDouble() / (3.0).toDouble()
    var mag = 1.0
    while (mag * 10.0 <= raw) {
      mag = mag * 10.0
    }
    while (mag > raw) {
      mag = (mag).toDouble() / (10.0).toDouble()
    }
    val norm = (raw).toDouble() / (mag).toDouble()
    val step = (if (norm >= 5.0) 5.0 else if (norm >= 2.0) 2.0 else 1.0) * mag
    var v = 0.0
    while (v < lo) {
      v = v + step
    }
    while (v - step >= lo) {
      v = v - step
    }
    var guard = 0
    while (v <= hi + 1e-9 && guard < 1000) {
      out.add((Math.round(v * 1000000.0)).toDouble() / (1000000.0).toDouble())
      v = v + step
      guard = guard + 1
    }
    return out
  }

fun polarColumnKey(s: PolarSeries, i: Int): String = (s.stack ?: "#${i}")

fun layoutPolar(axes: PolarAxes, series: List<PolarSeries>, box: PyreonChartRect, options: PolarOptions? = null): PolarLayout {
    val palette = (options?.palette ?: DEFAULT_PALETTE)
    val categoryOn = (axes.categoryOn ?: "angle")
    val n = axes.categories.length
    var nF = 0.0
    for (i in 0 until n) {
      nF = nF + 1.0
    }
    val fontSize = (options?.fontSize ?: 11.0)
    val gutter = if (options?.showLabels == false) 4.0 else fontSize * 3.0
    val center = PyreonChartPt(x = box.x + (box.w).toDouble() / (2.0).toDouble(), y = box.y + (box.h).toDouble() / (2.0).toDouble())
    val side = if (box.w < box.h) box.w else box.h
    val rawOuter = (side).toDouble() / (2.0).toDouble() - gutter
    val outerR = if (rawOuter < 0.0) 0.0 else rawOuter
    val rawRatio = (options?.innerRatio ?: 0.0)
    val ratio = if (rawRatio < 0.0) 0.0 else if (rawRatio > 0.95) 0.95 else rawRatio
    val innerR = outerR * ratio
    val start = (axes.startAngle ?: (-kotlin.math.PI).toDouble() / (2.0).toDouble())
    val dir = if (axes.clockwise == false) -1.0 else 1.0
    val barGap = (options?.barGap ?: 0.2)
    val columns: MutableList<String> = mutableListOf()
    for (si in 0 until series.length) {
      val s = series[si]
      if (s.kind != "bar") {
        continue
      }
      val key = polarColumnKey(s, si)
      var known = false
      for (c in columns) {
        if (c == key) {
          known = true
        }
      }
      if (!known) {
        columns.add(key)
      }
    }
    var columnsF = 0.0
    for (i in 0 until columns.length) {
      columnsF = columnsF + 1.0
    }
    val stackTop: MutableList<Double> = mutableListOf()
    for (c in 0 until columns.length) {
      for (i in 0 until n) {
        stackTop.add(0.0)
      }
    }
    var lo = 0.0
    var hi = 0.0
    for (si in 0 until series.length) {
      val s = series[si]
      var col = -1
      if (s.kind == "bar" && s.stack != null && categoryOn == "angle") {
        val key = polarColumnKey(s, si)
        for (c in 0 until columns.length) {
          if (columns[c] == key) {
            col = c
          }
        }
      }
      for (i in 0 until n) {
        if (i >= s.values.length) {
          continue
        }
        val v = s.values[i]
        if (!isFiniteNumber(v)) {
          continue
        }
        if (col >= 0) {
          val at = col * n + i
          val top = stackTop[at] + v
          stackTop[at] = top
          if (top > hi) {
            hi = top
          }
          if (top < lo) {
            lo = top
          }
        } else {
          if (v > hi) {
            hi = v
          }
          if (v < lo) {
            lo = v
          }
        }
      }
    }
    val domainLo = (axes.valueDomain?.min ?: lo)
    val domainHi = (axes.valueDomain?.max ?: hi)
    val sectors: MutableList<PolarSector> = mutableListOf()
    val lines: MutableList<PolarLine> = mutableListOf()
    val categoryLabels: MutableList<PolarCategoryLabel> = mutableListOf()
    val running: MutableList<Double> = mutableListOf()
    for (c in 0 until columns.length) {
      for (i in 0 until n) {
        running.add(0.0)
      }
    }
    if (categoryOn == "angle") {
      val slot = if (nF <= 0.0) 0.0 else (POLAR_TAU).toDouble() / (nF).toDouble()
      for (si in 0 until series.length) {
        val s = series[si]
        if (s.kind != "bar") {
          continue
        }
        val key = polarColumnKey(s, si)
        var col = 0
        var colF = 0.0
        for (c in 0 until columns.length) {
          if (columns[c] == key) {
            col = c
            colF = 0.0
            for (k in 0 until c) {
              colF = colF + 1.0
            }
          }
        }
        val color = (s.color ?: paletteAt(palette, si))
        var iF = 0.0
        for (i in 0 until n) {
          if (i < s.values.length) {
            val v = s.values[i]
            if (isFiniteNumber(v)) {
              val inner = ((slot * barGap)).toDouble() / (2.0).toDouble()
              val width = ((slot - slot * barGap)).toDouble() / (columnsF).toDouble()
              val a0 = start + dir * slot * iF + dir * (inner + width * colF)
              val a1 = a0 + dir * width
              val at = col * n + i
              val base = running[at]
              running[at] = base + v
              sectors.add(PolarSector(series = si, index = i, start = if (a0 < a1) a0 else a1, end = if (a0 < a1) a1 else a0, innerR = innerR + (outerR - innerR) * polarFrac(base, domainLo, domainHi), outerR = innerR + (outerR - innerR) * polarFrac(base + v, domainLo, domainHi), color = color, value = v))
            }
          }
          iF = iF + 1.0
        }
      }
      for (si in 0 until series.length) {
        val s = series[si]
        if (s.kind != "line" && s.kind != "scatter") {
          continue
        }
        val color = (s.color ?: paletteAt(palette, si))
        val points: MutableList<PolarPoint> = mutableListOf()
        var iF = 0.0
        for (i in 0 until n) {
          if (i < s.values.length) {
            val v = s.values[i]
            if (isFiniteNumber(v)) {
              val r = innerR + (outerR - innerR) * polarFrac(v, domainLo, domainHi)
              points.add(PolarPoint(series = si, index = i, at = pointOnCircle(center, r, start + dir * slot * (iF + 0.5)), color = color, value = v))
            }
          }
          iF = iF + 1.0
        }
        lines.add(PolarLine(series = si, color = color, points = points, scatter = s.kind == "scatter", radius = (s.radius ?: (if (s.kind == "scatter") 4.0 else 2.5))))
      }
      var iF = 0.0
      for (i in 0 until n) {
        val a = start + dir * slot * (iF + 0.5)
        val at = pointOnCircle(center, outerR + fontSize * 0.6, a)
        val c = Math.cos((a).toDouble())
        categoryLabels.add(PolarCategoryLabel(text = axes.categories[i], at = at, align = if (c > 0.3) "start" else if (c < -0.3) "end" else "middle"))
        iF = iF + 1.0
      }
    } else {
      val ring = if (nF <= 0.0) 0.0 else ((outerR - innerR)).toDouble() / (nF).toDouble()
      for (si in 0 until series.length) {
        val s = series[si]
        if (s.kind != "bar") {
          continue
        }
        val key = polarColumnKey(s, si)
        var colF = 0.0
        for (c in 0 until columns.length) {
          if (columns[c] == key) {
            colF = 0.0
            for (k in 0 until c) {
              colF = colF + 1.0
            }
          }
        }
        val color = (s.color ?: paletteAt(palette, si))
        var iF = 0.0
        for (i in 0 until n) {
          if (i < s.values.length) {
            val v = s.values[i]
            if (isFiniteNumber(v)) {
              val r0 = innerR + ring * iF + ((ring * barGap)).toDouble() / (2.0).toDouble()
              val width = ((ring - ring * barGap)).toDouble() / (columnsF).toDouble()
              val sweep = dir * POLAR_TAU * polarFrac(v, domainLo, domainHi)
              val a0 = start
              val a1 = start + sweep
              sectors.add(PolarSector(series = si, index = i, start = if (a0 < a1) a0 else a1, end = if (a0 < a1) a1 else a0, innerR = r0 + width * colF, outerR = r0 + width * (colF + 1.0), color = color, value = v))
            }
          }
          iF = iF + 1.0
        }
      }
      for (si in 0 until series.length) {
        val s = series[si]
        if (s.kind != "line" && s.kind != "scatter") {
          continue
        }
        val color = (s.color ?: paletteAt(palette, si))
        val points: MutableList<PolarPoint> = mutableListOf()
        var iF = 0.0
        for (i in 0 until n) {
          if (i < s.values.length) {
            val v = s.values[i]
            if (isFiniteNumber(v)) {
              points.add(PolarPoint(series = si, index = i, at = pointOnCircle(center, innerR + ring * (iF + 0.5), start + dir * POLAR_TAU * polarFrac(v, domainLo, domainHi)), color = color, value = v))
            }
          }
          iF = iF + 1.0
        }
        lines.add(PolarLine(series = si, color = color, points = points, scatter = s.kind == "scatter", radius = (s.radius ?: (if (s.kind == "scatter") 4.0 else 2.5))))
      }
      var iF = 0.0
      for (i in 0 until n) {
        categoryLabels.add(PolarCategoryLabel(text = axes.categories[i], at = PyreonChartPt(x = center.x + 4.0, y = center.y - (innerR + ring * (iF + 0.5))), align = "start"))
        iF = iF + 1.0
      }
    }
    val ticks: MutableList<PolarTick> = mutableListOf()
    for (v in polarTicks(domainLo, domainHi)) {
      ticks.add(PolarTick(value = v, label = "${v}"))
    }
    return PolarLayout(center = center, innerR = innerR, outerR = outerR, domain = Domain(min = domainLo, max = domainHi), categoryOn = categoryOn, sectors = sectors, lines = lines, categoryLabels = categoryLabels, ticks = ticks)
  }

fun ringPolyline(center: PyreonChartPt, r: Double): List<PyreonChartPt> {
    val full = arcPolygon(center, r, 0.0, 0.0, POLAR_TAU)
    val out: MutableList<PyreonChartPt> = mutableListOf()
    for (i in 0 until full.length) {
      if (i >= 65) {
        break
      }
      out.add(full[i])
    }
    return out
  }

fun renderPolar(layout: PolarLayout, options: PolarOptions? = null): List<PyreonDrawCmd> {
    val out: MutableList<PyreonDrawCmd> = mutableListOf()
    val rawP = (options?.progress ?: 1.0)
    val progress = if (rawP < 0.0) 0.0 else if (rawP > 1.0) 1.0 else rawP
    val gridColor = (options?.gridColor ?: "#e2e8f0")
    val labelColor = (options?.labelColor ?: "#64748b")
    val fontSize = (options?.fontSize ?: 11.0)
    val lineWidth = (options?.lineWidth ?: 2.0)
    val c = layout.center
    val lo = layout.domain.min
    val hi = layout.domain.max
    if (options?.showGrid != false) {
      if (layout.categoryOn == "angle") {
        for (t in layout.ticks) {
          val r = layout.innerR + (layout.outerR - layout.innerR) * polarFrac(t.value, lo, hi)
          if (r <= 0.0) {
            continue
          }
          out.add(PyreonDrawCmd(kind = "polyline", stroke = gridColor, width = 1.0, points = ringPolyline(c, r)))
        }
      } else {
        var kF = 0.0
        for (k in 0 until 8) {
          out.add(PyreonDrawCmd(kind = "line", from = c, to = pointOnCircle(c, layout.outerR, ((kF).toDouble() / (8.0).toDouble()) * POLAR_TAU), stroke = gridColor, width = 1.0))
          kF = kF + 1.0
        }
        out.add(PyreonDrawCmd(kind = "polyline", stroke = gridColor, width = 1.0, points = ringPolyline(c, layout.outerR)))
      }
    }
    for (s in layout.sectors) {
      val outerR = if (layout.categoryOn == "angle") s.innerR + (s.outerR - s.innerR) * progress else s.outerR
      val end = if (layout.categoryOn == "radius") s.start + (s.end - s.start) * progress else s.end
      if (outerR <= s.innerR || end <= s.start) {
        continue
      }
      out.add(PyreonDrawCmd(kind = "polygon", fill = s.color, points = arcPolygon(c, outerR, s.innerR, s.start, end)))
    }
    for (l in layout.lines) {
      var lenF = 0.0
      for (i in 0 until l.points.length) {
        lenF = lenF + 1.0
      }
      var countF = 0.0
      if (progress >= 1.0) {
        countF = lenF
      } else {
        while (countF + 1.0 <= lenF * progress) {
          countF = countF + 1.0
        }
      }
      val pts: MutableList<PyreonChartPt> = mutableListOf()
      var iF = 0.0
      for (i in 0 until l.points.length) {
        if (iF >= countF) {
          break
        }
        pts.add(l.points[i].at)
        iF = iF + 1.0
      }
      if (pts.length > 1 && !l.scatter) {
        out.add(PyreonDrawCmd(kind = "polyline", stroke = l.color, width = lineWidth, points = pts))
      }
      for (p in pts) {
        out.add(PyreonDrawCmd(kind = "circle", fill = l.color, center = p, radius = l.radius))
      }
    }
    if (options?.showLabels != false && progress >= 1.0) {
      for (lab in layout.categoryLabels) {
        out.add(PyreonDrawCmd(kind = "text", fill = labelColor, text = lab.text, at = lab.at, size = fontSize, align = lab.align, baseline = "middle"))
      }
    }
    return out
  }

fun hitPolarIndex(layout: PolarLayout, px: Double, py: Double): PolarHitIndex {
    val dx = px - layout.center.x
    val dy = py - layout.center.y
    val dist = Math.sqrt((dx * dx + dy * dy).toDouble())
    val ang = Math.atan2((dy).toDouble(), (dx).toDouble())
    var sectorIdx = -1
    for (i in 0 until layout.sectors.length) {
      if (sectorIdx >= 0) {
        continue
      }
      val s = layout.sectors[i]
      if (dist < s.innerR || dist > s.outerR) {
        continue
      }
      var t = ang
      while (t < s.start) {
        t = t + POLAR_TAU
      }
      while (t >= s.start + POLAR_TAU) {
        t = t - POLAR_TAU
      }
      if (t <= s.end) {
        sectorIdx = i
      }
    }
    if (sectorIdx >= 0) {
      return PolarHitIndex(sector = sectorIdx, line = -1, point = -1)
    }
    var bestLine = -1
    var bestPoint = -1
    var bestD = 36.0
    for (li in 0 until layout.lines.length) {
      val l = layout.lines[li]
      for (pi in 0 until l.points.length) {
        val p = l.points[pi]
        val d = (px - p.at.x) * (px - p.at.x) + (py - p.at.y) * (py - p.at.y)
        if (d <= bestD) {
          bestLine = li
          bestPoint = pi
          bestD = d
        }
      }
    }
    return PolarHitIndex(sector = -1, line = bestLine, point = bestPoint)
  }

fun sankeyRgba(hex: String, alpha: Double): String {
    if (hex.length < 7) {
      return hex
    }
    val r = hexDigit(hex[(1).toInt()].code.toDouble()) * 16.0 + hexDigit(hex[(2).toInt()].code.toDouble())
    val g = hexDigit(hex[(3).toInt()].code.toDouble()) * 16.0 + hexDigit(hex[(4).toInt()].code.toDouble())
    val b = hexDigit(hex[(5).toInt()].code.toDouble()) * 16.0 + hexDigit(hex[(6).toInt()].code.toDouble())
    return "rgba(${Math.round(r)}, ${Math.round(g)}, ${Math.round(b)}, ${alpha})"
  }

fun sankeyIndexOf(nodes: List<SankeyNode>, name: String): Int {
    for (i in 0 until nodes.length) {
      if (nodes[i].name == name) {
        return i
      }
    }
    return -1
  }

fun layoutSankey(nodes: List<SankeyNode>, links: List<SankeyLink>, box: PyreonChartRect, options: SankeyOptions? = null): SankeyLayout {
    val palette = (options?.palette ?: DEFAULT_PALETTE)
    val nodeWidth = (options?.nodeWidth ?: 16.0)
    val padding = (options?.nodePadding ?: 8.0)
    val iterations = (options?.iterations ?: 6.0)
    val align = (options?.align ?: "justify")
    val dropped: MutableList<String> = mutableListOf()
    val keptS: MutableList<Int> = mutableListOf()
    val keptT: MutableList<Int> = mutableListOf()
    val keptV: MutableList<Double> = mutableListOf()
    for (l in links) {
      val s = sankeyIndexOf(nodes, l.source)
      val t = sankeyIndexOf(nodes, l.target)
      if (s < 0 || t < 0 || s == t || !(l.value > 0.0)) {
        dropped.add("${l.source} -> ${l.target}")
        continue
      }
      keptS.add(s)
      keptT.add(t)
      keptV.add(l.value)
    }
    val n = nodes.length
    val depth: MutableList<Int> = mutableListOf()
    for (i in 0 until n) {
      depth.add(0)
    }
    val live: MutableList<Boolean> = mutableListOf()
    for (k in 0 until keptS.length) {
      live.add(true)
    }
    var round = 0
    var settled = false
    while (!settled && round <= n) {
      var changed = false
      for (k in 0 until keptS.length) {
        if (!live[k]) {
          continue
        }
        val s = keptS[k]
        val t = keptT[k]
        if (depth[t] < depth[s] + 1) {
          if (round == n) {
            live[k] = false
            dropped.add("${nodes[s].name} -> ${nodes[t].name} (cycle)")
          } else {
            depth[t] = depth[s] + 1
            changed = true
          }
        }
      }
      if (!changed) {
        settled = true
      }
      round = round + 1
    }
    val flowS: MutableList<Int> = mutableListOf()
    val flowT: MutableList<Int> = mutableListOf()
    val flowV: MutableList<Double> = mutableListOf()
    for (k in 0 until keptS.length) {
      if (!live[k]) {
        continue
      }
      flowS.add(keptS[k])
      flowT.add(keptT[k])
      flowV.add(keptV[k])
    }
    var maxDepth = 0
    for (i in 0 until n) {
      if (depth[i] > maxDepth) {
        maxDepth = depth[i]
      }
    }
    if (align == "justify") {
      val hasOut: MutableList<Boolean> = mutableListOf()
      for (i in 0 until n) {
        hasOut.add(false)
      }
      for (s in flowS) {
        hasOut[s] = true
      }
      for (i in 0 until n) {
        if (!hasOut[i]) {
          depth[i] = maxDepth
        }
      }
    }
    val inSum: MutableList<Double> = mutableListOf()
    val outSum: MutableList<Double> = mutableListOf()
    for (i in 0 until n) {
      inSum.add(0.0)
      outSum.add(0.0)
    }
    for (k in 0 until flowS.length) {
      outSum[flowS[k]] = outSum[flowS[k]] + flowV[k]
      inSum[flowT[k]] = inSum[flowT[k]] + flowV[k]
    }
    val value: MutableList<Double> = mutableListOf()
    for (i in 0 until n) {
      value.add(if (inSum[i] > outSum[i]) inSum[i] else outSum[i])
    }
    var ky = 0.0
    var kySeen = false
    for (d in 0..maxDepth) {
      var total = 0.0
      var members = 0.0
      for (i in 0 until n) {
        if (depth[i] != d) {
          continue
        }
        total = total + value[i]
        members = members + 1.0
      }
      val avail = box.h - padding * (if (members > 1.0) members - 1.0 else 0.0)
      if (total > 0.0 && avail > 0.0) {
        val cand = (avail).toDouble() / (total).toDouble()
        if (!kySeen || cand < ky) {
          ky = cand
        }
        kySeen = true
      }
    }
    var maxDepthF = 0.0
    for (d in 0 until maxDepth) {
      maxDepthF = maxDepthF + 1.0
    }
    val y0: MutableList<Double> = mutableListOf()
    val hgt: MutableList<Double> = mutableListOf()
    for (i in 0 until n) {
      y0.add(0.0)
      hgt.add(value[i] * ky)
    }
    for (d in 0..maxDepth) {
      var y = box.y
      for (i in 0 until n) {
        if (depth[i] != d) {
          continue
        }
        y0[i] = y
        y = y + hgt[i] + padding
      }
    }
    var itF = 0.0
    for (it in 0 until Math.ceil(iterations).toInt()) {
      val alpha = 0.99 - itF * ((0.99).toDouble() / ((if (iterations > 1.0) iterations else 1.0)).toDouble())
      for (pass in 0 until 2) {
        val forward = pass == 0
        val dStart = if (forward) 1 else maxDepth - 1
        val dEnd = if (forward) maxDepth else 0
        val dStep = if (forward) 1 else -1
        var d = dStart
        var more = if (forward) d <= dEnd else d >= dEnd
        while (more) {
          for (i in 0 until n) {
            if (depth[i] != d) {
              continue
            }
            var w = 0.0
            var acc = 0.0
            for (k in 0 until flowS.length) {
              val other = if (forward) flowS[k] else flowT[k]
              val mine = if (forward) flowT[k] else flowS[k]
              if (mine != i) {
                continue
              }
              acc = acc + (y0[other] + (hgt[other]).toDouble() / (2.0).toDouble()) * flowV[k]
              w = w + flowV[k]
            }
            if (w > 0.0) {
              y0[i] = y0[i] + ((acc).toDouble() / (w).toDouble() - (y0[i] + (hgt[i]).toDouble() / (2.0).toDouble())) * alpha
            }
          }
          val col: MutableList<Int> = mutableListOf()
          for (i in 0 until n) {
            if (depth[i] == d) {
              col.add(i)
            }
          }
          for (a in 1 until col.length) {
            val cur = col[a]
            val cc = y0[cur] + (hgt[cur]).toDouble() / (2.0).toDouble()
            var b = a - 1
            while (b >= 0) {
              val prev = col[b]
              if (y0[prev] + (hgt[prev]).toDouble() / (2.0).toDouble() <= cc) {
                break
              }
              col[b + 1] = prev
              b = b - 1
            }
            col[b + 1] = cur
          }
          var y = box.y
          for (i in col) {
            if (y0[i] < y) {
              y0[i] = y
            }
            y = y0[i] + hgt[i] + padding
          }
          var bottom = box.y + box.h
          for (k in col.length - 1 downTo 0) {
            val i = col[k]
            if (y0[i] + hgt[i] > bottom) {
              y0[i] = bottom - hgt[i]
            }
            bottom = y0[i] - padding
          }
          d = d + dStep
          more = if (forward) d <= dEnd else d >= dEnd
        }
      }
      itF = itF + 1.0
    }
    val outNodes: MutableList<SankeyLayoutNode> = mutableListOf()
    for (i in 0 until n) {
      var depthF = 0.0
      for (d in 0 until depth[i]) {
        depthF = depthF + 1.0
      }
      val x = if (maxDepthF <= 0.0) box.x else box.x + (((box.w - nodeWidth) * depthF)).toDouble() / (maxDepthF).toDouble()
      outNodes.add(SankeyLayoutNode(name = nodes[i].name, index = i, depth = depth[i], value = value[i], rect = PyreonChartRect(x = x, y = y0[i], w = nodeWidth, h = hgt[i]), color = (nodes[i].color ?: paletteAt(palette, i))))
    }
    val outCursor: MutableList<Double> = mutableListOf()
    val inCursor: MutableList<Double> = mutableListOf()
    for (i in 0 until n) {
      outCursor.add(y0[i])
      inCursor.add(y0[i])
    }
    val linkY0: MutableList<Double> = mutableListOf()
    val linkY1: MutableList<Double> = mutableListOf()
    for (k in 0 until flowS.length) {
      linkY0.add(0.0)
      linkY1.add(0.0)
    }
    val orderOut: MutableList<Int> = mutableListOf()
    for (k in 0 until flowS.length) {
      orderOut.add(k)
    }
    for (a in 1 until orderOut.length) {
      val cur = orderOut[a]
      val ct = y0[flowT[cur]] + (hgt[flowT[cur]]).toDouble() / (2.0).toDouble()
      var b = a - 1
      while (b >= 0) {
        val prev = orderOut[b]
        val pt = y0[flowT[prev]] + (hgt[flowT[prev]]).toDouble() / (2.0).toDouble()
        if (pt < ct || (pt == ct && flowS[prev] <= flowS[cur])) {
          break
        }
        orderOut[b + 1] = prev
        b = b - 1
      }
      orderOut[b + 1] = cur
    }
    for (k in orderOut) {
      linkY0[k] = outCursor[flowS[k]]
      outCursor[flowS[k]] = outCursor[flowS[k]] + flowV[k] * ky
    }
    val orderIn: MutableList<Int> = mutableListOf()
    for (k in 0 until flowS.length) {
      orderIn.add(k)
    }
    for (a in 1 until orderIn.length) {
      val cur = orderIn[a]
      val cs = y0[flowS[cur]] + (hgt[flowS[cur]]).toDouble() / (2.0).toDouble()
      var b = a - 1
      while (b >= 0) {
        val prev = orderIn[b]
        val ps = y0[flowS[prev]] + (hgt[flowS[prev]]).toDouble() / (2.0).toDouble()
        if (ps < cs || (ps == cs && flowT[prev] <= flowT[cur])) {
          break
        }
        orderIn[b + 1] = prev
        b = b - 1
      }
      orderIn[b + 1] = cur
    }
    for (k in orderIn) {
      linkY1[k] = inCursor[flowT[k]]
      inCursor[flowT[k]] = inCursor[flowT[k]] + flowV[k] * ky
    }
    val outLinks: MutableList<SankeyLayoutLink> = mutableListOf()
    for (k in 0 until flowS.length) {
      outLinks.add(SankeyLayoutLink(source = flowS[k], target = flowT[k], value = flowV[k], width = flowV[k] * ky, y0 = linkY0[k], y1 = linkY1[k]))
    }
    return SankeyLayout(nodes = outNodes, links = outLinks, dropped = dropped)
  }

fun ribbonPoints(layout: SankeyLayout, link: SankeyLayoutLink, progress: Double? = null): List<PyreonChartPt> {
    val s = layout.nodes[link.source].rect
    val t = layout.nodes[link.target].rect
    val x0 = s.x + s.w
    val x1raw = t.x
    val rawP = (progress ?: 1.0)
    val p = if (rawP < 0.0) 0.0 else if (rawP > 1.0) 1.0 else rawP
    val x1 = x0 + (x1raw - x0) * p
    val top: MutableList<PyreonChartPt> = mutableListOf()
    val bottom: MutableList<PyreonChartPt> = mutableListOf()
    var iF = 0.0
    for (i in 0..16) {
      val u = (iF).toDouble() / (16.0).toDouble()
      val e = u * u * (3.0 - 2.0 * u)
      val x = x0 + (x1 - x0) * u
      top.add(PyreonChartPt(x = x, y = link.y0 + (link.y1 - link.y0) * e))
      bottom.add(PyreonChartPt(x = x, y = link.y0 + link.width + (link.y1 + link.width - (link.y0 + link.width)) * e))
      iF = iF + 1.0
    }
    val out: MutableList<PyreonChartPt> = mutableListOf()
    for (p2 in top) {
      out.add(p2)
    }
    var bi = bottom.length - 1
    while (bi >= 0) {
      out.add(bottom[bi])
      bi = bi - 1
    }
    return out
  }

fun renderSankey(layout: SankeyLayout, options: SankeyOptions? = null): List<PyreonDrawCmd> {
    val out: MutableList<PyreonDrawCmd> = mutableListOf()
    val opacity = (options?.linkOpacity ?: 0.35)
    val rawP = (options?.progress ?: 1.0)
    val progress = if (rawP < 0.0) 0.0 else if (rawP > 1.0) 1.0 else rawP
    val showLabels = (options?.showLabels ?: true)
    val fontSize = (options?.fontSize ?: 11.0)
    val labelColor = (options?.labelColor ?: "#334155")
    var maxDepth = 0
    for (nd in layout.nodes) {
      if (nd.depth > maxDepth) {
        maxDepth = nd.depth
      }
    }
    for (l in layout.links) {
      if (l.width <= 0.0) {
        continue
      }
      out.add(PyreonDrawCmd(kind = "polygon", fill = sankeyRgba(layout.nodes[l.source].color, opacity), points = ribbonPoints(layout, l, progress)))
    }
    for (nd in layout.nodes) {
      if (nd.rect.h <= 0.0) {
        continue
      }
      out.add(PyreonDrawCmd(kind = "rect", rect = nd.rect, fill = nd.color))
      if (!showLabels || progress < 1.0) {
        continue
      }
      val last = nd.depth == maxDepth
      out.add(PyreonDrawCmd(kind = "text", fill = labelColor, text = nd.name, at = PyreonChartPt(x = if (last) nd.rect.x - 4.0 else nd.rect.x + nd.rect.w + 4.0, y = nd.rect.y + (nd.rect.h).toDouble() / (2.0).toDouble()), size = fontSize, align = if (last) "end" else "start", baseline = "middle"))
    }
    return out
  }

fun sankeyPointInPolygon(pts: List<PyreonChartPt>, px: Double, py: Double): Boolean {
    var inside = false
    var j = pts.length - 1
    for (i in 0 until pts.length) {
      val a = pts[i]
      val b = pts[j]
      val aAbove = a.y > py
      val bAbove = b.y > py
      if (aAbove != bAbove && px < (((b.x - a.x) * (py - a.y))).toDouble() / ((b.y - a.y)).toDouble() + a.x) {
        inside = !inside
      }
      j = i
    }
    return inside
  }

fun hitSankeyIndex(layout: SankeyLayout, px: Double, py: Double): SankeyHitIndex {
    var nodeIdx = -1
    for (i in 0 until layout.nodes.length) {
      if (nodeIdx >= 0) {
        continue
      }
      val r = layout.nodes[i].rect
      if (px >= r.x && px <= r.x + r.w && py >= r.y && py <= r.y + r.h) {
        nodeIdx = i
      }
    }
    if (nodeIdx >= 0) {
      return SankeyHitIndex(node = nodeIdx, link = -1)
    }
    var linkIdx = -1
    for (k in 0 until layout.links.length) {
      if (linkIdx >= 0) {
        continue
      }
      val l = layout.links[k]
      if (l.width > 0.0 && sankeyPointInPolygon(ribbonPoints(layout, l, 1.0), px, py)) {
        linkIdx = k
      }
    }
    return SankeyHitIndex(node = -1, link = linkIdx)
  }

fun graphNextSeed(state: Double): Double {
    val raw = state * 16807.0
    return raw - Math.floor((raw).toDouble() / (GRAPH_LCG_M).toDouble()) * GRAPH_LCG_M
  }

fun graphSeedState(seed: Double): Double {
    val f = Math.floor(if (seed < 0.0) -seed else seed)
    val wrapped = f - Math.floor((f).toDouble() / ((GRAPH_LCG_M - 1.0)).toDouble()) * (GRAPH_LCG_M - 1.0)
    return wrapped + 1.0
  }

fun graphIndexOf(nodes: List<GraphNode>, id: String): Int {
    for (i in 0 until nodes.length) {
      if (nodes[i].id == id) {
        return i
      }
    }
    return -1
  }

fun graphRadius(value: Double, hasValue: Boolean, maxValue: Double, base: Double): Double {
    if (!hasValue || maxValue <= 0.0) {
      return (base).toDouble() / (2.0).toDouble()
    }
    val v = if (value < 0.0) 0.0 else value
    return ((base).toDouble() / (2.0).toDouble()) * (0.6 + 1.4 * Math.sqrt(((v).toDouble() / (maxValue).toDouble()).toDouble()))
  }

fun layoutGraph(nodes: List<GraphNode>, links: List<GraphLink>, box: PyreonChartRect, options: GraphOptions? = null): GraphLayout {
    val palette = (options?.palette ?: DEFAULT_PALETTE)
    val mode = (options?.layout ?: "force")
    val base = (options?.symbolSize ?: 10.0)
    val dropped: MutableList<String> = mutableListOf()
    val outLinks: MutableList<GraphLayoutLink> = mutableListOf()
    for (l in links) {
      val s = graphIndexOf(nodes, l.source)
      val t = graphIndexOf(nodes, l.target)
      if (s < 0 || t < 0) {
        dropped.add("${l.source} -> ${l.target}")
        continue
      }
      outLinks.add(GraphLayoutLink(source = s, target = t, value = l.value, index = outLinks.length))
    }
    val n = nodes.length
    var nF = 0.0
    for (i in 0 until n) {
      nF = nF + 1.0
    }
    var maxValue = 0.0
    for (nd in nodes) {
      val v = (nd.value ?: -1.0)
      if (v > maxValue) {
        maxValue = v
      }
    }
    val cx = box.x + (box.w).toDouble() / (2.0).toDouble()
    val cy = box.y + (box.h).toDouble() / (2.0).toDouble()
    val px: MutableList<Double> = mutableListOf()
    val py: MutableList<Double> = mutableListOf()
    val radius: MutableList<Double> = mutableListOf()
    for (i in 0 until n) {
      px.add(cx)
      py.add(cy)
      val v = (nodes[i].value ?: -1.0)
      radius.add(graphRadius(v, v >= 0.0, maxValue, base))
    }
    if (mode == "circular") {
      val half = ((if (box.w < box.h) box.w else box.h)).toDouble() / (2.0).toDouble() - base
      val R = if (half < 0.0) 0.0 else half
      var iF = 0.0
      for (i in 0 until n) {
        val ang = (-kotlin.math.PI).toDouble() / (2.0).toDouble() + (if (nF <= 0.0) 0.0 else ((iF).toDouble() / (nF).toDouble()) * GRAPH_TAU)
        px[i] = cx + Math.cos((ang).toDouble()) * R
        py[i] = cy + Math.sin((ang).toDouble()) * R
        iF = iF + 1.0
      }
    } else {
      if (mode == "none") {
        var minX = 0.0
        var maxX = 0.0
        var minY = 0.0
        var maxY = 0.0
        var seen = false
        for (nd in nodes) {
          val x = (nd.x ?: 0.0)
          val y = (nd.y ?: 0.0)
          if (!seen || x < minX) {
            minX = x
          }
          if (!seen || x > maxX) {
            maxX = x
          }
          if (!seen || y < minY) {
            minY = y
          }
          if (!seen || y > maxY) {
            maxY = y
          }
          seen = true
        }
        val spanX = maxX - minX
        val spanY = maxY - minY
        val pad = base
        for (i in 0 until n) {
          val fx = if (spanX <= 0.0) 0.5 else ((((nodes[i].x ?: 0.0)) - minX)).toDouble() / (spanX).toDouble()
          val fy = if (spanY <= 0.0) 0.5 else ((((nodes[i].y ?: 0.0)) - minY)).toDouble() / (spanY).toDouble()
          px[i] = box.x + pad + (box.w - pad * 2.0) * fx
          py[i] = box.y + pad + (box.h - pad * 2.0) * fy
        }
      } else {
        var seed = graphSeedState((options?.seed ?: 7.0))
        val rawIt = Math.floor((options?.iterations ?: 200.0))
        val iterations = if (rawIt < 0.0) 0.0 else rawIt
        val rawArea = box.w * box.h
        val area = if (rawArea < 1.0) 1.0 else rawArea
        val k = Math.sqrt(((area).toDouble() / ((if (nF < 1.0) 1.0 else nF)).toDouble()).toDouble())
        val repulsion = (options?.repulsion ?: k * k)
        val linkDistance = (options?.linkDistance ?: k)
        val gravity = (options?.gravity ?: 0.05)
        val spread = ((if (box.w < box.h) box.w else box.h)).toDouble() / (3.0).toDouble()
        for (i in 0 until n) {
          seed = graphNextSeed(seed)
          px[i] = cx + ((seed).toDouble() / (GRAPH_LCG_M).toDouble() - 0.5) * spread
          seed = graphNextSeed(seed)
          py[i] = cy + ((seed).toDouble() / (GRAPH_LCG_M).toDouble() - 0.5) * spread
        }
        var temp = ((if (box.w > box.h) box.w else box.h)).toDouble() / (10.0).toDouble()
        val cool = if (iterations <= 0.0) 0.0 else (temp).toDouble() / (iterations).toDouble()
        val dx: MutableList<Double> = mutableListOf()
        val dy: MutableList<Double> = mutableListOf()
        for (i in 0 until n) {
          dx.add(0.0)
          dy.add(0.0)
        }
        var it = 0.0
        while (it < iterations) {
          for (i in 0 until n) {
            dx[i] = 0.0
            dy[i] = 0.0
          }
          for (i in 0 until n) {
            for (j in i + 1 until n) {
              var ddx = px[i] - px[j]
              var ddy = py[i] - py[j]
              var d = Math.sqrt((ddx * ddx + ddy * ddy).toDouble())
              if (d < 0.01) {
                seed = graphNextSeed(seed)
                ddx = ((seed).toDouble() / (GRAPH_LCG_M).toDouble() - 0.5) * 0.1
                seed = graphNextSeed(seed)
                ddy = ((seed).toDouble() / (GRAPH_LCG_M).toDouble() - 0.5) * 0.1
                d = 0.01
              }
              val f = (repulsion).toDouble() / ((d * d)).toDouble()
              val fx = ((ddx).toDouble() / (d).toDouble()) * f
              val fy = ((ddy).toDouble() / (d).toDouble()) * f
              dx[i] = dx[i] + fx
              dy[i] = dy[i] + fy
              dx[j] = dx[j] - fx
              dy[j] = dy[j] - fy
            }
          }
          for (l in outLinks) {
            var ddx = px[l.source] - px[l.target]
            var ddy = py[l.source] - py[l.target]
            var d = Math.sqrt((ddx * ddx + ddy * ddy).toDouble())
            if (d <= 0.0) {
              continue
            }
            val f = ((d * d)).toDouble() / (linkDistance).toDouble()
            val fx = ((ddx).toDouble() / (d).toDouble()) * f
            val fy = ((ddy).toDouble() / (d).toDouble()) * f
            dx[l.source] = dx[l.source] - fx
            dy[l.source] = dy[l.source] - fy
            dx[l.target] = dx[l.target] + fx
            dy[l.target] = dy[l.target] + fy
          }
          for (i in 0 until n) {
            dx[i] = dx[i] + (cx - px[i]) * gravity * k * 0.1
            dy[i] = dy[i] + (cy - py[i]) * gravity * k * 0.1
            var d = Math.sqrt((dx[i] * dx[i] + dy[i] * dy[i]).toDouble())
            if (d > 0.0) {
              val step = if (d < temp) d else temp
              px[i] = px[i] + ((dx[i]).toDouble() / (d).toDouble()) * step
              py[i] = py[i] + ((dy[i]).toDouble() / (d).toDouble()) * step
            }
            val r = radius[i]
            if (px[i] < box.x + r) {
              px[i] = box.x + r
            }
            if (px[i] > box.x + box.w - r) {
              px[i] = box.x + box.w - r
            }
            if (py[i] < box.y + r) {
              py[i] = box.y + r
            }
            if (py[i] > box.y + box.h - r) {
              py[i] = box.y + box.h - r
            }
          }
          temp = temp - cool
          if (temp < 0.5) {
            temp = 0.5
          }
          it = it + 1.0
        }
      }
    }
    val outNodes: MutableList<GraphLayoutNode> = mutableListOf()
    for (i in 0 until n) {
      val nd = nodes[i]
      val cat = nd.category
      val color = (nd.color ?: paletteAt(palette, (cat ?: i)))
      outNodes.add(GraphLayoutNode(id = nd.id, name = (nd.name ?: nd.id), index = i, at = PyreonChartPt(x = px[i], y = py[i]), radius = radius[i], color = color, category = cat, value = nd.value))
    }
    return GraphLayout(mode = mode, nodes = outNodes, links = outLinks, dropped = dropped)
  }

fun graphAt(n: GraphLayoutNode, cx: Double, cy: Double, progress: Double): PyreonChartPt = PyreonChartPt(x = cx + (n.at.x - cx) * progress, y = cy + (n.at.y - cy) * progress)

fun renderGraph(layout: GraphLayout, box: PyreonChartRect, options: GraphOptions? = null): List<PyreonDrawCmd> {
    val out: MutableList<PyreonDrawCmd> = mutableListOf()
    val rawP = (options?.progress ?: 1.0)
    val progress = if (rawP < 0.0) 0.0 else if (rawP > 1.0) 1.0 else rawP
    val cx = box.x + (box.w).toDouble() / (2.0).toDouble()
    val cy = box.y + (box.h).toDouble() / (2.0).toDouble()
    val linkColor = (options?.linkColor ?: "#94a3b8")
    val showLabels = (options?.showLabels ?: false)
    val fontSize = (options?.fontSize ?: 11.0)
    val labelColor = (options?.labelColor ?: "#334155")
    var maxLink = 0.0
    for (l in layout.links) {
      val v = (l.value ?: -1.0)
      if (v > maxLink) {
        maxLink = v
      }
    }
    for (l in layout.links) {
      val v = (l.value ?: -1.0)
      val width = if (v < 0.0 || maxLink <= 0.0) 1.0 else 1.0 + 3.0 * ((v).toDouble() / (maxLink).toDouble())
      out.add(PyreonDrawCmd(kind = "line", from = graphAt(layout.nodes[l.source], cx, cy, progress), to = graphAt(layout.nodes[l.target], cx, cy, progress), stroke = linkColor, width = width))
    }
    for (nd in layout.nodes) {
      out.add(PyreonDrawCmd(kind = "circle", fill = nd.color, center = graphAt(nd, cx, cy, progress), radius = nd.radius))
      if (!showLabels || progress < 1.0) {
        continue
      }
      out.add(PyreonDrawCmd(kind = "text", fill = labelColor, text = nd.name, at = PyreonChartPt(x = nd.at.x + nd.radius + 3.0, y = nd.at.y), size = fontSize, align = "start", baseline = "middle"))
    }
    return out
  }

fun hitGraphIndex(layout: GraphLayout, px: Double, py: Double): Int {
    var best = -1
    var bestD = 0.0
    for (i in 0 until layout.nodes.length) {
      val nd = layout.nodes[i]
      val dx = px - nd.at.x
      val dy = py - nd.at.y
      val d = dx * dx + dy * dy
      val r = nd.radius + 3.0
      if (d <= r * r && (best < 0 || d < bestD)) {
        best = i
        bestD = d
      }
    }
    return best
  }

fun daysFromCivil(year: Double, month: Double, day: Double): Double {
    val yy = if (month <= 2.0) year - 1.0 else year
    val era = Math.floor((yy).toDouble() / (400.0).toDouble())
    val yoe = yy - era * 400.0
    val mp = if (month > 2.0) month - 3.0 else month + 9.0
    val doy = Math.floor(((153.0 * mp + 2.0)).toDouble() / (5.0).toDouble()) + day - 1.0
    val doe = yoe * 365.0 + Math.floor((yoe).toDouble() / (4.0).toDouble()) - Math.floor((yoe).toDouble() / (100.0).toDouble()) + doy
    return era * 146097.0 + doe - 719468.0
  }

fun civilFromDays(days: Double): CalendarDate {
    val z = days + 719468.0
    val era = Math.floor((z).toDouble() / (146097.0).toDouble())
    val doe = z - era * 146097.0
    val yoe = Math.floor(((doe - Math.floor((doe).toDouble() / (1460.0).toDouble()) + Math.floor((doe).toDouble() / (36524.0).toDouble()) - Math.floor((doe).toDouble() / (146096.0).toDouble()))).toDouble() / (365.0).toDouble())
    val y = yoe + era * 400.0
    val doy = doe - (365.0 * yoe + Math.floor((yoe).toDouble() / (4.0).toDouble()) - Math.floor((yoe).toDouble() / (100.0).toDouble()))
    val mp = Math.floor(((5.0 * doy + 2.0)).toDouble() / (153.0).toDouble())
    val d = doy - Math.floor(((153.0 * mp + 2.0)).toDouble() / (5.0).toDouble()) + 1.0
    val m = if (mp < 10.0) mp + 3.0 else mp - 9.0
    return CalendarDate(year = if (m <= 2.0) y + 1.0 else y, month = m, day = d)
  }

fun weekdayOfDays(days: Double): Double {
    val x = days + 4.0
    return x - Math.floor((x).toDouble() / (7.0).toDouble()) * 7.0
  }

fun calendarDigit(c: Double): Double {
    if (c >= 48.0 && c <= 57.0) {
      return c - 48.0
    }
    return -1.0
  }

fun parseIsoDays(s: String): CalendarParsed {
    if (s.length != 10 || s[(4).toInt()].code.toDouble() != 45.0 || s[(7).toInt()].code.toDouble() != 45.0) {
      return CalendarParsed(ok = false, days = 0.0)
    }
    val y0 = calendarDigit(s[(0).toInt()].code.toDouble())
    val y1 = calendarDigit(s[(1).toInt()].code.toDouble())
    val y2 = calendarDigit(s[(2).toInt()].code.toDouble())
    val y3 = calendarDigit(s[(3).toInt()].code.toDouble())
    val m0 = calendarDigit(s[(5).toInt()].code.toDouble())
    val m1 = calendarDigit(s[(6).toInt()].code.toDouble())
    val d0 = calendarDigit(s[(8).toInt()].code.toDouble())
    val d1 = calendarDigit(s[(9).toInt()].code.toDouble())
    if (y0 < 0.0 || y1 < 0.0 || y2 < 0.0 || y3 < 0.0 || m0 < 0.0 || m1 < 0.0 || d0 < 0.0 || d1 < 0.0) {
      return CalendarParsed(ok = false, days = 0.0)
    }
    val y = y0 * 1000.0 + y1 * 100.0 + y2 * 10.0 + y3
    val m = m0 * 10.0 + m1
    val d = d0 * 10.0 + d1
    if (m < 1.0 || m > 12.0 || d < 1.0 || d > 31.0) {
      return CalendarParsed(ok = false, days = 0.0)
    }
    val days = daysFromCivil(y, m, d)
    val back = civilFromDays(days)
    if (back.month != m || back.day != d) {
      return CalendarParsed(ok = false, days = 0.0)
    }
    return CalendarParsed(ok = true, days = days)
  }

fun formatIsoDays(days: Double): String {
    val c = civilFromDays(days)
    val mp = if (c.month < 10.0) "0" else ""
    val dp = if (c.day < 10.0) "0" else ""
    val yp = if (c.year < 1000.0) (if (c.year < 100.0) (if (c.year < 10.0) "000" else "00") else "0") else ""
    return "${yp}${Math.round(c.year)}-${mp}${Math.round(c.month)}-${dp}${Math.round(c.day)}"
  }

fun layoutCalendar(start: String, end: String, box: PyreonChartRect, options: CalendarOptions? = null): CalendarLayout {
    val p0 = parseIsoDays(start)
    val p1 = parseIsoDays(end)
    if (!p0.ok || !p1.ok || p1.days < p0.days) {
      return CalendarLayout(cells = listOf(), monthLabels = listOf(), dayLabels = listOf(), cellSize = 0.0, startDay = 0.0, days = 0.0)
    }
    val rawFirst = Math.floor((options?.firstDay ?: 0.0))
    val firstDay = if (rawFirst < 0.0) 0.0 else if (rawFirst > 6.0) 6.0 else rawFirst
    val gap = (options?.cellGap ?: 2.0)
    val fontSize = (options?.fontSize ?: 10.0)
    val showMonths = (options?.showMonthLabels ?: true)
    val showDays = (options?.showDayLabels ?: true)
    val gutterX = if (showDays) fontSize * 2.6 else 0.0
    val gutterY = if (showMonths) fontSize * 1.6 else 0.0
    val sr = weekdayOfDays(p0.days) - firstDay + 7.0
    val startRow = sr - Math.floor((sr).toDouble() / (7.0).toDouble()) * 7.0
    val days = p1.days - p0.days + 1.0
    val weeksRaw = ((startRow + days)).toDouble() / (7.0).toDouble()
    val weeksF = Math.floor(weeksRaw)
    val weeks = if (weeksF < weeksRaw) weeksF + 1.0 else weeksF
    val fitW = if (weeks <= 0.0) 0.0 else ((box.w - gutterX)).toDouble() / (weeks).toDouble()
    val fitH = ((box.h - gutterY)).toDouble() / (7.0).toDouble()
    val fitRaw = if (fitW < fitH) fitW else fitH
    val fit = if (fitRaw < 0.0) 0.0 else fitRaw
    val fixed = (options?.cellSize ?: -1.0)
    val pitch = if (fixed >= 0.0) fixed + gap else fit
    val rawCell = pitch - gap
    val cellSize = if (rawCell < 0.0) 0.0 else rawCell
    val originX = box.x + gutterX
    val originY = box.y + gutterY
    val cells: MutableList<CalendarCell> = mutableListOf()
    val monthLabels: MutableList<CalendarLabel> = mutableListOf()
    var lastMonthKey = -1.0
    var iF = 0.0
    while (iF < days) {
      val t = p0.days + iF
      val c = civilFromDays(t)
      val idx = startRow + iF
      val week = Math.floor((idx).toDouble() / (7.0).toDouble())
      val row = idx - week * 7.0
      val rect = PyreonChartRect(x = originX + week * pitch, y = originY + row * pitch, w = cellSize, h = cellSize)
      cells.add(CalendarCell(date = formatIsoDays(t), rect = rect, row = row, week = week, month = c.month - 1.0, day = c.day, year = c.year))
      val key = c.year * 12.0 + c.month
      if (key != lastMonthKey) {
        lastMonthKey = key
        var mi = 0
        var miF = 1.0
        while (miF < c.month) {
          mi = mi + 1
          miF = miF + 1.0
        }
        monthLabels.add(CalendarLabel(kind = "month", text = CALENDAR_MONTHS[mi], at = PyreonChartPt(x = originX + week * pitch, y = originY - fontSize * 0.4)))
      }
      iF = iF + 1.0
    }
    val dayLabels: MutableList<CalendarLabel> = mutableListOf()
    var rF = 0.0
    for (r in 0 until 7) {
      if (r % 2 == 1) {
        val raw = firstDay + rF
        val dIdx = raw - Math.floor((raw).toDouble() / (7.0).toDouble()) * 7.0
        var di = 0
        var diF = 0.0
        while (diF < dIdx) {
          di = di + 1
          diF = diF + 1.0
        }
        dayLabels.add(CalendarLabel(kind = "day", text = CALENDAR_DAYS[di], at = PyreonChartPt(x = originX - fontSize * 0.4, y = originY + rF * pitch + (cellSize).toDouble() / (2.0).toDouble())))
      }
      rF = rF + 1.0
    }
    return CalendarLayout(cells = cells, monthLabels = if (showMonths) monthLabels else listOf(), dayLabels = if (showDays) dayLabels else listOf(), cellSize = cellSize, startDay = p0.days, days = days)
  }

fun calendarCellValues(layout: CalendarLayout, values: List<CalendarValue>): CalendarCellValues {
    val has: MutableList<Boolean> = mutableListOf()
    val value: MutableList<Double> = mutableListOf()
    for (i in 0 until layout.cells.length) {
      has.add(false)
      value.add(0.0)
    }
    val vDays: MutableList<Double> = mutableListOf()
    val vOk: MutableList<Boolean> = mutableListOf()
    for (v in values) {
      val p = parseIsoDays(v.date)
      vDays.add(p.days)
      vOk.add(p.ok && isFiniteNumber(v.value))
    }
    var iF = 0.0
    for (i in 0 until layout.cells.length) {
      val day = layout.startDay + iF
      for (k in 0 until values.length) {
        if (!vOk[k] || vDays[k] != day) {
          continue
        }
        has[i] = true
        value[i] = values[k].value
      }
      iF = iF + 1.0
    }
    return CalendarCellValues(has = has, value = value)
  }

fun calendarDomain(layout: CalendarLayout, values: List<CalendarValue>): Domain {
    val cv = calendarCellValues(layout, values)
    var lo = 0.0
    var hi = 0.0
    var seen = false
    for (i in 0 until cv.has.length) {
      if (!cv.has[i]) {
        continue
      }
      val v = cv.value[i]
      if (!seen || v < lo) {
        lo = v
      }
      if (!seen || v > hi) {
        hi = v
      }
      seen = true
    }
    return Domain(min = lo, max = hi)
  }

fun renderCalendar(layout: CalendarLayout, values: List<CalendarValue>, options: CalendarOptions? = null): List<PyreonDrawCmd> {
    val out: MutableList<PyreonDrawCmd> = mutableListOf()
    val stops = (options?.stops ?: HEAT_RAMP)
    val emptyColor = (options?.emptyColor ?: "#e2e8f0")
    val domain = (options?.domain ?: calendarDomain(layout, values))
    val span = domain.max - domain.min
    val rawP = (options?.progress ?: 1.0)
    val progress = if (rawP < 0.0) 0.0 else if (rawP > 1.0) 1.0 else rawP
    var weeks = 0.0
    for (c in layout.cells) {
      if (c.week + 1.0 > weeks) {
        weeks = c.week + 1.0
      }
    }
    val shownWeeks = if (progress >= 1.0) weeks else Math.floor(weeks * progress)
    val fontSize = (options?.fontSize ?: 10.0)
    val labelColor = (options?.labelColor ?: "#64748b")
    val cv = calendarCellValues(layout, values)
    for (i in 0 until layout.cells.length) {
      val c = layout.cells[i]
      if (c.week >= shownWeeks) {
        continue
      }
      val hasV = cv.has[i]
      val raw = if (!hasV) 0.0 else if (span <= 0.0) 1.0 else ((cv.value[i] - domain.min)).toDouble() / (span).toDouble()
      val t = if (raw < 0.0) 0.0 else if (raw > 1.0) 1.0 else raw
      val outside = hasV && visualOutside(cv.value[i], options?.inRange, options?.outBands)
      out.add(PyreonDrawCmd(kind = "rect", rect = c.rect, fill = if (!hasV) emptyColor else if (outside) (options?.outColor ?: "#cccccc") else rampColor(stops, t)))
    }
    if (progress < 1.0) {
      return out
    }
    for (m in layout.monthLabels) {
      out.add(PyreonDrawCmd(kind = "text", fill = labelColor, text = m.text, at = m.at, size = fontSize, align = "start", baseline = "bottom"))
    }
    for (d in layout.dayLabels) {
      out.add(PyreonDrawCmd(kind = "text", fill = labelColor, text = d.text, at = d.at, size = fontSize, align = "end", baseline = "middle"))
    }
    return out
  }

fun hitCalendarIndex(layout: CalendarLayout, px: Double, py: Double): Int {
    var hit = -1
    for (i in 0 until layout.cells.length) {
      if (hit >= 0) {
        continue
      }
      val r = layout.cells[i].rect
      if (px >= r.x && px <= r.x + r.w && py >= r.y && py <= r.y + r.h) {
        hit = i
      }
    }
    return hit
  }

fun geoValueOf(values: List<GeoValue>, name: String): Double {
    for (v in values) {
      if (v.region == name) {
        return v.value
      }
    }
    return GEO_NA
  }

fun geoProject(t: GeoTransform, lon: Double, lat: Double): PyreonChartPt {
    val p = projectLonLat(lon, lat, t.projection)
    return PyreonChartPt(x = t.ox + (p.x - t.minX) * t.scale, y = t.oy + (t.maxY - p.y) * t.scale)
  }

fun projectLonLat(lon: Double, lat: Double, projection: GeoProjection): PyreonChartPt {
    if (projection == GeoProjection.mercator) {
      val clamped = if (lat > 85.0) 85.0 else if (lat < -85.0) -85.0 else lat
      val phi = ((clamped * kotlin.math.PI)).toDouble() / (180.0).toDouble()
      return PyreonChartPt(x = lon, y = ((Math.log((Math.tan(((kotlin.math.PI).toDouble() / (4.0).toDouble() + (phi).toDouble() / (2.0).toDouble()).toDouble())).toDouble()) * 180.0)).toDouble() / (kotlin.math.PI).toDouble())
    }
    return PyreonChartPt(x = lon, y = lat)
  }

fun ringArea(ring: List<PyreonChartPt>): Double {
    var a = 0.0
    for (i in 0 until ring.length) {
      val j = if (i == 0) ring.length - 1 else i - 1
      a = a + (ring[j].x * ring[i].y - ring[i].x * ring[j].y)
    }
    return (a).toDouble() / (2.0).toDouble()
  }

fun ringCentroid(ring: List<PyreonChartPt>): PyreonChartPt? {
    val a = ringArea(ring)
    if (Math.abs(a) < 1e-12) {
      return null
    }
    var cx = 0.0
    var cy = 0.0
    for (i in 0 until ring.length) {
      val j = if (i == 0) ring.length - 1 else i - 1
      val f = ring[j].x * ring[i].y - ring[i].x * ring[j].y
      cx = cx + (ring[j].x + ring[i].x) * f
      cy = cy + (ring[j].y + ring[i].y) * f
    }
    return PyreonChartPt(x = (cx).toDouble() / ((6.0 * a)).toDouble(), y = (cy).toDouble() / ((6.0 * a)).toDouble())
  }

fun layoutGeoShapes(shapes: List<GeoShape>, box: PyreonChartRect, options: GeoOptions? = null): GeoLayout {
    val projection = (options?.projection ?: GeoProjection.equirectangular)
    val pad = (options?.padding ?: 4.0)
    val raw = shapes
    var minX = 0.0
    var maxX = 0.0
    var minY = 0.0
    var maxY = 0.0
    var seen = 0
    for (sh in raw) {
      for (ring in sh.rings) {
        for (p in ring) {
          if (seen == 0) {
            minX = p.x
            maxX = p.x
            minY = p.y
            maxY = p.y
          }
          if (p.x < minX) {
            minX = p.x
          }
          if (p.x > maxX) {
            maxX = p.x
          }
          if (p.y < minY) {
            minY = p.y
          }
          if (p.y > maxY) {
            maxY = p.y
          }
          seen = seen + 1
        }
      }
    }
    val innerW = Math.max(0.0, box.w - pad * 2.0)
    val innerH = Math.max(0.0, box.h - pad * 2.0)
    val spanX = maxX - minX
    val spanY = maxY - minY
    val fitScale = if (raw.length == 0 || spanX <= 0.0 || spanY <= 0.0) 1.0 else Math.min((innerW).toDouble() / (spanX).toDouble(), (innerH).toDouble() / (spanY).toDouble())
    val fitOx = box.x + pad + ((innerW - spanX * fitScale)).toDouble() / (2.0).toDouble()
    val fitOy = box.y + pad + ((innerH - spanY * fitScale)).toDouble() / (2.0).toDouble()
    val zoom = if (((options?.zoom ?: 1.0)) > 0.0) (options?.zoom ?: 1.0) else 1.0
    val cx = box.x + (box.w).toDouble() / (2.0).toDouble()
    val cy = box.y + (box.h).toDouble() / (2.0).toDouble()
    val scale = fitScale * zoom
    val ox = cx + (fitOx - cx) * zoom + ((options?.panX ?: 0.0))
    val oy = cy + (fitOy - cy) * zoom + ((options?.panY ?: 0.0))
    val toPx = { p: PyreonChartPt -> (PyreonChartPt(x = ox + (p.x - minX) * scale, y = oy + (maxY - p.y) * scale)) }
    val regions = raw.map({ r ->
      val rings = r.rings.map({ ring -> ring.map(toPx) })
      var bx0 = 0.0
      var by0 = 0.0
      var bx1 = 0.0
      var by1 = 0.0
      var bseen = 0
      var bestAt = -1
      var bestArea = -1.0
      for (ri in 0 until rings.length) {
        val ring = rings[ri]
        for (p in ring) {
          if (bseen == 0) {
            bx0 = p.x
            by0 = p.y
            bx1 = p.x
            by1 = p.y
          }
          if (p.x < bx0) {
            bx0 = p.x
          }
          if (p.y < by0) {
            by0 = p.y
          }
          if (p.x > bx1) {
            bx1 = p.x
          }
          if (p.y > by1) {
            by1 = p.y
          }
          bseen = bseen + 1
        }
        val a = Math.abs(ringArea(ring))
        if (a > bestArea) {
          bestArea = a
          bestAt = ri
        }
      }
      val bbox = if (bseen == 0) PyreonChartRect(x = box.x, y = box.y, w = 0.0, h = 0.0) else PyreonChartRect(x = bx0, y = by0, w = bx1 - bx0, h = by1 - by0)
      val fallback = PyreonChartPt(x = bbox.x + (bbox.w).toDouble() / (2.0).toDouble(), y = bbox.y + (bbox.h).toDouble() / (2.0).toDouble())
      val centroid = if (bestAt < 0) fallback else (ringCentroid(rings[bestAt]) ?: fallback)
      return@map GeoRegion(name = r.name, rings = rings, centroid = centroid, bbox = bbox)
    })
    return GeoLayout(regions = regions, transform = GeoTransform(minX = minX, maxY = maxY, scale = scale, ox = ox, oy = oy, projection = projection))
  }

fun geoRoamZoom(view: GeoView, factor: Double, px: Double, py: Double, box: PyreonChartRect, minZoom: Double, maxZoom: Double): GeoView {
    val lo = if (minZoom > 0.0) minZoom else 0.1
    val hi = if (maxZoom >= lo) maxZoom else lo
    val wanted = view.zoom * factor
    val zoom = if (wanted < lo) lo else if (wanted > hi) hi else wanted
    val k = (zoom).toDouble() / (view.zoom).toDouble()
    val cx = box.x + (box.w).toDouble() / (2.0).toDouble()
    val cy = box.y + (box.h).toDouble() / (2.0).toDouble()
    val panX = (px - cx) - (px - cx - view.panX) * k
    val panY = (py - cy) - (py - cy - view.panY) * k
    return GeoView(zoom = zoom, panX = panX, panY = panY)
  }

fun geoRoamPan(view: GeoView, dx: Double, dy: Double): GeoView = GeoView(zoom = view.zoom, panX = view.panX + dx, panY = view.panY + dy)

fun geoDomain(layout: GeoLayout, values: List<GeoValue>): Domain {
    var lo = 0.0
    var hi = 0.0
    var seen = 0
    for (r in layout.regions) {
      val v = geoValueOf(values, r.name)
      if (!isFiniteNumber(v)) {
        continue
      }
      if (seen == 0) {
        lo = v
        hi = v
      }
      if (v < lo) {
        lo = v
      }
      if (v > hi) {
        hi = v
      }
      seen = seen + 1
    }
    return if (seen == 0) Domain(min = 0.0, max = 0.0) else Domain(min = lo, max = hi)
  }

fun renderGeo(layout: GeoLayout, values: List<GeoValue>, options: GeoOptions? = null, measure: ((String, Double) -> Double)? = null): List<PyreonDrawCmd> {
    val out: MutableList<PyreonDrawCmd> = mutableListOf()
    val stops = (options?.stops ?: HEAT_RAMP)
    val emptyColor = (options?.emptyColor ?: "#e2e8f0")
    val border = (options?.borderColor ?: "#ffffff")
    val borderWidth = (options?.borderWidth ?: 1.0)
    val dom = (options?.domain ?: geoDomain(layout, values))
    val lo = dom.min
    val hi = dom.max
    val span = hi - lo
    val rawP = (options?.progress ?: 1.0)
    val progress = if (rawP < 0.0) 0.0 else if (rawP > 1.0) 1.0 else rawP
    val fontSize = (options?.fontSize ?: 10.0)
    val labelColor = (options?.labelColor ?: "#1e293b")
    val m = (measure ?: ::approxTextWidth)
    for (r in layout.regions) {
      val v = geoValueOf(values, r.name)
      val has = isFiniteNumber(v) && progress > 0.0
      val t = if (!has) 0.0 else if (span <= 0.0) 1.0 else (((v - lo)).toDouble() / (span).toDouble()) * progress
      val fill = if (!has) emptyColor else if (visualOutside(v, options?.inRange, options?.outBands)) (options?.outColor ?: "#cccccc") else rampColor(stops, if (t < 0.0) 0.0 else if (t > 1.0) 1.0 else t)
      for (ring in r.rings) {
        out.add(PyreonDrawCmd(kind = "polygon", fill = fill, points = ring))
      }
    }
    for (r in layout.regions) {
      for (ring in r.rings) {
        val closed: MutableList<PyreonChartPt> = mutableListOf()
        for (p in ring) {
          closed.add(p)
        }
        closed.add(ring[0])
        out.add(PyreonDrawCmd(kind = "polyline", stroke = border, width = borderWidth, points = closed))
      }
    }
    if (options?.showLabels == true && progress >= 1.0) {
      for (r in layout.regions) {
        var hostAt = -1
        for (hri in 0 until r.rings.length) {
          if (pointInRing(r.rings[hri], r.centroid.x, r.centroid.y)) {
            hostAt = hri
          }
        }
        if (hostAt < 0) {
          continue
        }
        val b = ringBox(r.rings[hostAt])
        if (m(r.name, fontSize) > b.w || fontSize > b.h) {
          continue
        }
        out.add(PyreonDrawCmd(kind = "text", fill = labelColor, text = r.name, at = r.centroid, size = fontSize, align = "middle", baseline = "middle"))
      }
    }
    return out
  }

fun ringBox(ring: List<PyreonChartPt>): PyreonChartRect {
    var x0 = 0.0
    var y0 = 0.0
    var x1 = 0.0
    var y1 = 0.0
    var seen = 0
    for (p in ring) {
      if (seen == 0) {
        x0 = p.x
        y0 = p.y
        x1 = p.x
        y1 = p.y
      }
      if (p.x < x0) {
        x0 = p.x
      }
      if (p.y < y0) {
        y0 = p.y
      }
      if (p.x > x1) {
        x1 = p.x
      }
      if (p.y > y1) {
        y1 = p.y
      }
      seen = seen + 1
    }
    return if (seen == 0) PyreonChartRect(x = 0.0, y = 0.0, w = 0.0, h = 0.0) else PyreonChartRect(x = x0, y = y0, w = x1 - x0, h = y1 - y0)
  }

fun pointInRing(ring: List<PyreonChartPt>, px: Double, py: Double): Boolean {
    var inside = false
    for (i in 0 until ring.length) {
      val j = if (i == 0) ring.length - 1 else i - 1
      val a = ring[i]
      val b = ring[j]
      if ((a.y > py) != (b.y > py) && px < (((b.x - a.x) * (py - a.y))).toDouble() / ((b.y - a.y)).toDouble() + a.x) {
        inside = !inside
      }
    }
    return inside
  }

fun hitGeo(layout: GeoLayout, px: Double, py: Double): GeoRegion? {
    val i = hitGeoIndex(layout, px, py)
    return if (i < 0) null else layout.regions[i]
  }

fun hitGeoIndex(layout: GeoLayout, px: Double, py: Double): Int {
    for (i in layout.regions.length - 1 downTo 0) {
      val r = layout.regions[i]
      if (px < r.bbox.x || px > r.bbox.x + r.bbox.w || py < r.bbox.y || py > r.bbox.y + r.bbox.h) {
        continue
      }
      for (ring in r.rings) {
        if (pointInRing(ring, px, py)) {
          return i
        }
      }
    }
    return -1
  }

fun geoOverlayPointRadii(points: List<GeoOverlayPoint>, base: Double): List<Double> {
    var hi = 0.0
    for (p in points) {
      val value = (p.value ?: 0.0)
      if (value > hi) {
        hi = value
      }
    }
    val out: MutableList<Double> = mutableListOf()
    for (p in points) {
      val hasValue = p.value != null
      val value = (p.value ?: 0.0)
      out.add(if (!hasValue || hi <= 0.0) base else base * (0.6 + 1.4 * Math.sqrt(((Math.max(0.0, value)).toDouble() / (hi).toDouble()).toDouble())))
    }
    return out
  }

fun renderGeoOverlayPoints(layout: GeoLayout, points: List<GeoOverlayPoint>, options: GeoOverlayOptions? = null): List<PyreonDrawCmd> {
    val out: MutableList<PyreonDrawCmd> = mutableListOf()
    val base = (options?.radius ?: 5.0)
    val color = (options?.color ?: "#b42318")
    val rawP = (options?.progress ?: 1.0)
    val progress = if (rawP < 0.0) 0.0 else if (rawP > 1.0) 1.0 else rawP
    val fontSize = (options?.fontSize ?: 10.0)
    val labelColor = (options?.labelColor ?: "#1e293b")
    val radii = geoOverlayPointRadii(points, base)
    for (i in 0 until points.length) {
      val p = points[i]
      val at = geoProject(layout.transform, p.lon, p.lat)
      val r = radii[i] * progress
      val fill = (p.color ?: color)
      if (options?.effect == true || p.effect == true) {
        out.add(PyreonDrawCmd(kind = "circle", fill = withAlpha(fill, 0.12), center = at, radius = r * 2.6))
        out.add(PyreonDrawCmd(kind = "circle", fill = withAlpha(fill, 0.25), center = at, radius = r * 1.7))
      }
      out.add(PyreonDrawCmd(kind = "circle", fill = fill, center = at, radius = r))
      if (options?.showLabels == true && progress >= 1.0 && p.name != null) {
        out.add(PyreonDrawCmd(kind = "text", fill = labelColor, text = p.name, at = PyreonChartPt(x = at.x + r + 3.0, y = at.y), size = fontSize, align = "start", baseline = "middle"))
      }
    }
    return out
  }

fun renderGeoOverlayPaths(layout: GeoLayout, paths: List<GeoOverlayPath>, options: GeoOverlayOptions? = null): List<PyreonDrawCmd> {
    val out: MutableList<PyreonDrawCmd> = mutableListOf()
    val color = (options?.color ?: "#b42318")
    val rawP = (options?.progress ?: 1.0)
    val progress = if (rawP < 0.0) 0.0 else if (rawP > 1.0) 1.0 else rawP
    for (path in paths) {
      val pts = path.coords.map({ c -> geoProject(layout.transform, c.lon, c.lat) })
      if (pts.length < 2 || progress <= 0.0) {
        continue
      }
      var length = 0.0
      for (_p in pts) {
        length = length + 1.0
      }
      val visibleCount = if (progress >= 1.0) length else Math.max(2.0, Math.floor(length * progress))
      val visible: MutableList<PyreonChartPt> = mutableListOf()
      var index = 0.0
      for (point in pts) {
        if (index < visibleCount) {
          visible.add(point)
        }
        index = index + 1.0
      }
      out.add(PyreonDrawCmd(kind = "polyline", stroke = (path.color ?: color), width = (path.width ?: 1.5), points = visible))
    }
    return out
  }

fun hitGeoOverlayPoint(layout: GeoLayout, points: List<GeoOverlayPoint>, px: Double, py: Double, base: Double? = null): Int {
    val radii = geoOverlayPointRadii(points, (base ?: 5.0))
    var best = -1
    var bestD = 999999999999.0
    for (i in 0 until points.length) {
      val at = geoProject(layout.transform, points[i].lon, points[i].lat)
      val d = (px - at.x) * (px - at.x) + (py - at.y) * (py - at.y)
      val r = radii[i] + 3.0
      if (d <= r * r && d < bestD) {
        best = i
        bestD = d
      }
    }
    return best
  }

fun renderGeoHeat(layout: GeoLayout, points: List<GeoHeatPoint>, stops: List<String>, radius: Double, progress: Double): List<PyreonDrawCmd> {
    val out: MutableList<PyreonDrawCmd> = mutableListOf()
    var lo = 0.0
    var hi = 0.0
    var seen = 0
    for (p in points) {
      if (seen == 0 || p.value < lo) {
        lo = p.value
      }
      if (seen == 0 || p.value > hi) {
        hi = p.value
      }
      seen = seen + 1
    }
    val span = hi - lo
    val alpha = if (progress < 0.0) 0.0 else if (progress > 1.0) 1.0 else progress
    val ramp = if (stops.length > 0) stops else listOf("#3b82f6", "#facc15", "#ef4444")
    for (p in points) {
      val at = geoProject(layout.transform, p.lon, p.lat)
      val color = rampColor(ramp, if (span > 0.0) ((p.value - lo)).toDouble() / (span).toDouble() else 1.0)
      val ring = arcPolygon(at, radius, 0.0, 0.0, kotlin.math.PI * 2.0)
      out.add(PyreonDrawCmd(kind = "polygon", fill = withAlpha(color, 0.5 * alpha), grad = PyreonChartGradient(from = at, to = PyreonChartPt(x = at.x + radius, y = at.y), stops = listOf(PyreonChartGradientStop(offset = 0.0, color = withAlpha(color, 0.85 * alpha)), PyreonChartGradientStop(offset = 1.0, color = withAlpha(color, 0.0))), radial = true), points = ring))
    }
    return out
  }

fun geoHeatStops(stops: List<String>, fallback: List<String>?): List<String> {
    if (stops.length > 0) {
      return stops
    }
    return (fallback ?: listOf())
  }

fun renderGeoPies(layout: GeoLayout, pies: List<GeoPie>, progress: Double): List<PyreonDrawCmd> {
    val out: MutableList<PyreonDrawCmd> = mutableListOf()
    val t = if (progress < 0.0) 0.0 else if (progress > 1.0) 1.0 else progress
    for (pie in pies) {
      val at = geoProject(layout.transform, pie.lon, pie.lat)
      val inner = pie.radius * (if (pie.innerRadius < 0.0) 0.0 else if (pie.innerRadius > 0.95) 0.95 else pie.innerRadius)
      for (a in layoutArcs(pie.slices)) {
        if (!(a.end > a.start)) {
          continue
        }
        out.add(PyreonDrawCmd(kind = "polygon", fill = a.slice.color, points = arcPolygon(at, pie.radius, inner, a.start * t, a.end * t)))
      }
    }
    return out
  }

fun renderGeoTrails(layout: GeoLayout, paths: List<GeoOverlayPath>, trail: GeoTrail, time: Double, fallbackColor: String): List<PyreonDrawCmd> {
    val out: MutableList<PyreonDrawCmd> = mutableListOf()
    val period = if (trail.period > 0.0) trail.period else 4.0
    val cycles = (time).toDouble() / (period).toDouble()
    val phase = cycles - Math.floor(cycles)
    val share = if (trail.trailLength < 0.0) 0.0 else if (trail.trailLength > 1.0) 1.0 else trail.trailLength
    for (path in paths) {
      val pts = path.coords.map({ c -> geoProject(layout.transform, c.lon, c.lat) })
      if (pts.length < 2) {
        continue
      }
      val total = pathLength(pts)
      if (!(total > 0.0)) {
        continue
      }
      val color = if (trail.color != "") trail.color else (path.color ?: fallbackColor)
      val head = phase * total
      val tail = if (head - share * total > 0.0) head - share * total else 0.0
      if (share > 0.0 && head > tail) {
        out.add(PyreonDrawCmd(kind = "polyline", stroke = withAlpha(color, 0.85), width = ((path.width ?: 1.5)) + 1.0, points = subPath(pts, tail, head)))
      }
      out.add(PyreonDrawCmd(kind = "circle", fill = color, center = pointAlong(pts, head), radius = (trail.symbolSize).toDouble() / (2.0).toDouble()))
    }
    return out
  }

fun renderGeoTrailsIfAny(layout: GeoLayout, paths: List<GeoOverlayPath>, trail: GeoTrail?, time: Double, fallbackColor: String): List<PyreonDrawCmd> {
    val t = (trail ?: GeoTrail(period = 4.0, trailLength = 0.0, color = "", symbolSize = 0.0))
    if (trail == null) {
      return listOf()
    }
    return renderGeoTrails(layout, paths, t, time, fallbackColor)
  }

fun ganttUnitFor(spanDays: Double): String {
    if (spanDays <= 21.0) {
      return "day"
    }
    if (spanDays <= 120.0) {
      return "week"
    }
    if (spanDays <= 730.0) {
      return "month"
    }
    if (spanDays <= 3000.0) {
      return "quarter"
    }
    return "year"
  }

fun ganttUnitDays(unit: String): Double {
    if (unit == "day") {
      return 1.0
    }
    if (unit == "week") {
      return 7.0
    }
    if (unit == "month") {
      return 30.0
    }
    if (unit == "quarter") {
      return 91.0
    }
    return 365.0
  }

fun ganttMonthName(month: Double): String {
    var mi = 0
    var miF = 1.0
    while (miF < month) {
      mi = mi + 1
      miF = miF + 1.0
    }
    return GANTT_MONTHS[mi]
  }

fun ganttAlignStart(lo: Double, unit: String): Double {
    val day = Math.floor(lo)
    val c = civilFromDays(day)
    if (unit == "day") {
      return day
    }
    if (unit == "week") {
      val back = weekdayOfDays(day) + 6.0
      return day - (back - Math.floor((back).toDouble() / (7.0).toDouble()) * 7.0)
    }
    if (unit == "month") {
      return daysFromCivil(c.year, c.month, 1.0)
    }
    if (unit == "quarter") {
      val off = c.month - 1.0
      return daysFromCivil(c.year, c.month - (off - Math.floor((off).toDouble() / (3.0).toDouble()) * 3.0), 1.0)
    }
    return daysFromCivil(c.year, 1.0, 1.0)
  }

fun ganttNextTick(t: Double, unit: String): Double {
    if (unit == "day") {
      return t + 1.0
    }
    if (unit == "week") {
      return t + 7.0
    }
    val c = civilFromDays(t)
    if (unit == "month") {
      return if (c.month >= 12.0) daysFromCivil(c.year + 1.0, 1.0, 1.0) else daysFromCivil(c.year, c.month + 1.0, 1.0)
    }
    if (unit == "quarter") {
      return if (c.month >= 10.0) daysFromCivil(c.year + 1.0, c.month - 9.0, 1.0) else daysFromCivil(c.year, c.month + 3.0, 1.0)
    }
    return daysFromCivil(c.year + 1.0, 1.0, 1.0)
  }

fun ganttTicks(lo: Double, hi: Double, unit: String): List<GanttTick> {
    val out: MutableList<GanttTick> = mutableListOf()
    val sameYear = civilFromDays(Math.floor(lo)).year == civilFromDays(Math.floor(hi)).year
    var t = ganttAlignStart(lo, unit)
    var guard = 0
    while (t <= hi && guard < 400) {
      guard = guard + 1
      if (t >= lo) {
        val c = civilFromDays(t)
        val q = Math.floor(((c.month - 1.0)).toDouble() / (3.0).toDouble()) + 1.0
        val year = "${Math.round((c.year).toDouble())}"
        val label = if (unit == "day" || unit == "week") "${Math.round((c.day).toDouble())} ${ganttMonthName(c.month)}" else if (unit == "month") (if (sameYear) ganttMonthName(c.month) else "${ganttMonthName(c.month)} ${year}") else if (unit == "quarter") "Q${Math.round((q).toDouble())} ${year}" else year
        out.add(GanttTick(at = t, x = 0.0, label = label))
      }
      t = ganttNextTick(t, unit)
    }
    return out
  }

fun ganttRowIndex(rows: List<GanttRow>, id: String): Int {
    var found = -1
    for (i in 0 until rows.length) {
      if (found < 0 && rows[i].task.id == id) {
        found = i
      }
    }
    return found
  }

fun layoutGantt(tasks: List<GanttTask>, box: PyreonChartRect, options: GanttOptions? = null, measure: ((String, Double) -> Double)? = null): GanttLayout {
    val fontSize = (options?.fontSize ?: 12.0)
    val m = (measure ?: ::approxTextWidth)
    val palette = (options?.palette ?: DEFAULT_PALETTE)
    val sDay: MutableList<Double> = mutableListOf()
    val eDay: MutableList<Double> = mutableListOf()
    for (task in tasks) {
      val ps = parseIsoDays(task.start)
      val s = if (ps.ok) ps.days else 0.0
      val pe = parseIsoDays((task.end ?: ""))
      val eRaw = if (pe.ok) pe.days else s
      val e = if (task.milestone == true) s else if (eRaw < s) s else eRaw
      sDay.add(s)
      eDay.add(e)
    }
    var lo = 0.0
    var hi = 0.0
    var seen = false
    for (i in 0 until sDay.length) {
      if (!seen || sDay[i] < lo) {
        lo = sDay[i]
      }
      if (!seen || eDay[i] > hi) {
        hi = eDay[i]
      }
      seen = true
    }
    if (!seen) {
      lo = daysFromCivil(2024.0, 1.0, 1.0)
      hi = lo + 30.0
    }
    if (hi <= lo) {
      hi = lo + 1.0
    }
    val pToday = parseIsoDays((options?.today ?: ""))
    val hasToday = pToday.ok
    val todayDay = pToday.days
    if (hasToday) {
      if (todayDay < lo) {
        lo = todayDay
      }
      if (todayDay > hi) {
        hi = todayDay
      }
    }
    val pA = parseIsoDays((options?.domain?.start ?: ""))
    val pB = parseIsoDays((options?.domain?.end ?: ""))
    val explicit = pA.ok && pB.ok && pB.days > pA.days
    if (explicit) {
      lo = pA.days
      hi = pB.days
    } else {
      val pad = ganttUnitDays(ganttUnitFor(hi - lo)) * 0.25
      lo = lo - pad
      hi = hi + pad
    }
    val unit = ganttUnitFor(hi - lo)
    var labelW = 0.0
    for (task in tasks) {
      val w = m(task.name, fontSize)
      if (w > labelW) {
        labelW = w
      }
    }
    val groups: MutableList<String> = mutableListOf()
    for (task in tasks) {
      val g = (task.group ?: "")
      if (g == "") {
        continue
      }
      var known = false
      for (k in groups) {
        if (k == g) {
          known = true
        }
      }
      if (!known) {
        groups.add(g)
      }
    }
    for (g in groups) {
      val w = m(g, fontSize + 1.0)
      if (w > labelW) {
        labelW = w
      }
    }
    val cap = box.w * ((options?.labelFraction ?: 0.35))
    val labelCol = if (labelW + 16.0 < cap) labelW + 16.0 else cap
    val axisH = fontSize + 12.0
    val axisW = box.w - labelCol
    val axis = PyreonChartRect(x = box.x + labelCol, y = box.y, w = if (axisW < 0.0) 0.0 else axisW, h = axisH)
    var lineCount = 0.0
    var lastGroup = ""
    for (task in tasks) {
      val g = (task.group ?: "")
      if (g != "" && g != lastGroup) {
        lineCount = lineCount + 1.0
        lastGroup = g
      }
      lineCount = lineCount + 1.0
    }
    val availRaw = box.h - axisH
    val avail = if (availRaw < 0.0) 0.0 else availRaw
    val fitRow = if (lineCount <= 0.0) 28.0 else (avail).toDouble() / (lineCount).toDouble()
    val clampedRow = if (fitRow < 12.0) 12.0 else if (fitRow > 28.0) 28.0 else fitRow
    val rowHeight = (options?.rowHeight ?: clampedRow)
    val plotH = rowHeight * lineCount
    val plot = PyreonChartRect(x = axis.x, y = box.y + axisH, w = axis.w, h = if (avail > plotH) avail else plotH)
    val span = hi - lo
    val rows: MutableList<GanttRow> = mutableListOf()
    val lanes: MutableList<GanttLane> = mutableListOf()
    var y = plot.y
    var laneGroup = ""
    val labelX = box.x + (if (groups.length > 0) 14.0 else 4.0)
    for (i in 0 until tasks.length) {
      val task = tasks[i]
      val g = (task.group ?: "")
      if (g != "" && g != laneGroup) {
        lanes.add(GanttLane(text = g, at = PyreonChartPt(x = box.x + 4.0, y = y + (rowHeight).toDouble() / (2.0).toDouble()), band = PyreonChartRect(x = box.x, y = y, w = box.w, h = rowHeight)))
        y = y + rowHeight
        laneGroup = g
      }
      val x0 = plot.x + (((sDay[i] - lo)).toDouble() / (span).toDouble()) * plot.w
      val x1 = plot.x + (((eDay[i] - lo)).toDouble() / (span).toDouble()) * plot.w
      val barRaw = rowHeight * 0.6
      val barH = if (barRaw < 4.0) 4.0 else barRaw
      val isMilestone = task.milestone == true || eDay[i] == sDay[i]
      val bw = if (x1 - x0 < 1.0) 1.0 else x1 - x0
      val rect = if (isMilestone) PyreonChartRect(x = x0 - (barH).toDouble() / (2.0).toDouble(), y = y + ((rowHeight - barH)).toDouble() / (2.0).toDouble(), w = barH, h = barH) else PyreonChartRect(x = x0, y = y + ((rowHeight - barH)).toDouble() / (2.0).toDouble(), w = bw, h = barH)
      rows.add(GanttRow(task = task, index = i, rect = rect, band = PyreonChartRect(x = box.x, y = y, w = box.w, h = rowHeight), startDay = sDay[i], endDay = eDay[i], color = (task.color ?: palette[i % palette.length]), label = task.name, labelAt = PyreonChartPt(x = labelX, y = y + (rowHeight).toDouble() / (2.0).toDouble())))
      y = y + rowHeight
    }
    val dependencies: MutableList<GanttDependency> = mutableListOf()
    for (row in rows) {
      val deps = (row.task.dependencies ?: listOf())
      for (dep in deps) {
        val fi = ganttRowIndex(rows, dep)
        if (fi < 0) {
          continue
        }
        val from = rows[fi]
        val fx = from.rect.x + from.rect.w
        val fy = from.rect.y + (from.rect.h).toDouble() / (2.0).toDouble()
        val tx = row.rect.x
        val ty = row.rect.y + (row.rect.h).toDouble() / (2.0).toDouble()
        val points: MutableList<PyreonChartPt> = mutableListOf()
        points.add(PyreonChartPt(x = fx, y = fy))
        if (fx + 8.0 <= tx) {
          points.add(PyreonChartPt(x = fx + 8.0, y = fy))
          points.add(PyreonChartPt(x = fx + 8.0, y = ty))
        } else {
          val above = ty - (row.rect.h).toDouble() / (2.0).toDouble() - 2.0
          points.add(PyreonChartPt(x = fx + 8.0, y = fy))
          points.add(PyreonChartPt(x = fx + 8.0, y = above))
          points.add(PyreonChartPt(x = tx - 8.0, y = above))
          points.add(PyreonChartPt(x = tx - 8.0, y = ty))
        }
        points.add(PyreonChartPt(x = tx, y = ty))
        dependencies.add(GanttDependency(from = dep, to = row.task.id, points = points))
      }
    }
    val ticks: MutableList<GanttTick> = mutableListOf()
    for (t in ganttTicks(lo, hi, unit)) {
      ticks.add(GanttTick(at = t.at, x = plot.x + (((t.at - lo)).toDouble() / (span).toDouble()) * plot.w, label = t.label))
    }
    return GanttLayout(rows = rows, lanes = lanes, dependencies = dependencies, ticks = ticks, unit = unit, axis = axis, plot = plot, domain = Domain(min = lo, max = hi), hasToday = hasToday, todayX = if (hasToday) plot.x + (((todayDay - lo)).toDouble() / (span).toDouble()) * plot.w else 0.0, rowHeight = rowHeight)
  }

fun renderGantt(layout: GanttLayout, options: GanttOptions? = null): List<PyreonDrawCmd> {
    val out: MutableList<PyreonDrawCmd> = mutableListOf()
    val fontSize = (options?.fontSize ?: 12.0)
    val labelColor = (options?.labelColor ?: "#374151")
    val gridColor = (options?.gridColor ?: "#e5e7eb")
    val laneColor = (options?.laneColor ?: "#f3f4f6")
    val rawP = (options?.progress ?: 1.0)
    val progress = if (rawP < 0.0) 0.0 else if (rawP > 1.0) 1.0 else rawP
    val showDeps = (options?.showDependencies ?: true)
    for (lane in layout.lanes) {
      out.add(PyreonDrawCmd(kind = "rect", rect = lane.band, fill = laneColor))
      out.add(PyreonDrawCmd(kind = "text", fill = labelColor, text = lane.text, at = lane.at, size = fontSize + 1.0, align = "start", baseline = "middle"))
    }
    val plotBottom = layout.plot.y + layout.plot.h
    for (t in layout.ticks) {
      out.add(PyreonDrawCmd(kind = "line", from = PyreonChartPt(x = t.x, y = layout.axis.y + layout.axis.h), to = PyreonChartPt(x = t.x, y = plotBottom), stroke = gridColor, width = 1.0))
      out.add(PyreonDrawCmd(kind = "text", fill = labelColor, text = t.label, at = PyreonChartPt(x = t.x + 3.0, y = layout.axis.y + (layout.axis.h).toDouble() / (2.0).toDouble()), size = fontSize - 1.0, align = "start", baseline = "middle"))
    }
    for (row in layout.rows) {
      out.add(PyreonDrawCmd(kind = "text", fill = labelColor, text = row.label, at = row.labelAt, size = fontSize, align = "start", baseline = "middle"))
      val r = row.rect
      if (row.task.milestone == true || row.endDay == row.startDay) {
        val cx = r.x + (r.w).toDouble() / (2.0).toDouble()
        val cy = r.y + (r.h).toDouble() / (2.0).toDouble()
        val hw = ((r.w).toDouble() / (2.0).toDouble()) * progress
        val diamond: MutableList<PyreonChartPt> = mutableListOf()
        diamond.add(PyreonChartPt(x = cx, y = cy - hw))
        diamond.add(PyreonChartPt(x = cx + hw, y = cy))
        diamond.add(PyreonChartPt(x = cx, y = cy + hw))
        diamond.add(PyreonChartPt(x = cx - hw, y = cy))
        out.add(PyreonDrawCmd(kind = "polygon", fill = row.color, points = diamond))
        continue
      }
      val w = r.w * progress
      out.add(PyreonDrawCmd(kind = "rect", rect = PyreonChartRect(x = r.x, y = r.y, w = w, h = r.h), fill = row.color))
      val done = (row.task.progress ?: 0.0)
      if (done > 0.0) {
        val dw = w * (if (done > 1.0) 1.0 else done)
        out.add(PyreonDrawCmd(kind = "rect", rect = PyreonChartRect(x = r.x, y = r.y + r.h * 0.25, w = dw, h = r.h * 0.5), fill = "rgba(0,0,0,0.35)"))
      }
    }
    if (progress >= 1.0 && showDeps) {
      for (d in layout.dependencies) {
        out.add(PyreonDrawCmd(kind = "polyline", stroke = "#6b7280", width = 1.0, points = d.points))
      }
    }
    if (layout.hasToday) {
      out.add(PyreonDrawCmd(kind = "line", from = PyreonChartPt(x = layout.todayX, y = layout.axis.y), to = PyreonChartPt(x = layout.todayX, y = plotBottom), stroke = (options?.todayColor ?: "#dc2626"), width = 1.5, dash = listOf(4.0, 3.0)))
    }
    return out
  }

fun hitGanttIndex(layout: GanttLayout, px: Double, py: Double): Int {
    var hit = -1
    for (i in 0 until layout.rows.length) {
      if (hit >= 0) {
        continue
      }
      val r = layout.rows[i].rect
      if (px >= r.x && px <= r.x + r.w && py >= r.y && py <= r.y + r.h) {
        hit = i
      }
    }
    if (hit >= 0) {
      return hit
    }
    for (i in 0 until layout.rows.length) {
      if (hit >= 0) {
        continue
      }
      val b = layout.rows[i].band
      if (px >= layout.plot.x && py >= b.y && py <= b.y + b.h) {
        hit = i
      }
    }
    return hit
  }

fun ganttDurationDays(row: GanttRow): Double {
    val raw = row.endDay - row.startDay
    val f = Math.floor(raw)
    return if (raw - f < 0.5) f else f + 1.0
  }

fun parallelPlace(axis: ParallelLayoutAxis, v: Double): ParallelPlaced {
    if (!isFiniteNumber(v)) {
      return ParallelPlaced(ok = false, y = 0.0)
    }
    val lo = axis.domain.min
    val span = axis.domain.max - lo
    if (axis.isCategory && (v < 0.0 || v > axis.domain.max)) {
      return ParallelPlaced(ok = false, y = 0.0)
    }
    val raw = if (axis.isCategory) (if (span <= 0.0) 0.5 else (v).toDouble() / (span).toDouble()) else if (span <= 0.0) 0.5 else ((v - lo)).toDouble() / (span).toDouble()
    val t = if (raw < 0.0) 0.0 else if (raw > 1.0) 1.0 else raw
    val y = if (axis.inverse) axis.y0 + (axis.y1 - axis.y0) * t else axis.y1 - (axis.y1 - axis.y0) * t
    return ParallelPlaced(ok = true, y = y)
  }

fun parallelHighlighted(highlight: List<Double>, index: Double): Boolean {
    var found = false
    for (h in highlight) {
      if (h == index) {
        found = true
      }
    }
    return found
  }

fun layoutParallel(axes: List<ParallelAxis>, rows: List<List<Double>>, box: PyreonChartRect, options: ParallelOptions? = null): ParallelLayout {
    val fontSize = (options?.fontSize ?: 11.0)
    val top = box.y + fontSize * 1.8
    val bottom = box.y + box.h - fontSize * 1.4
    val n = axes.length
    var nF = 0.0
    for (i in 0 until n) {
      nF = nF + 1.0
    }
    val outAxes: MutableList<ParallelLayoutAxis> = mutableListOf()
    var aF = 0.0
    for (a in 0 until n) {
      val axis = axes[a]
      val x = if (n <= 1) box.x + (box.w).toDouble() / (2.0).toDouble() else box.x + ((box.w * aF)).toDouble() / ((nF - 1.0)).toDouble()
      val isCat = axis.type == "category"
      val cats = (axis.categories ?: listOf())
      val dMin = (axis.domain?.min ?: 0.0)
      val dMax = (axis.domain?.max ?: -1.0)
      val hasDomain = dMax >= dMin
      var lo = 0.0
      var hi = 0.0
      if (isCat) {
        var catsF = 0.0
        for (i in 0 until cats.length) {
          catsF = catsF + 1.0
        }
        hi = if (catsF > 1.0) catsF - 1.0 else 0.0
      } else {
        if (hasDomain) {
          lo = dMin
          hi = dMax
        } else {
          var seen = false
          for (r in rows) {
            if (a >= r.length) {
              continue
            }
            val v = r[a]
            if (!isFiniteNumber(v)) {
              continue
            }
            if (!seen || v < lo) {
              lo = v
            }
            if (!seen || v > hi) {
              hi = v
            }
            seen = true
          }
          if (!seen) {
            hi = 1.0
          }
        }
      }
      val inverse = axis.inverse == true
      val resolved = ParallelLayoutAxis(name = axis.name, x = x, y0 = top, y1 = bottom, domain = Domain(min = lo, max = hi), ticks = listOf(), isCategory = isCat, inverse = inverse)
      val ticks: MutableList<ParallelTick> = mutableListOf()
      if (isCat) {
        var iF = 0.0
        for (i in 0 until cats.length) {
          ticks.add(ParallelTick(y = parallelPlace(resolved, iF).y, label = cats[i]))
          iF = iF + 1.0
        }
      } else {
        ticks.add(ParallelTick(y = if (inverse) top else bottom, label = plain(lo)))
        ticks.add(ParallelTick(y = if (inverse) bottom else top, label = plain(hi)))
      }
      outAxes.add(ParallelLayoutAxis(name = axis.name, x = x, y0 = top, y1 = bottom, domain = Domain(min = lo, max = hi), ticks = ticks, isCategory = isCat, inverse = inverse))
      aF = aF + 1.0
    }
    val lines: MutableList<ParallelLine> = mutableListOf()
    val colors = (options?.lineColors ?: listOf())
    val fallback = (options?.lineColor ?: paletteAt((options?.palette ?: DEFAULT_PALETTE), 0))
    for (i in 0 until rows.length) {
      val row = rows[i]
      val points: MutableList<PyreonChartPt> = mutableListOf()
      val present: MutableList<Boolean> = mutableListOf()
      for (a in 0 until n) {
        val v = if (a < row.length) row[a] else (0.0).toDouble() / (0.0).toDouble()
        val placed = parallelPlace(outAxes[a], v)
        points.add(PyreonChartPt(x = outAxes[a].x, y = placed.y))
        present.add(placed.ok)
      }
      val color = if (i < colors.length) colors[i] else fallback
      lines.add(ParallelLine(index = i, points = points, present = present, color = color))
    }
    return ParallelLayout(axes = outAxes, lines = lines)
  }

fun renderParallel(layout: ParallelLayout, options: ParallelOptions? = null): List<PyreonDrawCmd> {
    val out: MutableList<PyreonDrawCmd> = mutableListOf()
    val opacity = (options?.lineOpacity ?: 0.45)
    val width = (options?.lineWidth ?: 1.0)
    val rawP = (options?.progress ?: 1.0)
    val progress = if (rawP < 0.0) 0.0 else if (rawP > 1.0) 1.0 else rawP
    val n = layout.axes.length
    var nF = 0.0
    for (i in 0 until n) {
      nF = nF + 1.0
    }
    val shown = if (progress >= 1.0) nF else Math.floor(nF * progress)
    val highlight = (options?.highlight ?: listOf())
    val highlightColor = (options?.highlightColor ?: "#b42318")
    val fontSize = (options?.fontSize ?: 11.0)
    val labelColor = (options?.labelColor ?: "#334155")
    val axisColor = (options?.axisColor ?: "#94a3b8")
    for (pass in 0 until 2) {
      var lineF = 0.0
      for (line in layout.lines) {
        val isHl = parallelHighlighted(highlight, lineF)
        lineF = lineF + 1.0
        if ((pass == 1) != isHl) {
          continue
        }
        val stroke = if (isHl) highlightColor else sankeyRgba(line.color, opacity)
        val w = if (isHl) width + 1.0 else width
        var runStart = -1
        var iF = 0.0
        for (i in 0 until line.points.length) {
          val visible = iF < shown && line.present[i]
          if (visible && runStart < 0) {
            runStart = i
          }
          if (!visible && runStart >= 0) {
            if (i - runStart >= 2) {
              val run: MutableList<PyreonChartPt> = mutableListOf()
              for (k in runStart until i) {
                run.add(line.points[k])
              }
              out.add(PyreonDrawCmd(kind = "polyline", stroke = stroke, width = w, points = run))
            }
            runStart = -1
          }
          iF = iF + 1.0
        }
        if (runStart >= 0 && line.points.length - runStart >= 2) {
          val run: MutableList<PyreonChartPt> = mutableListOf()
          for (k in runStart until line.points.length) {
            run.add(line.points[k])
          }
          out.add(PyreonDrawCmd(kind = "polyline", stroke = stroke, width = w, points = run))
        }
      }
    }
    for (axis in layout.axes) {
      out.add(PyreonDrawCmd(kind = "line", from = PyreonChartPt(x = axis.x, y = axis.y0), to = PyreonChartPt(x = axis.x, y = axis.y1), stroke = axisColor, width = 1.0))
      if (progress < 1.0) {
        continue
      }
      out.add(PyreonDrawCmd(kind = "text", fill = labelColor, text = axis.name, at = PyreonChartPt(x = axis.x, y = axis.y0 - fontSize * 0.5), size = fontSize, align = "middle", baseline = "bottom"))
      for (t in axis.ticks) {
        out.add(PyreonDrawCmd(kind = "line", from = PyreonChartPt(x = axis.x - 3.0, y = t.y), to = PyreonChartPt(x = axis.x + 3.0, y = t.y), stroke = axisColor, width = 1.0))
        out.add(PyreonDrawCmd(kind = "text", fill = labelColor, text = t.label, at = PyreonChartPt(x = axis.x + 5.0, y = t.y), size = fontSize * 0.9, align = "start", baseline = "middle"))
      }
    }
    return out
  }

fun parallelSegmentDistance(px: Double, py: Double, a: PyreonChartPt, b: PyreonChartPt): Double {
    val dx = b.x - a.x
    val dy = b.y - a.y
    val len2 = dx * dx + dy * dy
    val rawT = if (len2 <= 0.0) 0.0 else (((px - a.x) * dx + (py - a.y) * dy)).toDouble() / (len2).toDouble()
    val t = if (rawT < 0.0) 0.0 else if (rawT > 1.0) 1.0 else rawT
    val qx = a.x + dx * t
    val qy = a.y + dy * t
    return Math.sqrt(((px - qx) * (px - qx) + (py - qy) * (py - qy)).toDouble())
  }

fun hitParallelIndex(layout: ParallelLayout, px: Double, py: Double, tolerance: Double? = null): Int {
    val tol = (tolerance ?: 4.0)
    var best = -1
    var bestD = tol
    for (k in 0 until layout.lines.length) {
      val line = layout.lines[k]
      for (i in 1 until line.points.length) {
        if (!line.present[i - 1] || !line.present[i]) {
          continue
        }
        val d = parallelSegmentDistance(px, py, line.points[i - 1], line.points[i])
        if (d <= bestD) {
          best = k
          bestD = d
        }
      }
    }
    return best
  }

fun niceTicks(lo: Double, hi: Double, count: Int): List<Double> {
    if (hi <= lo) {
      return listOf(lo)
    }
    val raw = ((hi - lo)).toDouble() / (count).toDouble()
    val mag = Math.pow((10.0).toDouble(), (Math.floor(Math.log10((raw).toDouble()))).toDouble())
    val norm = (raw).toDouble() / (mag).toDouble()
    val step = (if (norm >= 5.0) 5.0 else if (norm >= 2.0) 2.0 else 1.0) * mag
    val out: MutableList<Double> = mutableListOf()
    var v = Math.ceil((lo).toDouble() / (step).toDouble()) * step
    while (v <= hi + 1e-9) {
      out.add((Math.round(v * 1000000.0)).toDouble() / (1000000.0).toDouble())
      v = v + step
    }
    return out
  }

fun layoutSingleAxis(axis: SingleAxisSpec, points: List<SingleAxisPoint>, box: PyreonChartRect, options: SingleAxisOptions? = null): SingleAxisLayout {
    val fontSize = (options?.fontSize ?: 11.0)
    val base = (options?.radius ?: 5.0)
    val isCat = axis.type == "category"
    val gutter = fontSize * 2.0
    val x0 = box.x + gutter
    val x1 = box.x + box.w - gutter
    val y = box.y + (box.h).toDouble() / (2.0).toDouble()
    var lo: Double
    var hi: Double
    if (isCat) {
      lo = 0.0
      hi = Math.max(0.0, ((axis.categories ?: listOf())).length * 1.0 - 1.0)
    } else {
      if (axis.domain != null) {
        val domain = (axis.domain ?: Domain(min = 0.0, max = 1.0))
        lo = domain.min
        hi = domain.max
      } else {
        lo = 999999999999999.0
        hi = -999999999999999.0
        for (p in points) {
          if (p.x < lo) {
            lo = p.x
          }
          if (p.x > hi) {
            hi = p.x
          }
        }
        if (lo == 999999999999999.0) {
          lo = 0.0
          hi = 1.0
        }
      }
    }
    val span = hi - lo
    val px = { v: Double -> (if (span <= 0.0) ((x0 + x1)).toDouble() / (2.0).toDouble() else x0 + (((v - lo)).toDouble() / (span).toDouble()) * (x1 - x0)) }
    val ticks: MutableList<SingleAxisTick> = mutableListOf()
    if (isCat) {
      val cats = (axis.categories ?: listOf())
      for (i in 0 until cats.length) {
        ticks.add(SingleAxisTick(x = px(i * 1.0), label = cats[i], index = i))
      }
    } else {
      var index = 0
      for (v in niceTicks(lo, hi, 6)) {
        ticks.add(SingleAxisTick(x = px(v), label = (v).toString(), index = index))
        index += 1
      }
    }
    var maxSize = 0.0
    for (p in points) {
      val pointSize = (p.size ?: 0.0)
      if (pointSize > maxSize) {
        maxSize = pointSize
      }
    }
    val color = (options?.color ?: "#0f766e")
    val laid: MutableList<SingleAxisLayoutPoint> = mutableListOf()
    for (i in 0 until points.length) {
      val p = points[i]
      val pointSize = (p.size ?: 0.0)
      val hasSize = p.size != null
      laid.add(SingleAxisLayoutPoint(index = i, at = PyreonChartPt(x = px(p.x), y = y), radius = if (!hasSize || maxSize <= 0.0) base else base * (0.6 + 1.4 * Math.sqrt(((Math.max(0.0, pointSize)).toDouble() / (maxSize).toDouble()).toDouble())), color = (p.color ?: color), name = p.name))
    }
    return SingleAxisLayout(axis = SingleAxisLayoutAxis(y = y, x0 = x0, x1 = x1, ticks = ticks, name = axis.name), points = laid)
  }

fun renderSingleAxis(layout: SingleAxisLayout, options: SingleAxisOptions? = null): List<PyreonDrawCmd> {
    val out: MutableList<PyreonDrawCmd> = mutableListOf()
    val fontSize = (options?.fontSize ?: 11.0)
    val axisColor = (options?.axisColor ?: "#94a3b8")
    val labelColor = (options?.labelColor ?: "#334155")
    val rawP = (options?.progress ?: 1.0)
    val progress = if (rawP < 0.0) 0.0 else if (rawP > 1.0) 1.0 else rawP
    val a = layout.axis
    out.add(PyreonDrawCmd(kind = "line", from = PyreonChartPt(x = a.x0, y = a.y), to = PyreonChartPt(x = a.x1, y = a.y), stroke = axisColor, width = 1.0))
    for (t in a.ticks) {
      out.add(PyreonDrawCmd(kind = "line", from = PyreonChartPt(x = t.x, y = a.y), to = PyreonChartPt(x = t.x, y = a.y + 4.0), stroke = axisColor, width = 1.0))
      out.add(PyreonDrawCmd(kind = "text", fill = labelColor, text = t.label, at = PyreonChartPt(x = t.x, y = a.y + 8.0), size = fontSize, align = "middle", baseline = "top"))
    }
    if (a.name != null) {
      out.add(PyreonDrawCmd(kind = "text", fill = labelColor, text = a.name, at = PyreonChartPt(x = a.x1, y = a.y + fontSize * 2.2), size = fontSize, align = "end", baseline = "top"))
    }
    for (p in layout.points) {
      out.add(PyreonDrawCmd(kind = "circle", fill = p.color, center = p.at, radius = p.radius * progress))
      if (options?.showLabels == true && progress >= 1.0 && p.name != null) {
        out.add(PyreonDrawCmd(kind = "text", fill = labelColor, text = p.name, at = PyreonChartPt(x = p.at.x, y = p.at.y - p.radius - 4.0), size = fontSize, align = "middle", baseline = "bottom"))
      }
    }
    return out
  }

fun hitSingleAxis(layout: SingleAxisLayout, px: Double, py: Double): Int {
    var best = -1
    var bestD = 999999999999999.0
    for (p in layout.points) {
      val d = (px - p.at.x) * (px - p.at.x) + (py - p.at.y) * (py - p.at.y)
      val r = p.radius + 3.0
      if (d <= r * r && d < bestD) {
        best = p.index
        bestD = d
      }
    }
    return best
  }

fun candlestickFrame(candles: List<Ohlc>, w: Double, h: Double, categories: List<String>, fontSize: Double, measure: (String, Double) -> Double): CandlestickFrame {
    val domain = niceDomain(ohlcExtent(candles), 5.0)
    val n = candles.length
    val cfg = LayoutConfig(width = w, height = h, xDomain = Domain(min = 0.0, max = if (n > 1) (n - 1).toDouble() else 1.0), yDomain = domain, categories = categories, fontSize = fontSize, xTickCount = 5.0, yTickCount = 5.0, showXAxis = true, showYAxis = true)
    val layout = computeLayout(cfg, measure)
    return CandlestickFrame(candles = candles, domain = domain, layout = layout)
  }

fun renderCandlestickChart(candles: List<Ohlc>, w: Double, h: Double, categories: List<String>, theme: ChartTheme, options: CandleOptions?, measure: (String, Double) -> Double): List<PyreonDrawCmd> {
    val f = candlestickFrame(candles, w, h, categories, theme.fontSize, measure)
    val l = f.layout
    val cmds: MutableList<PyreonDrawCmd> = mutableListOf()
    for (tick in l.yTicks) {
      cmds.add(PyreonDrawCmd(kind = "line", from = PyreonChartPt(x = l.plot.x, y = tick.pos), to = PyreonChartPt(x = l.plot.x + l.plot.w, y = tick.pos), stroke = theme.grid, width = 1.0))
      cmds.add(PyreonDrawCmd(kind = "text", fill = theme.label, text = tick.label, at = PyreonChartPt(x = l.plot.x - 6.0, y = tick.pos), size = theme.fontSize, align = "end", baseline = "middle"))
    }
    for (tick in l.xTicks) {
      cmds.add(PyreonDrawCmd(kind = "text", fill = theme.label, text = tick.label, at = PyreonChartPt(x = tick.pos, y = l.plot.y + l.plot.h + 6.0), size = theme.fontSize, align = "middle", baseline = "top"))
    }
    val body = renderCandles(candles, l.plot, f.domain, CandleOptions(upColor = (options?.upColor ?: theme.positive), downColor = (options?.downColor ?: theme.negative), widthRatio = options?.widthRatio))
    for (c in body) {
      cmds.add(c)
    }
    return cmds
  }

fun hitCandlestickChart(candles: List<Ohlc>, w: Double, h: Double, categories: List<String>, fontSize: Double, measure: (String, Double) -> Double, px: Double, py: Double): Int {
    val f = candlestickFrame(candles, w, h, categories, fontSize, measure)
    return hitCandle(candles.length, f.layout.plot, px, py)
  }

fun fiveNumber(values: List<Double>): FiveNumber {
    val sorted: MutableList<Double> = mutableListOf()
    for (v in values) {
      if (isFiniteNumber(v)) {
        sorted.add(v)
      }
    }
    sorted.sortedWith(Comparator { a, b -> (a - b).compareTo(0.0) })
    val n = sorted.length
    if (n == 0) {
      return FiveNumber(min = 0.0, q1 = 0.0, median = 0.0, q3 = 0.0, max = 0.0, outliers = listOf())
    }
    val at = fun(p: Double): Double {
      val pos = p * (n - 1.0)
      var lo = 0
      var jf = 1.0
      for (k in 1 until n) {
        if (jf <= pos) {
          lo = k
        }
        jf = jf + 1.0
      }
      val hi = if (lo + 1 < n) lo + 1 else lo
      var loF = 0.0
      for (k in 0 until lo) {
        loF = loF + 1.0
      }
      val frac = pos - loF
      return sorted[lo] + (sorted[hi] - sorted[lo]) * frac
    }
    val q1 = at(0.25)
    val median = at(0.5)
    val q3 = at(0.75)
    val iqr = q3 - q1
    val loFence = q1 - 1.5 * iqr
    val hiFence = q3 + 1.5 * iqr
    var min = sorted[0]
    var max = sorted[n - 1]
    val outliers: MutableList<Double> = mutableListOf()
    var minSet = false
    var maxSet = false
    for (v in sorted) {
      if (v < loFence || v > hiFence) {
        outliers.add(v)
      } else {
        if (!minSet) {
          min = v
          minSet = true
        }
        max = v
        maxSet = true
      }
    }
    if (!minSet) {
      min = q1
    }
    if (!maxSet) {
      max = q3
    }
    return FiveNumber(min = min, q1 = q1, median = median, q3 = q3, max = max, outliers = outliers)
  }

fun boxplotExtent(rows: List<FiveNumber>): Domain {
    if (rows.length == 0) {
      return Domain(min = 0.0, max = 1.0)
    }
    var lo = rows[0].min
    var hi = rows[0].max
    for (r in rows) {
      if (r.min < lo) {
        lo = r.min
      }
      if (r.max > hi) {
        hi = r.max
      }
      for (o in r.outliers) {
        if (o < lo) {
          lo = o
        }
        if (o > hi) {
          hi = o
        }
      }
    }
    if (hi <= lo) {
      return Domain(min = lo - 1.0, max = lo + 1.0)
    }
    return Domain(min = lo, max = hi)
  }

fun renderBoxplot(rows: List<FiveNumber>, plot: PyreonChartRect, domain: Domain, options: BoxplotOptions? = null): List<PyreonDrawCmd> {
    val out: MutableList<PyreonDrawCmd> = mutableListOf()
    val n = rows.length
    if (n == 0) {
      return out
    }
    val fill = (options?.fill ?: "rgba(99,102,241,0.35)")
    val stroke = (options?.stroke ?: "#4649c8")
    val rawRatio = (options?.widthRatio ?: 0.5)
    val ratio = if (rawRatio < 0.05) 0.05 else if (rawRatio > 0.9) 0.9 else rawRatio
    val radius = (options?.outlierRadius ?: 3.0)
    val rawP = (options?.progress ?: 1.0)
    val progress = if (rawP < 0.0) 0.0 else if (rawP > 1.0) 1.0 else rawP
    val band = (plot.w).toDouble() / (n).toDouble()
    val bw = band * ratio
    val yOf = { v: Double -> scaleLinear(domain, plot.y + plot.h, plot.y, v) }
    for (i in 0 until n) {
      val r = rows[i]
      val cx = plot.x + band * i + (band).toDouble() / (2.0).toDouble()
      val yMed = yOf(r.median)
      val grow = { y: Double -> yMed + (y - yMed) * progress }
      val yQ1 = grow(yOf(r.q1))
      val yQ3 = grow(yOf(r.q3))
      val yMin = grow(yOf(r.min))
      val yMax = grow(yOf(r.max))
      out.add(PyreonDrawCmd(kind = "line", from = PyreonChartPt(x = cx, y = yMax), to = PyreonChartPt(x = cx, y = yQ3), stroke = stroke, width = 1.0))
      out.add(PyreonDrawCmd(kind = "line", from = PyreonChartPt(x = cx, y = yQ1), to = PyreonChartPt(x = cx, y = yMin), stroke = stroke, width = 1.0))
      out.add(PyreonDrawCmd(kind = "line", from = PyreonChartPt(x = cx - (bw).toDouble() / (4.0).toDouble(), y = yMax), to = PyreonChartPt(x = cx + (bw).toDouble() / (4.0).toDouble(), y = yMax), stroke = stroke, width = 1.0))
      out.add(PyreonDrawCmd(kind = "line", from = PyreonChartPt(x = cx - (bw).toDouble() / (4.0).toDouble(), y = yMin), to = PyreonChartPt(x = cx + (bw).toDouble() / (4.0).toDouble(), y = yMin), stroke = stroke, width = 1.0))
      val top = if (yQ3 < yQ1) yQ3 else yQ1
      val h = if (yQ1 > yQ3) yQ1 - yQ3 else yQ3 - yQ1
      out.add(PyreonDrawCmd(kind = "rect", rect = PyreonChartRect(x = cx - (bw).toDouble() / (2.0).toDouble(), y = top, w = bw, h = if (h < 1.0) 1.0 else h), fill = fill))
      out.add(PyreonDrawCmd(kind = "line", from = PyreonChartPt(x = cx - (bw).toDouble() / (2.0).toDouble(), y = yMed), to = PyreonChartPt(x = cx + (bw).toDouble() / (2.0).toDouble(), y = yMed), stroke = stroke, width = 2.0))
      if (progress >= 1.0) {
        for (o in r.outliers) {
          out.add(PyreonDrawCmd(kind = "circle", fill = stroke, center = PyreonChartPt(x = cx, y = yOf(o)), radius = radius))
        }
      }
    }
    return out
  }

fun hitBox(count: Int, plot: PyreonChartRect, px: Double, py: Double): Int {
    if (count == 0 || px < plot.x || px > plot.x + plot.w || py < plot.y || py > plot.y + plot.h) {
      return -1
    }
    val band = (plot.w).toDouble() / (count).toDouble()
    var idx = 0
    var jf = 1.0
    for (k in 1 until count) {
      if (plot.x + band * jf <= px) {
        idx = k
      }
      jf = jf + 1.0
    }
    return idx
  }

fun boxplotFrame(rows: List<FiveNumber>, width: Double, height: Double, categories: List<String>, fontSize: Double, measure: (String, Double) -> Double, format: ((Double) -> String)? = null): BoxplotFrame {
    val domain = niceDomain(boxplotExtent(rows), 5.0)
    val cfg = LayoutConfig(width = width, height = height, xDomain = Domain(min = 0.0, max = if (rows.length > 1) (rows.length - 1).toDouble() else 1.0), yDomain = domain, categories = categories, fontSize = fontSize, xTickCount = 5.0, yTickCount = 5.0, showXAxis = true, showYAxis = true, yFormat = format)
    return BoxplotFrame(domain = domain, layout = computeLayout(cfg, measure))
  }

fun renderBoxplotChart(rows: List<FiveNumber>, width: Double, height: Double, categories: List<String>, theme: ChartTheme, options: BoxplotOptions, measure: (String, Double) -> Double, format: ((Double) -> String)? = null, progress: Double? = null): List<PyreonDrawCmd> {
    val f = boxplotFrame(rows, width, height, categories, theme.fontSize, measure, format)
    val l = f.layout
    val out: MutableList<PyreonDrawCmd> = mutableListOf()
    for (tick in l.yTicks) {
      out.add(PyreonDrawCmd(kind = "line", from = PyreonChartPt(x = l.plot.x, y = tick.pos), to = PyreonChartPt(x = l.plot.x + l.plot.w, y = tick.pos), stroke = theme.grid, width = 1.0))
      out.add(PyreonDrawCmd(kind = "text", fill = theme.label, text = tick.label, at = PyreonChartPt(x = l.plot.x - 6.0, y = tick.pos), size = theme.fontSize, align = "end", baseline = "middle"))
    }
    for (tick in l.xTicks) {
      out.add(PyreonDrawCmd(kind = "text", fill = theme.label, text = tick.label, at = PyreonChartPt(x = tick.pos, y = l.plot.y + l.plot.h + 6.0), size = theme.fontSize, align = "middle", baseline = "top"))
    }
    val p = (progress ?: options.progress)
    val opts = BoxplotOptions(fill = options.fill, stroke = options.stroke, widthRatio = options.widthRatio, outlierRadius = options.outlierRadius, progress = p)
    for (c in renderBoxplot(rows, l.plot, f.domain, opts)) {
      out.add(c)
    }
    return out
  }

fun hitBoxplotChart(count: Int, width: Double, height: Double, categories: List<String>, fontSize: Double, measure: (String, Double) -> Double, px: Double, py: Double, rows: List<FiveNumber>): Int {
    val f = boxplotFrame(rows, width, height, categories, fontSize, measure)
    return hitBox(count, f.layout.plot, px, py)
  }

fun heatGridFrom(xs: List<String>, ys: List<String>, values: List<Double>): HeatGrid {
    val cols: MutableList<String> = mutableListOf()
    val rows: MutableList<String> = mutableListOf()
    val colOf: MutableList<Double> = mutableListOf()
    val rowOf: MutableList<Double> = mutableListOf()
    val vals: MutableList<Double> = mutableListOf()
    val n = xs.length
    for (i in 0 until n) {
      val x = xs[i]
      var ci = -1.0
      var cf = 0.0
      for (j in 0 until cols.length) {
        if (cols[j] == x) {
          ci = cf
        }
        cf += 1.0
      }
      if (ci < 0.0) {
        ci = cf
        cols.add(x)
      }
      colOf.add(ci)
      val y = if (i < ys.length) ys[i] else ""
      var ri = -1.0
      var rf = 0.0
      for (j in 0 until rows.length) {
        if (rows[j] == y) {
          ri = rf
        }
        rf += 1.0
      }
      if (ri < 0.0) {
        ri = rf
        rows.add(y)
      }
      rowOf.add(ri)
      val v = if (i < values.length) values[i] else 0.0
      vals.add(if (isFiniteNumber(v)) v else 0.0)
    }
    return buildHeatGrid(cols, rows, colOf, rowOf, vals)
  }

fun heatPlotFor(grid: HeatGrid, w: Double, h: Double, fontSize: Double, measure: (String, Double) -> Double): PyreonChartRect {
    var widest = 0.0
    for (r in grid.rows) {
      val lw = measure(r, fontSize)
      if (lw > widest) {
        widest = lw
      }
    }
    val left = widest + 8.0
    val bottom = fontSize + 8.0
    return PyreonChartRect(x = left, y = 4.0, w = Math.max(0.0, w - left - 4.0), h = Math.max(0.0, h - 4.0 - bottom))
  }

fun renderHeatChart(grid: HeatGrid, w: Double, h: Double, theme: ChartTheme, stops: List<String>, gap: Double, measure: (String, Double) -> Double, progress: Double? = null, selection: HeatSelection? = null): List<PyreonDrawCmd> {
    val plot = heatPlotFor(grid, w, h, theme.fontSize, measure)
    val cmds: MutableList<PyreonDrawCmd> = mutableListOf()
    val cells = renderHeat(HeatmapOptions(grid = grid, plot = plot, stops = stops, gap = gap, progress = (progress ?: 1.0), inRange = selection?.inRange, outBands = selection?.outBands, outColor = selection?.outColor, domain = selection?.domain))
    for (c in cells) {
      cmds.add(c)
    }
    var nrF = 0.0
    for (i in 0 until grid.rows.length) {
      nrF += 1.0
    }
    var ncF = 0.0
    for (i in 0 until grid.cols.length) {
      ncF += 1.0
    }
    val rowStep = (plot.h).toDouble() / (Math.max(1.0, nrF)).toDouble()
    val colStep = (plot.w).toDouble() / (Math.max(1.0, ncF)).toDouble()
    var rf = 0.0
    for (r in grid.rows) {
      cmds.add(PyreonDrawCmd(kind = "text", fill = theme.label, text = r, at = PyreonChartPt(x = plot.x - 4.0, y = plot.y + rowStep * (rf + 0.5)), size = theme.fontSize, align = "end", baseline = "middle"))
      rf += 1.0
    }
    var cf = 0.0
    for (c in grid.cols) {
      cmds.add(PyreonDrawCmd(kind = "text", fill = theme.label, text = c, at = PyreonChartPt(x = plot.x + colStep * (cf + 0.5), y = plot.y + plot.h + 4.0), size = theme.fontSize, align = "middle", baseline = "top"))
      cf += 1.0
    }
    return cmds
  }

fun hitHeatChart(grid: HeatGrid, w: Double, h: Double, fontSize: Double, gap: Double, measure: (String, Double) -> Double, px: Double, py: Double): Int = hitHeatCell(grid, heatPlotFor(grid, w, h, fontSize, measure), gap, px, py)

fun plotHitBars(spec: ChartSpec, measure: (String, Double) -> Double, px: Double, py: Double): Int = plotHitBarsIn(spec, layoutChart(spec, measure), px, py)

fun plotHitBarsIn(spec: ChartSpec, l: PlotLayout, px: Double, py: Double): Int {
    for (i in 0 until spec.series.length) {
      val kind = spec.series[i].kind
      if (kind != "bars" && kind != "waterfall") {
        continue
      }
      val idx = hitBar(barsForIn(spec, i, l.plot), px, py)
      if (idx >= 0) {
        return categoryIndex(spec, idx)
      }
    }
    return stackedHitIn(spec, l.plot, px, py)
  }

fun plotHitIndex(spec: ChartSpec, measure: (String, Double) -> Double, px: Double, py: Double): Int = plotHitIndexIn(spec, layoutChart(spec, measure), px, py)

fun plotHitIndexIn(raw: ChartSpec, l: PlotLayout, px: Double, py: Double): Int {
    val barHit = plotHitBarsIn(raw, l, px, py)
    if (barHit >= 0) {
      return barHit
    }
    val spec = geometrySpec(raw)
    if (spec.series.length == 0) {
      return -1
    }
    val first = spec.series[0]
    if (first.kind == "bars" || first.kind == "stacked" || first.kind == "grouped" || first.kind == "waterfall") {
      return -1
    }
    return categoryIndex(raw, hitNearestX(layoutSeriesPoints(first.values, l.plot, resolveYDomain(spec)), px))
  }

fun renderTitle(text: String, subtitle: String?, box: PyreonChartRect, opts: TitleOptions): TitleLayout {
    val cmds: MutableList<PyreonDrawCmd> = mutableListOf()
    if (text == "" && (subtitle == null || subtitle == "")) {
      return TitleLayout(cmds = cmds, height = 0.0)
    }
    val align = (opts.align ?: "start")
    val gap = (opts.gap ?: 8.0)
    val subSize = (opts.subtitleSize ?: opts.fontSize * 0.8)
    val subColor = (opts.subtitleColor ?: opts.color)
    val x = if (align == "start") box.x else if (align == "end") box.x + box.w else box.x + (box.w).toDouble() / (2.0).toDouble()
    var y = box.y
    if (text != "") {
      cmds.add(PyreonDrawCmd(kind = "text", fill = opts.color, text = text, at = PyreonChartPt(x = x, y = y), size = opts.fontSize, align = align, baseline = "top"))
      y = y + opts.fontSize
    }
    if (subtitle != null && subtitle != "") {
      if (text != "") {
        y = y + (gap).toDouble() / (2.0).toDouble()
      }
      cmds.add(PyreonDrawCmd(kind = "text", fill = subColor, text = subtitle, at = PyreonChartPt(x = x, y = y), size = subSize, align = align, baseline = "top"))
      y = y + subSize
    }
    return TitleLayout(cmds = cmds, height = y - box.y + gap)
  }

fun legendPlan(entries: List<LegendEntry>, box: PyreonChartRect, opts: LegendOptions, measure: (String, Double) -> Double, wrapW: Double): LegendPlan {
    val row: MutableList<Double> = mutableListOf()
    val xs: MutableList<Double> = mutableListOf()
    var x = box.x
    var r = 0.0
    for (e in entries) {
      val entryW = opts.swatch + 4.0 + measure(e.label, opts.fontSize) + opts.gap
      if (opts.orientation == "horizontal" && x + entryW > box.x + wrapW && x > box.x) {
        x = box.x
        r = r + 1.0
      }
      row.add(r)
      xs.add(x)
      if (opts.orientation == "horizontal") {
        x = x + entryW
      } else {
        r = r + 1.0
      }
    }
    var count = 0.0
    for (i in 0 until entries.length) {
      count = count + 1.0
    }
    val rows = if (opts.orientation == "horizontal") r + 1.0 else count
    return LegendPlan(row = row, xs = xs, rows = rows)
  }

fun ceilPositive(v: Double): Double {
    val f = Math.floor(v)
    return if (f < v) f + 1.0 else f
  }

fun renderLegend(entries: List<LegendEntry>, box: PyreonChartRect, opts: LegendOptions, measure: (String, Double) -> Double): LegendLayout {
    val cmds: MutableList<PyreonDrawCmd> = mutableListOf()
    val boxes: MutableList<PyreonChartRect> = mutableListOf()
    if (entries.length == 0) {
      return LegendLayout(cmds = cmds, height = 0.0, boxes = boxes)
    }
    val rowH = Math.max(opts.swatch, opts.fontSize) + opts.gap
    val pagerW = opts.fontSize * 5.0 + opts.gap
    val maxRows = (opts.maxRows ?: 0.0)
    val capped = maxRows >= 1.0
    var plan = legendPlan(entries, box, opts, measure, box.w)
    var overflow = capped && plan.rows > maxRows
    if (overflow && opts.orientation == "horizontal") {
      plan = legendPlan(entries, box, opts, measure, Math.max(opts.swatch + 4.0, box.w - pagerW))
      overflow = plan.rows > maxRows
    }
    val pages = if (overflow) ceilPositive((plan.rows).toDouble() / (maxRows).toDouble()) else 1.0
    val rawPage = (opts.page ?: 0.0)
    val page = if (overflow) Math.max(0.0, Math.min(pages - 1.0, Math.floor(rawPage))) else 0.0
    val firstRow = if (overflow) page * maxRows else 0.0
    val lastRow = if (overflow) Math.min(plan.rows, firstRow + maxRows) else plan.rows
    for (i in 0 until entries.length) {
      val e = entries[i]
      val r = plan.row[i]
      if (r < firstRow || r >= lastRow) {
        boxes.add(PyreonChartRect(x = 0.0, y = 0.0, w = -1.0, h = -1.0))
        continue
      }
      val x = plan.xs[i]
      val y = box.y + (r - firstRow) * rowH
      val textW = measure(e.label, opts.fontSize)
      val entryW = opts.swatch + 4.0 + textW + opts.gap
      boxes.add(PyreonChartRect(x = x, y = y, w = entryW - opts.gap, h = rowH - opts.gap))
      cmds.add(PyreonDrawCmd(kind = "rect", rect = PyreonChartRect(x = x, y = y + ((rowH - opts.gap - opts.swatch)).toDouble() / (2.0).toDouble(), w = opts.swatch, h = opts.swatch), fill = if (e.muted == true) withAlpha(e.color, 0.25) else e.color))
      cmds.add(PyreonDrawCmd(kind = "text", fill = if (e.muted == true) withAlpha(opts.labelColor, 0.45) else opts.labelColor, text = e.label, at = PyreonChartPt(x = x + opts.swatch + 4.0, y = y + ((rowH - opts.gap)).toDouble() / (2.0).toDouble()), size = opts.fontSize, align = "start", baseline = "middle"))
    }
    val visibleRows = lastRow - firstRow
    val height = visibleRows * rowH
    if (!overflow) {
      return LegendLayout(cmds = cmds, height = height, boxes = boxes)
    }
    val py = box.y + (visibleRows - 1.0) * rowH
    val arrowW = opts.fontSize
    val right = box.x + box.w
    val prevX = right - pagerW
    val nextX = right - arrowW
    val canPrev = page > 0.0
    val canNext = page < pages - 1.0
    val mid = ((rowH - opts.gap)).toDouble() / (2.0).toDouble()
    cmds.add(PyreonDrawCmd(kind = "text", fill = if (canPrev) opts.labelColor else withAlpha(opts.labelColor, 0.35), text = "‹", at = PyreonChartPt(x = prevX + (arrowW).toDouble() / (2.0).toDouble(), y = py + mid), size = opts.fontSize, align = "middle", baseline = "middle"))
    cmds.add(PyreonDrawCmd(kind = "text", fill = opts.labelColor, text = "${plain(page + 1.0)}/${plain(pages)}", at = PyreonChartPt(x = ((prevX + arrowW + nextX)).toDouble() / (2.0).toDouble(), y = py + mid), size = opts.fontSize, align = "middle", baseline = "middle"))
    cmds.add(PyreonDrawCmd(kind = "text", fill = if (canNext) opts.labelColor else withAlpha(opts.labelColor, 0.35), text = "›", at = PyreonChartPt(x = nextX + (arrowW).toDouble() / (2.0).toDouble(), y = py + mid), size = opts.fontSize, align = "middle", baseline = "middle"))
    val pager = LegendPager(page = page, pages = pages, hasPrev = canPrev, prev = PyreonChartRect(x = prevX, y = py, w = arrowW, h = rowH - opts.gap), hasNext = canNext, next = PyreonChartRect(x = nextX, y = py, w = arrowW, h = rowH - opts.gap))
    return LegendLayout(cmds = cmds, height = height, boxes = boxes, pager = pager)
  }

fun legendColumnWidth(entries: List<LegendEntry>, opts: LegendOptions, measure: (String, Double) -> Double): Double {
    var w = 0.0
    for (e in entries) {
      val ew = opts.swatch + 4.0 + measure(e.label, opts.fontSize) + opts.gap
      if (ew > w) {
        w = ew
      }
    }
    return w
  }

fun placeLegend(entries: List<LegendEntry>, area: PyreonChartRect, position: LegendPosition, opts: LegendOptions, measure: (String, Double) -> Double): LegendPlacement {
    val empty = LegendPlacement(cmds = listOf(), top = 0.0, bottom = 0.0, left = 0.0, right = 0.0, boxes = listOf())
    if (entries.length == 0) {
      return empty
    }
    val pad = 8.0
    if (position == LegendPosition.left || position == LegendPosition.right) {
      val col = Math.min(legendColumnWidth(entries, opts, measure), area.w * 0.4)
      val lx = if (position == LegendPosition.left) area.x + pad else area.x + area.w - col
      val vertical = opts.copy(orientation = "vertical")
      val l = renderLegend(entries, PyreonChartRect(x = lx, y = area.y + pad, w = col, h = area.h), vertical, measure)
      val inset = col + pad
      return LegendPlacement(cmds = l.cmds, top = 0.0, bottom = 0.0, left = if (position == LegendPosition.left) inset else 0.0, right = if (position == LegendPosition.right) inset else 0.0, boxes = l.boxes, pager = l.pager)
    }
    val horizontal = opts.copy(orientation = "horizontal")
    val wrapW = area.w - pad * 2.0
    if (position == LegendPosition.bottom) {
      val rows = legendPlan(entries, PyreonChartRect(x = pad, y = 0.0, w = wrapW, h = area.h), horizontal, measure, wrapW).rows
      val rowH = Math.max(10.0, opts.fontSize) + 12.0
      val lh = rows * rowH
      val l = renderLegend(entries, PyreonChartRect(x = area.x + pad, y = area.y + area.h - lh, w = wrapW, h = lh), horizontal, measure)
      return LegendPlacement(cmds = l.cmds, top = 0.0, bottom = l.height + pad, left = 0.0, right = 0.0, boxes = l.boxes, pager = l.pager)
    }
    val l = renderLegend(entries, PyreonChartRect(x = area.x + pad, y = area.y + pad, w = wrapW, h = area.h), horizontal, measure)
    return LegendPlacement(cmds = l.cmds, top = l.height + pad, bottom = 0.0, left = 0.0, right = 0.0, boxes = l.boxes, pager = l.pager)
  }

fun tooltipAt(index: Int, categories: List<String>, series: List<TooltipSeries>): TooltipContent {
    val rows: MutableList<TooltipRow> = mutableListOf()
    for (s in series) {
      val v = s.values[index]
      if (v == null || !isFiniteNumber(v)) {
        continue
      }
      var row = TooltipRow(label = s.label, value = v, color = s.color)
      val other = (s.values2 ?: listOf())
      if (index < other.length) {
        val v2 = other[index]
        if (isFiniteNumber(v2)) {
          row = TooltipRow(label = s.label, value = v, color = s.color, value2 = v2)
        }
      }
      val rs = (s.rValues ?: listOf())
      if (index < rs.length) {
        val r = rs[index]
        if (isFiniteNumber(r)) {
          row = TooltipRow(label = row.label, value = row.value, color = row.color, value2 = row.value2, size = r)
        }
      }
      rows.add(row)
      val extras = (s.extras ?: listOf())
      for (e in extras) {
        val nums = (e.numbers ?: listOf())
        val strs = (e.texts ?: listOf())
        if (index < nums.length) {
          val ev = nums[index]
          if (isFiniteNumber(ev)) {
            val numRow = TooltipRow(label = e.label, value = ev, color = s.color)
            rows.add(numRow)
          }
        } else {
          if (index < strs.length) {
            val textRow = TooltipRow(label = e.label, value = (0.0).toDouble() / (0.0).toDouble(), color = s.color, text = strs[index])
            rows.add(textRow)
          }
        }
      }
    }
    return TooltipContent(title = (categories[index] ?: "${index + 1}"), rows = rows)
  }

fun tooltipLines(c: TooltipContent, format: ((Double) -> String)? = null): List<String> {
    val fmt = (format ?: ::plain)
    val out = mutableListOf(c.title)
    for (r in c.rows) {
      val lo = (r.value2 ?: ((0.0).toDouble() / (0.0).toDouble()))
      val sz = (r.size ?: ((0.0).toDouble() / (0.0).toDouble()))
      val txt = (r.text ?: "")
      if (lo == lo) {
        out.add("${r.label}: ${fmt(lo)} to ${fmt(r.value)}")
      } else {
        if (sz == sz) {
          out.add("${r.label}: ${fmt(r.value)} (size ${fmt(sz)})")
        } else {
          if (r.value != r.value) {
            out.add("${r.label}: ${txt}")
          } else {
            out.add("${r.label}: ${fmt(r.value)}")
          }
        }
      }
    }
    return out
  }

fun placeTooltip(at: PyreonChartPt, size: Size, bounds: PyreonChartRect, offset: Double): PyreonChartPt {
    var x = at.x + offset
    if (x + size.w > bounds.x + bounds.w) {
      x = at.x - offset - size.w
    }
    if (x < bounds.x) {
      x = bounds.x
    }
    var y = at.y - (size.h).toDouble() / (2.0).toDouble()
    if (y < bounds.y) {
      y = bounds.y
    }
    if (y + size.h > bounds.y + bounds.h) {
      y = bounds.y + bounds.h - size.h
    }
    return PyreonChartPt(x = x, y = y)
  }

