    return listOf(s.label, plain(s.value))
  }

fun pieTip(slices: List<Slice>, box: PyreonChartRect, innerRatio: Double, px: Double, py: Double): List<String> {
    val fit = fitCircle(box)
    val i = hitArc(layoutArcs(slices), fit.center, fit.radius, fit.radius * innerRatio, PyreonChartPt(x = px, y = py))
    if (i < 0) {
      return listOf()
    }
    val s = slices[i]
    var total = 0.0
    for (x in slices) {
      total += x.value
    }
    val pct = if (total > 0.0) Math.floor(((s.value).toDouble() / (total).toDouble()) * 100.0 + 0.5) else 0.0
    return listOf(s.label, "${plain(s.value)} (${plain(pct)}%)")
  }

fun renderTooltip(lines: List<String>, at: PyreonChartPt, bounds: PyreonChartRect, opts: TooltipOptions, measure: (String, Double) -> Double): List<PyreonDrawCmd> {
    val cmds: MutableList<PyreonDrawCmd> = mutableListOf()
    if (lines.length == 0) {
      return cmds
    }
    val lineH = opts.fontSize * 1.4
    var w = 0.0
    for (l in lines) {
      val m = measure(l, opts.fontSize)
      if (m > w) {
        w = m
      }
    }
    val size = Size(w = w + opts.pad * 2.0, h = lineH * lines.length + opts.pad * 2.0 - (lineH - opts.fontSize))
    val p = placeTooltip(at, size, bounds, 12.0)
    val r = opts.radius
    cmds.add(PyreonDrawCmd(kind = "rect", rect = PyreonChartRect(x = p.x, y = p.y, w = size.w, h = size.h), fill = opts.fill, corners = listOf(r, r, r, r)))
    cmds.add(PyreonDrawCmd(kind = "polyline", stroke = opts.border, width = 1.0, points = listOf(PyreonChartPt(x = p.x, y = p.y), PyreonChartPt(x = p.x + size.w, y = p.y), PyreonChartPt(x = p.x + size.w, y = p.y + size.h), PyreonChartPt(x = p.x, y = p.y + size.h), PyreonChartPt(x = p.x, y = p.y))))
    var y = p.y + opts.pad
    for (l in lines) {
      cmds.add(PyreonDrawCmd(kind = "text", fill = opts.text, text = l, at = PyreonChartPt(x = p.x + opts.pad, y = y), size = opts.fontSize, align = "start", baseline = "top"))
      y = y + lineH
    }
    return cmds
  }

fun bubbleRadii(raw: List<Double>, minR: Double, maxR: Double): List<Double> {
    val clean: MutableList<Double> = mutableListOf()
    var hi = 0.0
    for (v in raw) {
      val c = if (isFiniteNumber(v) && v > 0.0) v else 0.0
      clean.add(c)
      if (c > hi) {
        hi = c
      }
    }
    val out: MutableList<Double> = mutableListOf()
    for (c in clean) {
      out.add(if (hi == 0.0) minR else minR + Math.sqrt(((c).toDouble() / (hi).toDouble()).toDouble()) * (maxR - minR))
    }
    return out
  }

fun clampWindow(win: ZoomWindow): ZoomWindow {
    var span = win.end - win.start
    if (span < MIN_SPAN) {
      span = MIN_SPAN
    }
    if (span > 1.0) {
      span = 1.0
    }
    var start = win.start
    if (start < 0.0) {
      start = 0.0
    }
    if (start + span > 1.0) {
      start = 1.0 - span
    }
    return ZoomWindow(start = start, end = start + span)
  }

fun zoomWindow(win: ZoomWindow, factor: Double, centerFrac: Double): ZoomWindow {
    val span = win.end - win.start
    val c = win.start + span * (if (centerFrac < 0.0) 0.0 else if (centerFrac > 1.0) 1.0 else centerFrac)
    val nextSpan = span * factor
    val frac = if (span <= 0.0) 0.5 else ((c - win.start)).toDouble() / (span).toDouble()
    return clampWindow(ZoomWindow(start = c - nextSpan * frac, end = c + nextSpan * (1.0 - frac)))
  }

fun panWindow(win: ZoomWindow, deltaFrac: Double): ZoomWindow {
    val span = win.end - win.start
    return clampWindow(ZoomWindow(start = win.start + deltaFrac * span, end = win.end + deltaFrac * span))
  }

fun limitZoomWindow(limits: ZoomLimits, prev: ZoomWindow, next: ZoomWindow): ZoomWindow {
    val w = clampWindow(next)
    val span = w.end - w.start
    val lo = limits.minSpan
    val hi = if (limits.maxSpan > 0.0) limits.maxSpan else 1.0
    var target = if (span < lo) lo else if (span > hi) hi else span
    if (limits.lock) {
      target = prev.end - prev.start
    }
    val diff = target - span
    if ((if (diff < 0.0) 0.0 - diff else diff) <= 1e-9) {
      return w
    }
    val center = ((w.start + w.end)).toDouble() / (2.0).toDouble()
    var start = center - (target).toDouble() / (2.0).toDouble()
    var end = center + (target).toDouble() / (2.0).toDouble()
    if (start < 0.0) {
      end = end - start
      start = 0.0
    }
    if (end > 1.0) {
      start = start - (end - 1.0)
      end = 1.0
    }
    return clampWindow(ZoomWindow(start = if (start < 0.0) 0.0 else start, end = if (end > 1.0) 1.0 else end))
  }

fun isFullWindow(win: ZoomWindow): Boolean = win.start <= 0.0 && win.end >= 1.0

fun sliceRange(win: ZoomWindow, n: Int): SliceRange {
    if (n <= 0) {
      return SliceRange(from = 0, to = 0)
    }
    var nF = 0.0
    for (i in 0 until n) {
      nF = nF + 1.0
    }
    val startAt = win.start * nF
    val endAt = win.end * nF
    var from = 0
    var fromF = 0.0
    while (fromF + 1.0 <= startAt && from < n - 1) {
      from = from + 1
      fromF = fromF + 1.0
    }
    var to = 0
    var toF = 0.0
    while (toF < endAt && to < n) {
      to = to + 1
      toF = toF + 1.0
    }
    if (to < from + 1) {
      to = from + 1
    }
    return SliceRange(from = from, to = to)
  }

fun presetWindow(count: Int, total: Int): ZoomWindow {
    if (count <= 0 || total <= 0 || count >= total) {
      return ZoomWindow(start = 0.0, end = 1.0)
    }
    var c = 0.0
    for (i in 0 until count) {
      c = c + 1.0
    }
    var t = 0.0
    for (i in 0 until total) {
      t = t + 1.0
    }
    return ZoomWindow(start = 1.0 - (c).toDouble() / (t).toDouble(), end = 1.0)
  }

fun presetIsActive(preset: ZoomPreset, total: Int, win: ZoomWindow): Boolean {
    val target = presetWindow(preset.count, total)
    val ds = win.start - target.start
    val de = win.end - target.end
    val ads = if (ds < 0.0) 0.0 - ds else ds
    val ade = if (de < 0.0) 0.0 - de else de
    return ads < 0.000001 && ade < 0.000001
  }

fun renderPresets(items: List<ZoomPreset>, total: Int, win: ZoomWindow, canvas: PyreonChartRect, opts: PresetOptions, measure: (String, Double) -> Double): PresetLayout {
    val cmds: MutableList<PyreonDrawCmd> = mutableListOf()
    val boxes: MutableList<PyreonChartRect> = mutableListOf()
    if (items.length == 0) {
      return PresetLayout(cmds = cmds, boxes = boxes, height = 0.0)
    }
    val widths: MutableList<Double> = mutableListOf()
    var span = 0.0
    for (i in 0 until items.length) {
      val it = items[i]
      val tw = measure(it.label, opts.fontSize) + opts.padX * 2.0
      widths.add(tw)
      span = span + tw
      if (i > 0) {
        span = span + opts.gap
      }
    }
    var x = canvas.x + canvas.w - opts.inset - span
    val y = canvas.y + canvas.h - PRESET_STRIP_HEIGHT + opts.padY
    val h = PRESET_STRIP_HEIGHT - opts.padY * 2.0
    for (i in 0 until items.length) {
      val it = items[i]
      val tw = widths[i]
      val b = PyreonChartRect(x = x, y = y, w = tw, h = h)
      boxes.add(b)
      val active = presetIsActive(it, total, win)
      cmds.add(PyreonDrawCmd(kind = "rect", rect = b, fill = if (active) opts.activeFill else opts.idleFill))
      cmds.add(PyreonDrawCmd(kind = "text", fill = if (active) opts.activeText else opts.idleText, text = it.label, at = PyreonChartPt(x = b.x + (b.w).toDouble() / (2.0).toDouble(), y = b.y + (b.h).toDouble() / (2.0).toDouble()), size = opts.fontSize, align = "middle", baseline = "middle"))
      x = x + tw + opts.gap
    }
    return PresetLayout(cmds = cmds, boxes = boxes, height = PRESET_STRIP_HEIGHT)
  }

fun presetHit(boxes: List<PyreonChartRect>, x: Double, y: Double): Int {
    for (i in 0 until boxes.length) {
      val b = boxes[i]
      if (x >= b.x && x <= b.x + b.w && y >= b.y && y <= b.y + b.h) {
        return i
      }
    }
    return -1
  }

fun isHiddenSeries(hidden: List<Int>, i: Int): Boolean {
    for (k in 0 until hidden.length) {
      if (hidden[k] == i) {
        return true
      }
    }
    return false
  }

fun legendToggle(hidden: List<Int>, i: Int): List<Int> {
    val out: MutableList<Int> = mutableListOf()
    var found = false
    for (k in 0 until hidden.length) {
      val h = hidden[k]
      if (h == i) {
        found = true
      } else {
        out.add(h)
      }
    }
    if (!found) {
      out.add(i)
    }
    return out
  }

fun pinSelection(selected: List<Int>, global: Int, multiple: Boolean): List<Int> {
    if (global < 0) {
      return selected
    }
    var has = false
    for (k in 0 until selected.length) {
      if (selected[k] == global) {
        has = true
      }
    }
    if (!multiple) {
      val one: MutableList<Int> = mutableListOf()
      if (!has) {
        one.add(global)
      }
      return one
    }
    val out: MutableList<Int> = mutableListOf()
    for (k in 0 until selected.length) {
      val s = selected[k]
      if (s != global) {
        out.add(s)
      }
    }
    if (!has) {
      out.add(global)
    }
    return out
  }

fun hideHiddenSeries(series: List<Series>, hidden: List<Int>): List<Series> {
    if (hidden.length == 0) {
      return series
    }
    val out: MutableList<Series> = mutableListOf()
    for (i in 0 until series.length) {
      val s = series[i]
      if (isHiddenSeries(hidden, i)) {
        val zeroed: MutableList<Double> = mutableListOf()
        if (s.kind == "stacked" || s.kind == "grouped") {
          for (k in 0 until s.values.length) {
            zeroed.add(0.0)
          }
        }
        out.add(Series(kind = s.kind, values = zeroed, color = s.color, width = s.width, radius = s.radius, label = s.label, curve = s.curve, showValues = false, axis = s.axis, effect = s.effect, symbol = s.symbol, symbolRepeat = s.symbolRepeat))
      } else {
        out.add(s)
      }
    }
    return out
  }

fun legendHitIndex(boxes: List<PyreonChartRect>, x: Double, y: Double): Int {
    for (i in 0 until boxes.length) {
      val b = boxes[i]
      if (x >= b.x && x <= b.x + b.w && y >= b.y && y <= b.y + b.h) {
        return i
      }
    }
    return -1
  }

fun pagerHit(pager: LegendPager, x: Double, y: Double): Double {
    val p = pager.prev
    if (pager.hasPrev && x >= p.x && x <= p.x + p.w && y >= p.y && y <= p.y + p.h) {
      return -1.0
    }
    val n = pager.next
    if (pager.hasNext && x >= n.x && x <= n.x + n.w && y >= n.y && y <= n.y + n.h) {
      return 1.0
    }
    return 0.0
  }

fun renderNavigator(values: List<Double>, color: String, win: ZoomWindow, canvas: PyreonChartRect, gridFill: String): NavigatorLayout {
    val stripW = canvas.w - NAV_INSET * 2.0
    val strip = PyreonChartRect(x = canvas.x + NAV_INSET, y = canvas.y + canvas.h - NAV_STRIP_HEIGHT + NAV_PAD_Y, w = if (stripW < 0.0) 0.0 else stripW, h = NAV_STRIP_HEIGHT - NAV_PAD_Y * 2.0)
    val cmds: MutableList<PyreonDrawCmd> = mutableListOf()
    cmds.add(PyreonDrawCmd(kind = "rect", rect = strip, fill = gridFill))
    if (values.length > 1) {
      var lo = 0.0
      var hi = 0.0
      var seen = false
      for (i in 0 until values.length) {
        val v = values[i]
        if (isFiniteNumber(v)) {
          if (!seen) {
            lo = v
            hi = v
            seen = true
          } else {
            if (v < lo) {
              lo = v
            }
            if (v > hi) {
              hi = v
            }
          }
        }
      }
      if (seen) {
        val safe: MutableList<Double> = mutableListOf()
        for (i in 0 until values.length) {
          val v = values[i]
          safe.add(if (!isFiniteNumber(v)) lo else v)
        }
        val pts = layoutSeriesPoints(safe, strip, Domain(min = if (lo < 0.0) lo else 0.0, max = if (hi <= lo) lo + 1.0 else hi))
        val last = pts[pts.length - 1]
        val first = pts[0]
        val poly: MutableList<PyreonChartPt> = mutableListOf()
        for (i in 0 until pts.length) {
          poly.add(pts[i])
        }
        poly.add(PyreonChartPt(x = last.x, y = strip.y + strip.h))
        poly.add(PyreonChartPt(x = first.x, y = strip.y + strip.h))
        cmds.add(PyreonDrawCmd(kind = "polygon", fill = withAlpha(color, 0.35), points = poly))
      }
    }
    val bx0 = strip.x + strip.w * win.start
    val bx1 = strip.x + strip.w * win.end
    cmds.add(PyreonDrawCmd(kind = "rect", rect = PyreonChartRect(x = bx0, y = strip.y, w = bx1 - bx0, h = strip.h), fill = "rgba(37,99,235,0.18)"))
    cmds.add(PyreonDrawCmd(kind = "rect", rect = PyreonChartRect(x = bx0 - 3.0, y = strip.y, w = 6.0, h = strip.h), fill = "#2563eb"))
    cmds.add(PyreonDrawCmd(kind = "rect", rect = PyreonChartRect(x = bx1 - 3.0, y = strip.y, w = 6.0, h = strip.h), fill = "#2563eb"))
    return NavigatorLayout(cmds = cmds, strip = strip, height = NAV_STRIP_HEIGHT)
  }

fun navigatorHit(strip: PyreonChartRect, win: ZoomWindow, x: Double): Int {
    val bx0 = strip.x + strip.w * win.start
    val bx1 = strip.x + strip.w * win.end
    val dl = x - bx0
    val dr = x - bx1
    if ((if (dl < 0.0) 0.0 - dl else dl) <= HANDLE_GRAB) {
      return 2
    }
    if ((if (dr < 0.0) 0.0 - dr else dr) <= HANDLE_GRAB) {
      return 3
    }
    return 1
  }

fun navigatorDrag(kind: Int, startWin: ZoomWindow, deltaFrac: Double): ZoomWindow {
    if (kind == 2) {
      val s = startWin.start + deltaFrac
      val cap = startWin.end - NAV_MIN_SPAN
      return clampWindow(ZoomWindow(start = if (s < cap) s else cap, end = startWin.end))
    }
    if (kind == 3) {
      val e = startWin.end + deltaFrac
      val floor = startWin.start + NAV_MIN_SPAN
      return clampWindow(ZoomWindow(start = startWin.start, end = if (e > floor) e else floor))
    }
    return clampWindow(ZoomWindow(start = startWin.start + deltaFrac, end = startWin.end + deltaFrac))
  }

fun brushRange(plotX: Double, plotW: Double, x1: Double, x2: Double, win: ZoomWindow, n: Int): BrushRange {
    val lo = if (x1 < x2) x1 else x2
    val hi = if (x1 < x2) x2 else x1
    val span = win.end - win.start
    val rawLo = if (plotW <= 0.0) 0.0 else ((lo - plotX)).toDouble() / (plotW).toDouble()
    val rawHi = if (plotW <= 0.0) 0.0 else ((hi - plotX)).toDouble() / (plotW).toDouble()
    val cLo = if (rawLo < 0.0) 0.0 else if (rawLo > 1.0) 1.0 else rawLo
    val cHi = if (rawHi < 0.0) 0.0 else if (rawHi > 1.0) 1.0 else rawHi
    val r = sliceRange(ZoomWindow(start = win.start + cLo * span, end = win.start + cHi * span), n)
    return BrushRange(start = r.from, end = r.to - 1)
  }

fun countToDouble(k: Int): Double {
    var f = 0.0
    if (k >= 0) {
      for (i in 0 until k) {
        f = f + 1.0
      }
    } else {
      for (i in 0 until 0 - k) {
        f = f - 1.0
      }
    }
    return f
  }

fun brushBand(plot: PyreonChartRect, sel: BrushRange, win: ZoomWindow, n: Int): BrushBand {
    val r = sliceRange(win, n)
    val nView = r.to - r.from
    if (nView <= 0) {
      return BrushBand(visible = false, lo = 0.0, hi = 0.0)
    }
    val bw = (plot.w).toDouble() / (countToDouble(nView)).toDouble()
    var lo = plot.x + countToDouble(sel.start - r.from) * bw
    var hi = plot.x + countToDouble(sel.end - r.from + 1) * bw
    if (hi < plot.x || lo > plot.x + plot.w) {
      return BrushBand(visible = false, lo = 0.0, hi = 0.0)
    }
    if (lo < plot.x) {
      lo = plot.x
    }
    if (hi > plot.x + plot.w) {
      hi = plot.x + plot.w
    }
    return BrushBand(visible = true, lo = lo, hi = hi)
  }

fun renderBrushBand(plot: PyreonChartRect, lo: Double, hi: Double, edge: String): List<PyreonDrawCmd> {
    val out: MutableList<PyreonDrawCmd> = mutableListOf()
    out.add(PyreonDrawCmd(kind = "rect", rect = PyreonChartRect(x = lo, y = plot.y, w = hi - lo, h = plot.h), fill = "rgba(99,102,241,0.15)"))
    out.add(PyreonDrawCmd(kind = "line", from = PyreonChartPt(x = lo, y = plot.y), to = PyreonChartPt(x = lo, y = plot.y + plot.h), stroke = edge, width = 1.0, dash = listOf(3.0, 3.0)))
    out.add(PyreonDrawCmd(kind = "line", from = PyreonChartPt(x = hi, y = plot.y), to = PyreonChartPt(x = hi, y = plot.y + plot.h), stroke = edge, width = 1.0, dash = listOf(3.0, 3.0)))
    return out
  }

fun describeChart(input: A11yInput): String {
    val fmt = (input.format ?: ::plain)
    val parts: MutableList<String> = mutableListOf()
    val title = (input.title ?: "Chart")
    if (input.series.length == 0) {
      return "${title}: no data."
    }
    parts.add("${title}.")
    val n = input.series.length
    parts.add(if (n == 1) "1 series" else "${n} series")
    if (input.categories.length > 0) {
      parts.add("over ${input.categories.length} categories from ${input.categories[0]} to ${input.categories[input.categories.length - 1]}.")
    } else {
      parts.add(".")
    }
    for (s in input.series) {
      if (s.values.length == 0) {
        parts.add("${s.label}: empty.")
        continue
      }
      var lo = 0.0
      var hi = 0.0
      var loAt = 0
      var hiAt = 0
      var first = 0.0
      var last = 0.0
      var seen = 0
      for (i in 0 until s.values.length) {
        val v = s.values[i]
        if (v != v) {
          continue
        }
        if (seen == 0) {
          lo = v
          hi = v
          loAt = i
          hiAt = i
          first = v
        }
        if (v < lo) {
          lo = v
          loAt = i
        }
        if (v > hi) {
          hi = v
          hiAt = i
        }
        last = v
        seen = seen + 1
      }
      if (seen == 0) {
        parts.add("${s.label}: empty.")
        continue
      }
      val dir = if (last > first) "rising" else if (last < first) "falling" else "flat"
      val at = { i: Int -> if (input.categories[i] != null) " at ${input.categories[i]}" else "" }
      val other = (s.values2 ?: listOf())
      if (other.length > 0) {
        var olo = 0.0
        var ohi = 0.0
        var oseen = 0
        for (i in 0 until other.length) {
          val v = other[i]
          if (v != v) {
            continue
          }
          if (oseen == 0) {
            olo = v
            ohi = v
          }
          if (v < olo) {
            olo = v
          }
          if (v > ohi) {
            ohi = v
          }
          oseen = oseen + 1
        }
        if (oseen > 0) {
          parts.add("${s.label}, ${s.kind}: upper bound ${dir} from ${fmt(first)} to ${fmt(last)}, " + "ranging ${fmt(lo)}${at(loAt)} to ${fmt(hi)}${at(hiAt)}; " + "lower bound ranging ${fmt(olo)} to ${fmt(ohi)}.")
          continue
        }
      }
      parts.add("${s.label}, ${s.kind}: ${dir} from ${fmt(first)} to ${fmt(last)}, " + "ranging ${fmt(lo)}${at(loAt)} to ${fmt(hi)}${at(hiAt)}.")
    }
    return parts.joinToString(" ").replaceFirst(" .", ".")
  }

fun withError(fmt: (Double) -> String, v: Double, s: A11ySeries, i: Int): String {
    val lo = (s.errLow ?: listOf())
    val hi = (s.errHigh ?: listOf())
    if (i >= lo.length || i >= hi.length) {
      return fmt(v)
    }
    val l = lo[i]
    val h = hi[i]
    if (!isFiniteNumber(l) || !isFiniteNumber(h)) {
      return fmt(v)
    }
    return "${fmt(v)} (${fmt(l)} to ${fmt(h)})"
  }

fun chartTable(input: A11yInput): A11yTable {
    val fmt = (input.format ?: ::plain)
    val headers = mutableListOf("Category")
    for (s in input.series) {
      val other = (s.values2 ?: listOf())
      val rs = (s.rValues ?: listOf())
      if (other.length > 0) {
        headers.add("${s.label} (upper)")
        headers.add("${s.label} (lower)")
      } else {
        headers.add(s.label)
      }
      if (rs.length > 0) {
        headers.add("${s.label} (size)")
      }
      val sx = (s.xs ?: listOf())
      if (sx.length > 0) {
        headers.add("${s.label} (x)")
      }
      val extras = (s.extras ?: listOf())
      for (e in extras) {
        headers.add("${s.label} (${e.label})")
      }
    }
    var n = input.categories.length
    for (s in input.series) {
      if (s.values.length > n) {
        n = s.values.length
      }
    }
    val rows: MutableList<List<String>> = mutableListOf()
    for (i in 0 until n) {
      val row = mutableListOf(if (i < input.categories.length) input.categories[i] else "${i + 1}")
      for (s in input.series) {
        val other = (s.values2 ?: listOf())
        val rs = (s.rValues ?: listOf())
        val two = other.length > 0
        val sized = rs.length > 0
        val sx = (s.xs ?: listOf())
        val hasX = sx.length > 0
        val extras = (s.extras ?: listOf())
        if (i >= s.values.length) {
          row.add("")
          if (two) {
            row.add("")
          }
          if (sized) {
            row.add("")
          }
          if (hasX) {
            row.add("")
          }
          for (k in 0 until extras.length) {
            row.add("")
          }
          continue
        }
        val v = s.values[i]
        row.add(if (isFiniteNumber(v)) withError(fmt, v, s, i) else "")
        if (two) {
          if (i >= other.length) {
            row.add("")
          } else {
            val v2 = other[i]
            row.add(if (isFiniteNumber(v2)) fmt(v2) else "")
          }
        }
        if (sized) {
          if (i >= rs.length) {
            row.add("")
          } else {
            val r = rs[i]
            row.add(if (isFiniteNumber(r)) fmt(r) else "")
          }
        }
        if (hasX) {
          if (i >= sx.length) {
            row.add("")
          } else {
            val xv = sx[i]
            row.add(if (isFiniteNumber(xv)) fmt(xv) else "")
          }
        }
        for (e in extras) {
          val nums = (e.numbers ?: listOf())
          val strs = (e.texts ?: listOf())
          if (i < nums.length) {
            val ev = nums[i]
            row.add(if (isFiniteNumber(ev)) fmt(ev) else "")
          } else {
            if (i < strs.length) {
              row.add(strs[i])
            } else {
              row.add("")
            }
          }
        }
      }
      rows.add(row)
    }
    return A11yTable(headers = headers, rows = rows)
  }

fun finite(v: Double): Boolean = v == v

fun smaValues(values: List<Double>, window: Int): List<Double> {
    val n = values.length
    val out: MutableList<Double> = mutableListOf()
    val w = if (window < 1) 1 else window
    var sum = 0.0
    for (i in 0 until n) {
      val v = values[i]
      sum = sum + (if (finite(v)) v else 0.0)
      if (i >= w) {
        val gone = values[i - w]
        sum = sum - (if (finite(gone)) gone else 0.0)
      }
      out.add(if (i >= w - 1) (sum).toDouble() / (w).toDouble() else GAP)
    }
    return out
  }

fun emaValues(values: List<Double>, window: Int): List<Double> {
    val n = values.length
    val out: MutableList<Double> = mutableListOf()
    val w = if (window < 1) 1 else window
    val alpha = (2.0).toDouble() / ((w + 1.0)).toDouble()
    var prev = GAP
    var seed = 0.0
    for (i in 0 until n) {
      val v = values[i]
      val vv = if (finite(v)) v else 0.0
      if (i < w - 1) {
        seed = seed + vv
        out.add(GAP)
      } else {
        if (i == w - 1) {
          prev = ((seed + vv)).toDouble() / (w).toDouble()
          out.add(prev)
        } else {
          prev = vv * alpha + prev * (1.0 - alpha)
          out.add(prev)
        }
      }
    }
    return out
  }

fun stdevValues(values: List<Double>, window: Int): List<Double> {
    val n = values.length
    val out: MutableList<Double> = mutableListOf()
    val w = if (window < 1) 1 else window
    for (i in 0 until n) {
      if (i < w - 1) {
        out.add(GAP)
        continue
      }
      var mean = 0.0
      for (k in i - w + 1..i) {
        mean = mean + values[k]
      }
      mean = (mean).toDouble() / (w).toDouble()
      var acc = 0.0
      for (k in i - w + 1..i) {
        val d = values[k] - mean
        acc = acc + d * d
      }
      out.add(Math.sqrt(((acc).toDouble() / (w).toDouble()).toDouble()))
    }
    return out
  }

fun trendValues(values: List<Double>): List<Double> {
    val n = values.length
    val out: MutableList<Double> = mutableListOf()
    if (n == 0) {
      return out
    }
    var sx = 0.0
    var sy = 0.0
    var sxx = 0.0
    var sxy = 0.0
    var m = 0.0
    for (i in 0 until n) {
      val v = values[i]
      if (!finite(v)) {
        continue
      }
      val x = i * 1.0
      sx = sx + x
      sy = sy + v
      sxx = sxx + x * x
      sxy = sxy + x * v
      m = m + 1.0
    }
    val denom = m * sxx - sx * sx
    val slope = if (m < 2.0 || denom == 0.0) 0.0 else ((m * sxy - sx * sy)).toDouble() / (denom).toDouble()
    val intercept = if (m == 0.0) 0.0 else ((sy - slope * sx)).toDouble() / (m).toDouble()
    for (i in 0 until n) {
      out.add(intercept + slope * i)
    }
    return out
  }

fun bollingerEdge(values: List<Double>, window: Int, k: Double, sign: Double): List<Double> {
    val mid = smaValues(values, window)
    val sd = stdevValues(values, window)
    val out: MutableList<Double> = mutableListOf()
    for (i in 0 until values.length) {
      val m = mid[i]
      val s = sd[i]
      out.add(if (finite(m) && finite(s)) m + sign * k * s else GAP)
    }
    return out
  }

fun bucketEdges(span: Int, count: Int): List<Int> {
    val edges = mutableListOf(0)
    var acc = 0
    var edge = 0
    var i = 0
    while (i <= count) {
      acc = acc + span
      while (acc >= count) {
        acc = acc - count
        edge = edge + 1
      }
      edges.add(edge)
      i = i + 1
    }
    return edges
  }

fun xOf(xs: List<Double>, i: Int): Double {
    if (xs.length == 0) {
      return i * 1.0
    }
    return xs[i]
  }

fun lttbIndices(xs: List<Double>, ys: List<Double>, threshold: Int): List<Int> {
    val n = ys.length
    if (threshold >= n || threshold < 3) {
      return listOf()
    }
    val span = n - 2
    val count = threshold - 2
    val edges = bucketEdges(span, count)
    val out = mutableListOf(0)
    var a = 0
    for (i in 0 until count) {
      val lo = edges[i] + 1
      val hi = edges[i + 1] + 1
      var avgLo = edges[i + 1] + 1
      var avgHi = edges[i + 2] + 1
      if (avgHi > n) {
        avgHi = n
      }
      var avgCount = avgHi - avgLo
      if (avgCount < 1) {
        avgLo = lo
        avgHi = hi
        avgCount = hi - lo
        if (avgCount < 1) {
          avgCount = 1
        }
      }
      var avgX = 0.0
      var avgY = 0.0
      for (j in avgLo until avgHi) {
        avgX = avgX + xOf(xs, j)
        avgY = avgY + ys[j]
      }
      avgX = (avgX).toDouble() / (avgCount).toDouble()
      avgY = (avgY).toDouble() / (avgCount).toDouble()
      val paX = xOf(xs, a)
      val paY = ys[a]
      var best = lo
      var bestArea = -1.0
      for (j in lo until hi) {
        val pX = xOf(xs, j)
        val pY = ys[j]
        val area = Math.abs((paX - avgX) * (pY - paY) - (paX - pX) * (avgY - paY))
        if (area > bestArea) {
          bestArea = area
          best = j
        }
      }
      out.add(best)
      a = best
    }
    out.add(n - 1)
    return out
  }

fun minMaxBuckets(values: List<Double>, buckets: Int): List<Double> {
    val n = values.length
    if (buckets <= 0 || n <= buckets * 2) {
      return values
    }
    val edges = bucketEdges(n, buckets)
    val out: MutableList<Double> = mutableListOf()
    for (b in 0 until buckets) {
      val start = edges[b]
      var end = edges[b + 1]
      if (end > n) {
        end = n
      }
      if (start >= end) {
        continue
      }
      var lo = values[start]
      var hi = values[start]
      for (i in start until end) {
        val v = values[i]
        if (v < lo) {
          lo = v
        }
        if (v > hi) {
          hi = v
        }
      }
      out.add(lo)
      out.add(hi)
    }
    return out
  }

fun binValues(values: List<Double>, count: Double): List<Bin> {
    val finite: MutableList<Double> = mutableListOf()
    for (v in values) {
      if (isFiniteNumber(v)) {
        finite.add(v)
      }
    }
    val out: MutableList<Bin> = mutableListOf()
    if (finite.length == 0) {
      return out
    }
    var lo = finite[0]
    var hi = finite[0]
    for (v in finite) {
      if (v < lo) {
        lo = v
      }
      if (v > hi) {
        hi = v
      }
    }
    val target = if (count < 1.0) 1.0 else count
    if (hi == lo) {
      out.add(Bin(x0 = lo, x1 = lo + 1.0, count = (finite.length).toDouble()))
      return out
    }
    val dom = niceDomain(Domain(min = lo, max = hi), target)
    val step = niceStep(((hi - lo)).toDouble() / (target).toDouble())
    val limit = 500
    var x0 = dom.min
    var k = 0
    while (x0 < dom.max - step * 0.000001 && k < limit) {
      out.add(Bin(x0 = x0, x1 = x0 + step, count = 0.0))
      x0 = x0 + step
      k = k + 1
    }
    if (out.length == 0) {
      out.add(Bin(x0 = dom.min, x1 = dom.max, count = 0.0))
    }
    val last = out.length - 1
    for (v in finite) {
      var idx = 0
      var edge = dom.min + step
      while (edge <= v && idx < last) {
        idx = idx + 1
        edge = edge + step
      }
      out[idx].count = out[idx].count + 1.0
    }
    return out
  }

fun binLabel(b: Bin): String = "${plain(b.x0)}–${plain(b.x1)}"
